-- shco_tips_updates.sql
-- Combined achieve_tips for all 408 SHCO Full OEs
-- Run in Supabase SQL Editor. Idempotent.

-- AAC (48 OEs)
update public.shco_full_oes set achieve_tips = '["Create a formal document listing all healthcare services offered by the department, aligned with community health needs identified through local disease burden data or patient demand records.","Conduct a community needs assessment annually and update the service list accordingly, keeping the rationale document available for assessor review.","Develop an SOP for periodic review of service relevance, ensuring department heads sign off on the service scope every year.","Train staff to articulate how each defined service addresses a specific community need so they can confidently respond during assessor interviews."]'::jsonb where oe_code = 'AAC.1.a';
update public.shco_full_oes set achieve_tips = '["Map each defined healthcare service to the qualified personnel available (by name and qualification), covering OPD, IPD, and emergency shifts, and keep this roster updated and accessible.","Ensure every service listed in the scope has a corresponding duty roster showing round-the-clock coverage, and display it prominently in each department.","Draft an SOP specifying the minimum staff qualifications and availability required to sustain each service, and cross-reference it with the HR register.","Prepare staff to explain their roles and qualifications for each service during assessor interviews, and maintain credential files readily accessible for inspection."]'::jsonb where oe_code = 'AAC.1.b';
update public.shco_full_oes set achieve_tips = '["Write a formal Scope of Services document for each department that lists the specific procedures, treatments, and diagnostics it offers, reviewed and signed by the department head.","Display the scope statement inside each department and include it in the department policy manual so staff know exactly what they are authorized to perform.","Develop an SOP requiring annual review of each department''s scope, with a version-control log documenting any changes made over time.","Ensure all staff in each department can describe the scope of their department during assessor interviews, supported by training records showing they were briefed on the document."]'::jsonb where oe_code = 'AAC.1.c';
update public.shco_full_oes set achieve_tips = '["Place prominent notice boards or signage at the hospital entrance and each department entrance listing the services available, in the primary language of the community served.","Ensure the service display is updated whenever a service is added or discontinued, with a dated change log maintained by administration.","Audit signage placements quarterly using a checklist to confirm visibility, readability, and accuracy, and document each audit with corrective actions if any.","Train front-desk and reception staff to direct patients using the displayed service information, so they can demonstrate this process during assessor observations."]'::jsonb where oe_code = 'AAC.1.d';
update public.shco_full_oes set achieve_tips = '["Document the patient registration and admission process in an SOP covering steps from patient arrival to bed allotment, and share it with all front-desk and ward staff.","Set up a registration desk with standardized forms or digital entry fields to capture all required patient information consistently at every encounter.","Conduct mock drills of the registration and admission process for new staff, recording attendance in training logs so competency is demonstrated to assessors.","Maintain a daily register or electronic log of all registrations and admissions, available for assessor review, showing the process is consistently followed."]'::jsonb where oe_code = 'AAC.2.a';
update public.shco_full_oes set achieve_tips = '["Configure the hospital information system (HIS) or manual register to automatically assign a unique identification number (UID) at the time each patient completes registration, without exception.","Audit a sample of patient records every month to confirm every entry has a UID, documenting audit findings and corrective actions taken when gaps are found.","Train registration staff specifically on the UID generation step, and have them demonstrate this during assessor observation of the registration workflow.","Display the UID on every document generated for that patient — OPD card, prescription, lab request, and discharge summary — so assessors can trace continuity through records."]'::jsonb where oe_code = 'AAC.2.b';
update public.shco_full_oes set achieve_tips = '["Create an SOP that requires the treating team or admissions staff to confirm service availability before formally accepting a patient, with a decision checklist for common scenarios.","Maintain a bed availability board or HIS dashboard visible to admissions staff so they can check capacity in real time before accepting in-patients.","Document cases where patients were redirected to other facilities, including the reason, to demonstrate a consistent, transparent decision process to assessors.","Train staff to communicate service limitations clearly and compassionately to patients, and include this communication skill in their induction training records."]'::jsonb where oe_code = 'AAC.2.c';
update public.shco_full_oes set achieve_tips = '["Develop and implement an SOP for managing patients when beds are unavailable, covering options such as waiting lists, referrals, and day-care alternatives.","Maintain a bed-management register or dashboard that records instances of non-availability and the action taken (referral, waiting room, etc.), reviewed weekly by the nursing supervisor.","Set up a clear escalation pathway — e.g., nurse informs duty doctor who contacts the medical officer — documented in writing so every staff member knows the steps.","Conduct quarterly reviews of bed-occupancy data to identify patterns of non-availability, and present corrective measures in meeting minutes to demonstrate proactive management."]'::jsonb where oe_code = 'AAC.2.d';
update public.shco_full_oes set achieve_tips = '["Implement a triage protocol at the point of entry (OPD and emergency) that categorizes patients by clinical urgency using a documented colour-coded or numeric triage scale.","Track triage-to-consultation time for each category in a daily register, and analyse monthly data to confirm that higher-priority patients consistently receive faster access.","Display triage category criteria at the triage station so staff can apply them consistently, and ensure assessors can observe the live triage process during their visit.","Present before-and-after data showing reduced wait times for high-priority patients since triage implementation, as evidence of measurable improvement in access prioritization."]'::jsonb where oe_code = 'AAC.2.e';
update public.shco_full_oes set achieve_tips = '["Develop an SOP for transfer-in and transfer-out that specifies documentation requirements, clinical stability criteria, mode of transport, and receiving facility communication steps.","Maintain a transfer register recording each transfer-in and transfer-out with the referral form, reason, receiving/sending facility, and patient outcome, available for assessor review.","Ensure transfer forms include the patient''s clinical summary, ongoing treatment, and contact details of the transferring doctor, and audit a sample monthly for completeness.","Train ward staff and emergency nurses on transfer protocols, documenting competency assessments, so they can describe the steps accurately during assessor interviews."]'::jsonb where oe_code = 'AAC.2.f';
update public.shco_full_oes set achieve_tips = '["Standardize initial assessment forms for OPD, IPD, day-care, and emergency separately, ensuring each form captures history, examination findings, and provisional diagnosis fields that staff must complete at first contact.","Audit patient records weekly to confirm initial assessments are documented for every encounter type, recording compliance rates and addressing gaps through targeted reminders or coaching.","Train all clinical staff (doctors and nurses) on the minimum dataset required in each initial assessment form, and keep training attendance records available for assessor review.","Allow assessors to observe live initial assessments in OPD or emergency to verify that the process matches the documented SOP, and brief staff in advance on what correct completion looks like."]'::jsonb where oe_code = 'AAC.3.a';
update public.shco_full_oes set achieve_tips = '["Add a care-plan section to the initial assessment form that requires the treating doctor to record the planned investigations, treatment, and goals of care before the patient moves to the next care stage.","Audit a random sample of 10 in-patient records each week to verify that a documented care plan follows every initial assessment, and record audit results for trend analysis.","Present aggregated data on care-plan completion rates to the quality committee monthly, showing improvement over time as evidence of measurable achievement.","Ensure nursing staff are trained to flag any in-patient file that lacks a care plan and escalate to the duty doctor for completion within a defined timeframe."]'::jsonb where oe_code = 'AAC.3.b';
update public.shco_full_oes set achieve_tips = '["Define reassessment intervals in the clinical SOP for each patient category — e.g., every 4 hours for ICU, every shift for general wards, each visit for OPD — and include these intervals in the nursing care plan template.","Conduct record audits biweekly to confirm reassessment notes are present at the defined intervals, recording findings in an audit register with corrective action taken.","Train nurses and resident doctors to document reassessment findings including response to treatment and any change in care plan, so records clearly show ongoing clinical decision-making.","Brief staff to explain the reassessment schedule and rationale to assessors during interviews, supported by patient records showing consistent reassessment documentation."]'::jsonb where oe_code = 'AAC.3.c';
update public.shco_full_oes set achieve_tips = '["Add a ''Next Follow-Up Date'' field to every OPD prescription or visit summary sheet, and make it a mandatory entry before the consultation is closed in the HIS or manual register.","Train OPD doctors and nurses to verbally inform patients of their follow-up date and hand them a written reminder slip, documenting this step in the visit record.","Audit a sample of OPD records monthly to confirm follow-up dates are recorded, tracking compliance rate and sharing results in departmental meetings.","Develop an SOP specifying which OPD patients require follow-up scheduling (post-procedure, chronic disease, paediatric cases, etc.) so staff apply the practice consistently."]'::jsonb where oe_code = 'AAC.3.d';
update public.shco_full_oes set achieve_tips = '["Implement an early warning scoring system (such as NEWS or MEWS) on all in-patient observation charts, with clearly defined trigger scores that require escalation to the duty doctor.","Develop an SOP specifying the response steps when a warning score is triggered — who to call, within how many minutes, and what to document — and post it in every ward.","Conduct quarterly drills simulating a deteriorating patient scenario, recording which staff participated and their performance, so competency evidence is available for assessors.","Maintain a register of early warning score activations and outcomes, reviewed monthly, to demonstrate the system is working and producing measurable reductions in late-recognition events."]'::jsonb where oe_code = 'AAC.3.e';
update public.shco_full_oes set achieve_tips = '["Prepare a written Scope of Laboratory Services document that lists all tests offered internally, aligned with the clinical services provided, reviewed and approved by the laboratory in-charge and medical director.","Cross-check the test menu against the clinical departments'' needs during each annual scope review, updating the document whenever a new clinical service is added or a test is discontinued.","Display the approved test menu at the lab reception so clinicians can verify availability, and maintain version-controlled copies in the quality manual for assessor inspection.","Train laboratory staff to articulate how the test menu supports each clinical department, so they can respond accurately during assessor interviews about scope alignment."]'::jsonb where oe_code = 'AAC.4.a';
update public.shco_full_oes set achieve_tips = '["Maintain an up-to-date equipment inventory list for the laboratory including make, model, capacity, and calibration status, cross-referenced against the test menu to confirm adequacy.","Keep a staff qualification register listing every laboratory technician and scientist with their educational credentials, registration details, and designated test responsibilities.","Conduct a gap analysis every six months comparing current infrastructure and staffing against the service scope, and document action plans for any identified shortfalls.","Ensure assessors can inspect the lab layout, equipment, and personnel register during visits; brief staff to explain how their qualification matches their assigned duties."]'::jsonb where oe_code = 'AAC.4.b';
update public.shco_full_oes set achieve_tips = '["Create SOPs for each specimen type covering requisition format, collection technique, labelling, transportation conditions, storage, processing, and biohazard disposal, and place them at every relevant workstation.","Conduct monthly compliance audits of specimen handling practices by observing staff and reviewing requisition forms, recording deviations and corrective actions in an audit log.","Train all laboratory and ward staff who handle specimens on these SOPs at induction and annually thereafter, maintaining signed training records accessible for assessors.","Use labelled specimen collection kits and pre-printed requisition forms to standardize the process, reducing errors; track error rates monthly as a quality indicator."]'::jsonb where oe_code = 'AAC.4.c';
update public.shco_full_oes set achieve_tips = '["Define turnaround times (TAT) for each test category in a policy document — routine, urgent, and STAT — and display the TAT commitment at the lab counter and in the service agreement with clinical departments.","Monitor actual TAT daily using a log or HIS report, comparing against the defined benchmarks, and present TAT compliance data in the monthly quality meeting.","Investigate and document every TAT breach, identifying root causes (equipment failure, specimen issues, staffing) and implementing corrective actions to prevent recurrence.","Train laboratory staff on the TAT targets for their work area, and have them demonstrate how they prioritize urgent samples during assessor observation of lab workflow."]'::jsonb where oe_code = 'AAC.4.d';
update public.shco_full_oes set achieve_tips = '["Define the list of critical laboratory values in a written policy, specifying the exact thresholds that trigger immediate notification and the maximum time allowed to reach the clinician.","Maintain a critical results register recording every critical value reported — date, time, test, value, staff who notified, clinician who received, and time of receipt — available for assessor review.","Train laboratory staff to follow a read-back protocol when reporting critical values by phone, and document the read-back confirmation in the register to ensure accuracy.","Audit the critical results register monthly to confirm all entries are complete and notification timelines were met, presenting compliance data in quality meetings."]'::jsonb where oe_code = 'AAC.4.e';
update public.shco_full_oes set achieve_tips = '["Maintain an approved vendor list for outsourced laboratory tests, selecting only laboratories with accreditation (NABL or equivalent) or a documented quality assurance system, reviewed annually.","Create an SOP for outsourcing that defines the process for sending samples, receiving reports, turnaround time expectations, and handling discrepant or delayed results.","Keep copies of quality certificates and agreements with each outsourced lab in a vendor file, available for assessors to inspect as evidence of due diligence.","Record all outsourced tests in a register with dates, test names, outsourced lab name, and report receipt dates, enabling trend monitoring and vendor performance review."]'::jsonb where oe_code = 'AAC.4.f';
update public.shco_full_oes set achieve_tips = '["Develop and implement a written laboratory quality assurance programme covering internal quality control (IQC), external quality assessment (EQA), corrective actions, and periodic review cycles.","Maintain IQC records for each analyser showing daily control runs, results against acceptable ranges, and any corrective action taken when controls are out of range.","Enrol in an external quality assessment scheme and file EQA reports, certificates, and any remedial actions in the QA programme folder for assessor inspection.","Assign a laboratory quality coordinator to review the QA programme monthly, document findings in meeting minutes, and present a quarterly summary to the medical director."]'::jsonb where oe_code = 'AAC.4.g';
update public.shco_full_oes set achieve_tips = '["Maintain a calibration and preventive maintenance schedule for every laboratory instrument, listing the frequency, responsible person, and due dates, displayed visibly in the lab.","Record each calibration and maintenance activity in an equipment logbook immediately after completion, noting the engineer''s name, findings, and next due date.","Set up calendar-based reminders (electronic or physical) for upcoming calibration and maintenance events so no equipment misses its scheduled service.","Conduct a monthly review of the equipment logbooks to confirm all activities are on schedule, and document any overdue maintenance with the reason and corrective plan."]'::jsonb where oe_code = 'AAC.4.h';
update public.shco_full_oes set achieve_tips = '["Compile and maintain all statutory imaging licences and regulatory approvals (AERB registration, PCB consent, etc.) in a dedicated compliance file, checking renewal dates every six months.","Post copies of current licences at the imaging department entrance so they are immediately visible to assessors during inspection.","Develop a compliance calendar listing all regulatory renewal deadlines for the imaging department, with responsibility assigned to a named staff member, reviewed quarterly.","Train the radiology in-charge to explain all applicable legal requirements during assessor interviews, supported by the compliance file showing current, unexpired documents."]'::jsonb where oe_code = 'AAC.5.a';
update public.shco_full_oes set achieve_tips = '["Prepare a written Scope of Imaging Services document listing all modalities and procedures offered, cross-referenced against the clinical services of the organization, reviewed annually by the radiology in-charge.","Ensure the imaging scope is aligned with the equipment available and radiologist expertise; note any gaps and document the plan to address them.","Display the approved imaging service list at the radiology reception desk for patient and clinician reference, updating it whenever services change.","Train imaging staff to explain how the scope of services matches the organization''s clinical needs during assessor interviews, using the scope document as evidence."]'::jsonb where oe_code = 'AAC.5.b';
update public.shco_full_oes set achieve_tips = '["Maintain an equipment inventory for the imaging department with details of each modality, installation date, capacity, and maintenance status, updated at least quarterly.","Keep a staffing register listing radiologists, radiographers, and technicians with their qualifications, registrations, and assigned modalities to demonstrate adequate human resources.","Conduct a six-monthly gap analysis comparing equipment and staffing against the defined imaging scope, documenting corrective plans for any identified deficiencies.","Ensure assessors can tour the imaging area and review both the equipment and staffing registers during their visit; brief staff to explain how resources match the scope."]'::jsonb where oe_code = 'AAC.5.c';
update public.shco_full_oes set achieve_tips = '["Define a standardized report format for imaging results, including patient identification, clinical indication, findings, impression, and radiologist signature, and implement it across all modalities.","Set and document turnaround time targets for each imaging category (routine, urgent, emergency) in a policy, and track actual TAT daily using a report log or HIS data.","Monitor TAT compliance monthly, presenting data to the quality meeting with trend charts, and identify bottlenecks causing delays for targeted corrective action.","Train radiographers and radiologists on the standardized reporting format and TAT expectations, keeping training records available, so staff can demonstrate compliance during assessor review."]'::jsonb where oe_code = 'AAC.5.d';
update public.shco_full_oes set achieve_tips = '["Define critical imaging findings (e.g., pneumothorax, intracranial bleed, aortic dissection) in a written policy with the maximum notification time allowed after identification.","Maintain a critical imaging results register recording every instance — study date, finding, notifying radiologist, referring clinician, time of notification, and read-back confirmation.","Train all radiologists and radiographers to follow the immediate notification protocol the moment a critical finding is identified, and to document notification in the register before ending the study.","Audit the critical imaging register monthly to verify all notifications occurred within the defined timeframe, and report compliance rates to the quality committee."]'::jsonb where oe_code = 'AAC.5.e';
update public.shco_full_oes set achieve_tips = '["Maintain an approved outsourced imaging vendor list that includes only providers with documented quality systems or accreditation, updated at least annually with supporting certificates.","Create an SOP for outsourcing imaging studies, specifying how requests are sent, how reports are received, TAT expectations, and the process for handling delayed or unclear reports.","Keep a register of all outsourced imaging studies with dates, modality, outsourced centre name, and date of report receipt, enabling vendor performance monitoring.","File agreements and quality documents for each outsourced imaging centre in a vendor folder readily accessible to assessors during inspection."]'::jsonb where oe_code = 'AAC.5.f';
update public.shco_full_oes set achieve_tips = '["Develop a written imaging quality assurance programme covering repeat-rate monitoring, dose optimization, image reject analysis, equipment performance testing, and periodic review cycles.","Track the imaging repeat/reject rate monthly by modality, investigate causes exceeding the acceptable threshold, and document corrective actions in the QA log.","Assign a radiology quality lead to review QA data monthly and present a summary report to the medical director, with minutes kept as evidence of the programme running actively.","Train all imaging staff on QA programme components relevant to their role, maintaining signed training records so staff can accurately describe the programme during assessor interviews."]'::jsonb where oe_code = 'AAC.5.g';
update public.shco_full_oes set achieve_tips = '["Establish a structured internal peer-review process where a sample of imaging reports (minimum 5-10% per month) is reviewed by a second radiologist against the original report for concordance.","Participate in an external peer-review or teleradiology audit programme at least annually, retaining reports and feedback letters in the QA folder as documented evidence.","Record all peer-review findings — concordant, minor discordant, major discordant — in a tracking register, and analyse trends quarterly to identify systematic reporting errors.","Present before-and-after data showing improved concordance rates or reduced major discordances following protocol changes, as measurable evidence of quality improvement from the peer-review programme."]'::jsonb where oe_code = 'AAC.5.h';
update public.shco_full_oes set achieve_tips = '["Build a calibration and preventive maintenance schedule for all imaging equipment into the biomedical engineering calendar, listing frequency, responsible engineer, and due dates for each machine.","Record every calibration and maintenance event in an equipment logbook the same day it occurs, noting engineer name, activity performed, results, and next scheduled date.","Display a visible maintenance status sticker or tag on each imaging machine showing the last service date and next due date, enabling quick assessor verification.","Review equipment logbooks monthly to confirm all scheduled maintenance is on track, and document any overdue servicing with a reason and revised completion plan."]'::jsonb where oe_code = 'AAC.5.i';
update public.shco_full_oes set achieve_tips = '["Document the laboratory safety programme in a written policy covering biohazard handling, spill management, fire safety, sharp disposal, PPE use, and emergency procedures, available at every workstation.","Conduct quarterly safety drills (spill cleanup, fire evacuation, needlestick response) and record attendance and outcomes in a safety drill register for assessor review.","Display safety protocols — biohazard labelling, PPE requirements, spill procedure charts — at relevant workstations, and inspect these displays during monthly safety rounds.","Train all laboratory staff on the safety programme at induction and annually, issuing and documenting competency sign-offs so assessors can verify training completion through records."]'::jsonb where oe_code = 'AAC.6.a';
update public.shco_full_oes set achieve_tips = '["Provide each laboratory staff member with appropriate PPE (gloves, lab coat, eye protection, mask) relevant to their work area, and record the issue in a PPE distribution register.","Conduct annual competency assessments on safe laboratory practices including correct PPE use, hand hygiene, and sharps disposal, documenting results and any remedial training given.","Post safe-practice quick-reference guides at every bench, including steps for needlestick injuries, chemical exposure, and aerosol-generating procedures, and update them whenever protocols change.","Train staff to demonstrate correct PPE donning and doffing and emergency response steps during assessor observations, supported by signed training records in their personnel file."]'::jsonb where oe_code = 'AAC.6.b';
update public.shco_full_oes set achieve_tips = '["Develop a pre-imaging safety screening checklist (covering contraindications such as metallic implants for MRI, pregnancy, allergy history for contrast, renal function for contrast CT) and make it mandatory before every imaging procedure.","Train radiographers to administer the screening checklist verbally and in writing, recording the completed checklist in the patient''s imaging request file for every study.","Audit compliance with pre-imaging screening monthly by reviewing a sample of imaging request files, tracking the percentage of studies with a completed checklist and addressing gaps.","Ensure assessors can observe the screening process in action during a live imaging session and review completed checklists in the records to verify consistent implementation."]'::jsonb where oe_code = 'AAC.6.c';
update public.shco_full_oes set achieve_tips = '["Issue TLD badges or OSL dosimeters to all imaging personnel with radiation exposure, maintain a dosimetry register, and submit badges for reading on schedule, filing results in individual staff dose records.","Post radiation safety warning signs (''Caution: Radiation Area'', pregnancy advisory) at all access points to imaging rooms, and inspect their presence during monthly safety audits.","Develop and implement a radiation safety SOP covering ALARA principles, controlled area rules, use of lead aprons and shields, and patient shielding procedures, with staff trained at induction.","Conduct annual radiation safety refresher training for all imaging staff and radiologists, documenting attendance and assessment results so competency can be verified by assessors."]'::jsonb where oe_code = 'AAC.6.d';
update public.shco_full_oes set achieve_tips = '["Map all required imaging signage locations (entrance warnings, no-entry during exposure, pregnancy caution, radiation hazard symbol) and create a signage placement plan document for the department.","Install compliant signage at every required location and photograph placements to create a baseline reference; repeat photo-audit quarterly to confirm signage remains intact and legible.","Assign the radiology in-charge responsibility for a monthly signage inspection using a checklist, and document findings with corrective actions when signs are missing or damaged.","Brief assessors on the signage plan and walk them through the imaging area, demonstrating how each sign relates to the specific safety requirement it addresses."]'::jsonb where oe_code = 'AAC.6.e';
update public.shco_full_oes set achieve_tips = '["Create and maintain a duty assignment list or care-responsibility matrix for each unit showing, by shift, which qualified doctor or nurse is responsible for each patient, updated at every handover.","Document the responsible clinician''s name in the patient''s bedside chart or electronic record so any care provider can identify the accountable individual at a glance.","Develop an SOP specifying that a named responsible clinician must be documented for every patient within one hour of admission or phase-of-care transition, with nursing supervisors monitoring compliance.","Brief assessors by walking them to a patient''s bedside and demonstrating how staff identify the responsible clinician from the chart and assignment board, reinforcing with training records."]'::jsonb where oe_code = 'AAC.7.a';
update public.shco_full_oes set achieve_tips = '["Implement a structured multidisciplinary communication tool (such as SBAR) for sharing patient updates between doctors, nurses, and allied health staff, embedding it in the progress note and handover format.","Maintain a referral and consultation register that tracks inter-department referrals, the requesting doctor, the responding consultant, date and time, and the clinical response received.","Conduct biweekly multidisciplinary team (MDT) meetings for complex patients, documenting attendance and decisions in the patient''s record and in meeting minutes kept by the unit.","Train all care-providing staff on information-sharing expectations and tools, keeping training records, so they can demonstrate the communication pathway clearly during assessor interviews."]'::jsonb where oe_code = 'AAC.7.b';
update public.shco_full_oes set achieve_tips = '["Adopt a standardized handover tool (SBAR or ISOBAR) and embed it in a printed or electronic handover form that all nursing and medical staff must complete at the end of every shift.","Establish a dedicated handover time and location for each ward, ensuring outgoing and incoming staff overlap for a minimum defined period to allow face-to-face verbal and written handover.","Maintain completed handover forms for at least 30 days so assessors can audit a sample, verifying that handovers are being done consistently across all shifts and departments.","Conduct direct observation of handovers monthly by nursing supervisors, scoring against the standardized tool criteria and documenting findings to demonstrate ongoing compliance."]'::jsonb where oe_code = 'AAC.7.c';
update public.shco_full_oes set achieve_tips = '["Develop an SOP for intra-hospital transfer that specifies pre-transfer clinical assessment, minimum monitoring required en route, accompanying staff level, and documentation to be completed before transfer.","Use a dedicated intra-hospital transfer checklist completed by the nurse and doctor before every transfer, retained in the patient''s file as evidence of safe practice.","Ensure transport equipment (portable monitor, oxygen, emergency kit) is maintained in working order with a daily check log, so readiness is demonstrated to assessors through records.","Train ward nurses and doctors on intra-hospital transfer protocols annually, documenting attendance and competency assessments in personnel training files for assessor review."]'::jsonb where oe_code = 'AAC.7.d';
update public.shco_full_oes set achieve_tips = '["Develop an SOP mandating that a discharge summary be completed and handed to the patient or carer at the time of discharge for all patients, including those leaving against medical advice (LAMA).","Create a LAMA-specific discharge summary template capturing the patient''s refusal, clinical status at time of leaving, advice given, and signature or refusal to sign, filed in the patient''s record.","Audit 100% of discharged patient files weekly to confirm a discharge summary is present and was handed to the patient, recording compliance in a tracker reviewed by the nursing supervisor.","Train all ward doctors on the discharge summary requirement at induction and in annual refreshers, and brief them to demonstrate the process with a sample record during assessor interviews."]'::jsonb where oe_code = 'AAC.8.a';
update public.shco_full_oes set achieve_tips = '["Design the discharge summary template to include mandatory fields for patient name, UID, date of admission, and date of discharge, configured in HIS or pre-printed on paper forms so fields cannot be skipped.","Audit a random sample of 20 discharge summaries weekly to confirm all four demographic fields are correctly and legibly filled, logging audit results for trend analysis.","Train ward clerks and doctors on the importance of accurate patient identification in the discharge summary, with a specific reminder about UID entry as a core patient safety requirement.","Ensure nursing supervisors perform a spot-check of the demographic section before discharge summary is handed to the patient, documenting this verification step in the patient''s file."]'::jsonb where oe_code = 'AAC.8.b';
update public.shco_full_oes set achieve_tips = '["Standardize the clinical content section of the discharge summary template to include mandatory fields for reason for admission, significant findings, diagnosis, condition at discharge, investigations, procedures, medications, and treatments, ensuring completeness before finalization.","Train resident doctors and medical officers to complete each clinical field accurately at the time of discharge, not retrospectively, with a ''complete before patient leaves'' policy enforced by nursing supervisors.","Conduct monthly medical record audits reviewing 15-20 discharge summaries for completeness of clinical content, scoring each field, and presenting results to the medical audit committee.","Provide doctors with a discharge summary completion checklist they can use as a quick self-audit before signing, reducing omissions and improving consistency assessed by auditors."]'::jsonb where oe_code = 'AAC.8.c';
update public.shco_full_oes set achieve_tips = '["Add a dedicated section in the discharge summary template for follow-up appointment details, prescribed medications with dose and duration, dietary advice, activity restrictions, and warning symptoms, written in plain language the patient can understand.","Train doctors and nurses to explain the follow-up and medication section verbally to patients and caregivers at discharge, confirming understanding using a teach-back method and documenting it.","Audit discharge summaries monthly to verify the follow-up advice section is complete and written in patient-understandable language, tracking the percentage meeting the standard.","Develop a discharge instruction checklist that nursing staff use and sign off before the patient leaves, filed in the patient record, demonstrating this step is performed consistently."]'::jsonb where oe_code = 'AAC.8.d';
update public.shco_full_oes set achieve_tips = '["Add an ''Urgent Care Guidance'' section to the discharge summary template specifying warning signs that require emergency return (e.g., fever above 38.5C, wound bleeding, breathlessness) and the contact number or location to go to.","Train doctors to complete the urgent care instructions section using condition-specific examples, and use the IPASS or similar structured format to make the guidance clear and reproducible.","Audit a sample of discharge summaries each month to confirm the urgent care instructions section is present and contains specific, actionable guidance rather than generic statements.","Present data on the percentage of discharge summaries containing specific urgent care guidance over successive quarters, demonstrating a sustained improvement trend as measurable evidence."]'::jsonb where oe_code = 'AAC.8.e';
update public.shco_full_oes set achieve_tips = '["Add a mandatory cause-of-death field to the in-patient death summary template, requiring the immediate cause, underlying cause, and contributing conditions in line with ICD coding principles.","Create an SOP specifying that for every in-patient death, a death summary must be completed by the treating doctor within 24 hours, countersigned by the duty medical officer.","Maintain a death register with the UID, cause of death, certifying doctor, and date of summary completion, reviewed monthly by the medical superintendent for completeness.","Audit all death summaries quarterly to confirm cause of death is documented accurately and consistently, reporting findings to the quality committee with corrective action for any gaps found."]'::jsonb where oe_code = 'AAC.8.f';
update public.shco_full_oes set achieve_tips = '["Implement a planned discharge date system where the treating team sets an expected discharge date at or shortly after admission, records it in the patient''s file, and reviews it daily during ward rounds.","Develop a pre-discharge assessment checklist covering medication readiness, patient education completion, follow-up appointment booking, transport arrangement, and any special post-discharge needs, completed 24 hours before planned discharge.","Track planned versus actual discharge dates monthly to calculate discharge variance rates, and use the data to identify and address systemic causes of delayed discharge.","Identify patients with special post-discharge needs (home nursing, physiotherapy, social support, palliative care) at the care-planning stage, documenting referrals made and arrangements confirmed before discharge as measurable evidence of proactive planning."]'::jsonb where oe_code = 'AAC.8.g';

-- COP (82 OEs)
update public.shco_full_oes set achieve_tips = '["Implement a two-identifier wristband system (name + date of birth or MR number) and verify both identifiers before every procedure, medication administration, and sample collection.","Train all nursing and clinical staff to verbally confirm two patient identifiers at each care handover point and document the verification in the patient record at every shift.","Conduct unannounced spot-checks by the nursing supervisor to observe whether staff consistently use two identifiers before performing any clinical task, and record observations in the audit log.","During assessor visits, demonstrate identification records in patient files, walk assessors through the wristband verification workflow, and allow staff interviews to confirm daily practice."]'::jsonb where oe_code = 'COP.1.a';
update public.shco_full_oes set achieve_tips = '["Compile a master list of all applicable laws and regulations governing patient care (PCPNDT, MTP Act, Bio-Medical Waste Rules, etc.) and assign a compliance officer to track amendments and update SOPs accordingly.","Create an SOP for each regulatory requirement and display a compliance calendar in the nursing station that flags upcoming renewal deadlines for licenses and registrations.","Train all department heads in relevant statutory obligations during induction and annually thereafter, maintaining signed attendance records as audit-ready evidence.","Conduct a quarterly internal compliance audit comparing actual practice against regulatory requirements, document findings, and record corrective actions taken within defined timelines."]'::jsonb where oe_code = 'COP.1.b';
update public.shco_full_oes set achieve_tips = '["Identify the top 10 clinical conditions treated in the hospital, adopt national or international evidence-based guidelines for each (e.g., WHO, IAP, MoHFW), and keep printed or digital copies accessible in relevant departments.","Form a clinical protocol committee that meets quarterly to review, update, and formally approve protocols, documenting meeting minutes and version-controlled protocol registers.","Measure adherence to each protocol monthly using clinical audit tools, display compliance rates on departmental dashboards, and link findings to clinical improvement plans.","Before assessor visits, prepare a protocol adherence report showing before-and-after outcomes data (e.g., antibiotic compliance rates, mortality rates) to demonstrate evidence-based impact."]'::jsonb where oe_code = 'COP.1.c';
update public.shco_full_oes set achieve_tips = '["Map all care settings where the same clinical condition is treated (OPD, ward, day-care) and develop a single standardised care pathway or protocol applicable across all those settings.","Create SOPs that specify the same clinical steps, monitoring parameters, and documentation templates regardless of care setting, and distribute them to all relevant departments.","Train staff in every care setting on the unified pathway through monthly in-service sessions and retain attendance sheets and competency assessment records as evidence.","Conduct monthly cross-departmental audits comparing patient records from different settings for the same condition to confirm uniform care delivery and document audit findings."]'::jsonb where oe_code = 'COP.1.d';
update public.shco_full_oes set achieve_tips = '["Draft a written telemedicine policy aligned with the Telemedicine Practice Guidelines 2020 that specifies eligible services, technology platforms, consent requirements, and data security standards.","Set up a secure, encrypted telemedicine platform, train consulting doctors in its use, and maintain a session log for every telemedicine consultation conducted.","Obtain written or electronic consent from patients before each telemedicine encounter, store consent records in the patient file, and document clinical advice given during the session.","Review telemedicine session records quarterly for quality, check that documentation is complete, and report any technical or clinical concerns to the medical committee for corrective action."]'::jsonb where oe_code = 'COP.1.e';
update public.shco_full_oes set achieve_tips = '["Designate a clearly marked emergency reception area at the main entrance with unobstructed ambulance access, and equip it with a resuscitation trolley, defibrillator, oxygen, suction, and essential emergency drugs at all times.","Develop and display a written SOP defining the layout, staff deployment, and equipment checklist for the emergency area, and conduct daily equipment checks with a signed log.","Train all emergency staff in basic life support (BLS) and Advanced Cardiac Life Support (ACLS) protocols, and maintain training certificates with next due-date tracking in personnel files.","Conduct a monthly unannounced drill to test response times and resource availability in the emergency area, document outcomes, and implement corrective actions before the next drill."]'::jsonb where oe_code = 'COP.2.a';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP for managing medico-legal cases (MLCs) that covers mandatory reporting to police, documentation of injuries, evidence preservation, and liaison with legal authorities as required by law.","Ensure that every MLC patient receives emergency stabilisation before any paperwork is initiated — document the time of arrival, first intervention, and MLC registration number in the patient record.","Train all emergency doctors and nurses on MLC procedures during induction and annually, maintaining attendance and competency records; display a quick-reference MLC flowchart at the nursing station.","Conduct quarterly record audits of MLC case files to verify that all statutory fields are completed, police intimation letters are on file, and clinical documentation is accurate and timely."]'::jsonb where oe_code = 'COP.2.b';
update public.shco_full_oes set achieve_tips = '["Implement a validated triage tool (e.g., Modified Early Warning Score or colour-coded triage categories) and display the triage criteria at the emergency reception desk for all incoming staff to reference.","Train all emergency nurses and doctors in triage protocols and document their competency assessment scores; conduct quarterly triage simulation exercises and record outcomes.","Record every patient''s triage category, triage time, and name of the triaging staff member in the emergency register or electronic system immediately upon patient arrival.","Audit triage documentation monthly to check that response times for each triage category meet defined targets, report non-compliances to the emergency department in-charge, and track improvement over three months."]'::jsonb where oe_code = 'COP.2.c';
update public.shco_full_oes set achieve_tips = '["Define in the emergency SOP the maximum acceptable intervals between reassessments for each triage category (e.g., every 15 minutes for high-acuity patients) and make it a mandatory documentation requirement.","Set up a structured reassessment form or EMR field that nursing staff complete at each defined interval, capturing vital signs, pain score, and any change in clinical status.","Brief all emergency nursing staff at the start of each shift on current waiting patients and their reassessment due times, and assign a dedicated nurse to track and flag overdue reassessments.","Review ten random emergency patient files each month to verify that reassessment entries are present at the required intervals and escalate missing entries to the nursing supervisor for follow-up."]'::jsonb where oe_code = 'COP.2.d';
update public.shco_full_oes set achieve_tips = '["Create a standardised admission-discharge-transfer (ADT) form for the emergency department that captures reason for admission or discharge, clinical status at the time of decision, follow-up instructions, and responsible doctor''s signature.","Establish a policy that no patient leaves the emergency without a written discharge note containing diagnosis, treatment given, warning signs to watch for, and next-appointment details, signed by the treating doctor.","Train all emergency doctors and nurses to complete ADT documentation before the patient physically leaves the area, and verify compliance through daily charge-nurse checklist sign-offs.","Conduct a monthly review of ten emergency discharge records to confirm that all mandatory fields including the patient-copy discharge note are complete, and report compliance rates to the emergency committee."]'::jsonb where oe_code = 'COP.2.e';
update public.shco_full_oes set achieve_tips = '["Identify at least five measurable quality indicators for the emergency department (e.g., triage-to-doctor time, LAMA rate, re-visit within 48 hours, cardiac arrest survival rate) and begin collecting baseline data immediately.","Display monthly indicator dashboards in the emergency department and review them in a multidisciplinary quality meeting, documenting meeting minutes and agreed action points.","Set improvement targets for each indicator based on baseline data, implement corrective actions (e.g., staffing changes, protocol revisions), and track progress over three consecutive months.","Compile a before-and-after evidence file showing indicator trends, corrective actions taken, and measurable outcomes to present to assessors as proof of a functioning quality assurance programme."]'::jsonb where oe_code = 'COP.2.f';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP for managing Brought Dead (BD) and patients who die within minutes of arrival, covering documentation requirements, police intimation, MLC registration, body handling, and family notification steps.","Display the BD management flowchart at the emergency nursing station and brief all incoming shift staff on the procedure during daily handovers.","Train emergency doctors and nurses in the BD protocol during induction and conduct a mock exercise annually; retain attendance records and exercise debrief notes.","Audit all BD cases monthly to verify that all documentation requirements were met within specified timeframes, and report any gaps to the emergency in-charge for immediate corrective action."]'::jsonb where oe_code = 'COP.2.g';
update public.shco_full_oes set achieve_tips = '["Document a formal ambulance services agreement or in-house ambulance operational policy that specifies response time commitments, vehicle specifications, equipment list, and communication protocols.","Maintain a daily ambulance readiness log signed by the in-charge that confirms the vehicle is functional, fuel levels are adequate, and emergency equipment is in place before each shift.","Establish a memorandum of understanding (MoU) with at least one external ambulance provider if the hospital does not own an ambulance, and keep the MoU current and accessible during assessments.","Record all ambulance call-outs including dispatch time, arrival time, and patient handover time; review these records monthly to identify delays and implement corrective measures."]'::jsonb where oe_code = 'COP.2.h';
update public.shco_full_oes set achieve_tips = '["Prepare a written ambulance equipment checklist aligned with the ALS or BLS standard appropriate to the hospital''s scope, verify it daily, and have the ambulance in-charge sign the checklist log every shift.","Ensure ambulance personnel hold a valid BLS or ACLS certificate and a valid driving licence; maintain photocopies of all certificates in the personnel file and track renewal dates.","Conduct an unannounced monthly check of the ambulance to confirm that emergency medications (adrenaline, IV fluids, etc.) are within expiry, quantities are adequate, and the cold chain is maintained for temperature-sensitive drugs.","Run a quarterly ambulance response drill, measuring the time from call to vehicle departure; document results and use findings to address gaps in readiness or crew training."]'::jsonb where oe_code = 'COP.2.i';
update public.shco_full_oes set achieve_tips = '["Establish a pre-hospital coordination protocol that allows the ambulance crew to radio or call ahead with patient vitals, suspected diagnosis, and ETA so that the emergency team can prepare the resuscitation bay in advance.","Train ambulance staff to initiate basic interventions (IV access, oxygen, ECG, first-dose medications) per written standing orders while in transit, and document all actions on a pre-hospital care record.","Equip the ambulance with a telemedicine-capable device or direct phone link to the on-call emergency doctor so that treatment can be guided remotely during transport.","Review all pre-hospital care records monthly for completeness and quality of interventions; benchmark door-to-treatment times for cases where pre-hospital care was initiated against those where it was not."]'::jsonb where oe_code = 'COP.2.j';
update public.shco_full_oes set achieve_tips = '["Develop a formal Disaster Management Plan (DMP) covering mass casualty incidents, fire, epidemic outbreaks, and chemical exposures; define roles for each staff category and maintain the plan in a binder accessible to all emergency staff.","Conduct at least two mock disaster drills per year — one announced and one unannounced — covering different scenarios, and document participant roles, response times, and debrief findings.","Establish communication protocols with local government health authorities, nearby hospitals, and the police for coordinated disaster response; keep contact directories updated and test communication links quarterly.","Maintain a surge-capacity plan that specifies how the hospital will expand beds, procure additional supplies, and redeploy staff during a community emergency, and review the plan after each drill or real event."]'::jsonb where oe_code = 'COP.2.k';
update public.shco_full_oes set achieve_tips = '["Create a written resuscitation policy that mandates an assigned resuscitation team on every shift with defined roles (team leader, airway, compressions, medications, recorder) and post the team roster visibly in each ward and critical area.","Ensure crash carts are stocked, sealed, and strategically located in all patient care areas; have the nursing in-charge inspect and sign the crash cart checklist daily and after every use.","Train all clinical staff in BLS at induction and refresher ACLS/PALS for relevant staff annually; maintain valid certification copies in personnel files and track expiry dates on a shared calendar.","Conduct quarterly unannounced Code Blue drills in different locations of the hospital, time the team''s response from activation to first shock or drug administration, and document results with follow-up action plans."]'::jsonb where oe_code = 'COP.3.a';
update public.shco_full_oes set achieve_tips = '["Design a standardised CPR event record form that captures exact timings of each intervention, drug doses given, defibrillation attempts, and team members present; make this form mandatory for every resuscitation event.","Assign a dedicated recorder role during every CPR event whose sole responsibility is to document real-time entries on the event record form, ensuring no intervention goes unlogged.","Conduct a post-resuscitation debrief within 24 hours of every CPR event, using the event record to review team performance; document debrief findings and share them with the multidisciplinary committee.","During assessor visits, produce the CPR event register showing all resuscitation events, corresponding documentation forms, and evidence of role compliance during each event to demonstrate systematic recording practices."]'::jsonb where oe_code = 'COP.3.b';
update public.shco_full_oes set achieve_tips = '["Create a crash cart placement map for the hospital that identifies the location, content list, and responsible department for every cart; display this map in each nursing station and the security office.","Implement a daily crash cart checklist system: the nursing in-charge verifies contents, checks drug expiry dates, tests the defibrillator, and signs the logbook before the first patient contact of the day.","After any use of the crash cart (or any seal break), replenish and re-seal it within one hour and document the replenishment time, names of drugs replaced, and staff responsible in the crash cart log.","Perform a quarterly inventory audit of all crash carts across the hospital and present the compiled audit records to the quality committee, highlighting any gaps and corrective actions taken."]'::jsonb where oe_code = 'COP.3.c';
update public.shco_full_oes set achieve_tips = '["Constitute a multidisciplinary CPR review committee (including the medical director, nursing head, and anaesthesiologist) with a written terms of reference, and schedule meetings within 72 hours of any resuscitation event.","Use a standardised post-event analysis template (covering patient factors, system factors, team response, and outcome) during committee review meetings, and archive completed templates for each event.","Translate committee findings into specific corrective actions (e.g., equipment upgrades, retraining, protocol revisions), assign owners with deadlines, and track completion status at the next meeting.","Compile quarterly CPR outcome data (survival to discharge rate, response time, documentation completeness) and present trends to hospital leadership to demonstrate a culture of continuous improvement."]'::jsonb where oe_code = 'COP.3.d';
update public.shco_full_oes set achieve_tips = '["Ensure every nursing shift begins with a structured patient handover that includes current clinical status, active nursing care plan, pending investigations, and patient-specific alerts documented in a standardised handover record.","Use a unified nursing care plan template in the patient record that links nursing assessments, interventions, and outcomes directly to the treating physician''s management plan, updated at least once per shift.","Conduct monthly nursing record audits selecting ten random in-patient files to verify that nursing entries are timely, legible, complete, and aligned with medical orders, reporting compliance rates to the nursing head.","Allow assessors to observe actual nursing handovers and interview bedside nurses about care planning steps; maintain a nursing procedure log that documents all nursing interventions with time, nurse signature, and patient response."]'::jsonb where oe_code = 'COP.4.a';
update public.shco_full_oes set achieve_tips = '["Develop a written nursing assignment policy based on nurse-to-patient ratios recommended by current guidelines (e.g., NMC norms) and adjust ratios for high-dependency areas such as ICU, OT, and labour room.","Maintain daily nursing deployment sheets that record the nurse-to-patient ratio achieved on each shift in each ward; retain these sheets for at least one year as compliance evidence.","Train charge nurses on competency-based assignment principles and document their training; ensure that nurses with specialised skills (e.g., IV therapy, wound care) are preferentially assigned to patients needing those skills.","Review nursing assignment records monthly to identify recurrent ratio shortfalls and escalate staffing gaps to HR and hospital management with documented recommendations for resolution."]'::jsonb where oe_code = 'COP.4.b';
update public.shco_full_oes set achieve_tips = '["Conduct a biannual nursing equipment needs assessment for each department; maintain an equipment inventory register that tracks item name, quantity, condition, calibration due date, and last maintenance date.","Establish a process for nurses to report non-functioning equipment using a written equipment fault report; set a defined turnaround time for repair or replacement and track resolution times in the maintenance log.","Ensure consumables (syringes, IV lines, dressings, gloves) are stocked to a minimum par level in each ward and replenished daily; assign a named nurse to verify and document stock levels each morning.","During mock assessments or peer audits, verify that nursing staff can readily access and demonstrate proficiency on all critical equipment in their area, and document the outcome of these observations."]'::jsonb where oe_code = 'COP.4.c';
update public.shco_full_oes set achieve_tips = '["Form a nursing practice committee responsible for identifying, adopting, and periodically revising nursing clinical practice guidelines aligned with standards from professional bodies such as the Indian Nursing Council.","Document adopted nursing guidelines in a numbered, version-controlled format with effective and review dates, and store them in an accessible guideline binder or digital repository in each nursing unit.","Conduct nursing staff training on each new or revised guideline within 30 days of adoption, assess comprehension with a written or practical test, and retain training and assessment records in staff files.","Measure guideline adherence through quarterly nursing audits and report compliance rates to the nursing committee; show trend data to assessors as evidence that guidelines are implemented and continuously improved."]'::jsonb where oe_code = 'COP.4.d';
update public.shco_full_oes set achieve_tips = '["Develop an SOP for transfusion services that covers blood ordering, compatibility testing, storage, issue, administration, and reaction management, and ensure it references all applicable regulations (Drugs and Cosmetics Act, NBTC guidelines).","Create a pre-transfusion checklist embedded in the patient record that includes blood group verification, crossmatch result, compatibility label check, and double-nurse identification sign-off before each transfusion unit is hung.","Train all nursing and laboratory staff involved in transfusion services on the SOP at induction and annually; maintain training attendance and competency assessment records in each staff member''s file.","Review transfusion records monthly to verify that pre-transfusion checklists are complete for every unit transfused and that all applicable legal documentation (consent, crossmatch report, transfusion record) is present in the patient file."]'::jsonb where oe_code = 'COP.5.a';
update public.shco_full_oes set achieve_tips = '["Implement a mandatory pre-transfusion double-verification step requiring two nurses to independently confirm the patient''s identity, blood group, and compatibility label before commencing each unit of blood or blood component.","Document the start time, end time, transfusion rate, and patient''s vital signs (before, 15 minutes after starting, and on completion) on a structured transfusion monitoring chart filed in the patient record.","Train all nursing staff in recognition and management of acute transfusion reactions, including when to stop the transfusion, notify the doctor, and preserve the blood bag for investigation; assess their competency annually.","Conduct monthly audits of ten random transfusion records to verify double-verification compliance, complete vital sign monitoring, and reaction-management documentation; report results to the blood transfusion committee."]'::jsonb where oe_code = 'COP.5.b';
update public.shco_full_oes set achieve_tips = '["Establish a blood transfusion committee that reviews all transfusion requests and audits appropriateness based on defined clinical triggers (e.g., Hb thresholds, clinical indication criteria) aligned with national transfusion guidelines.","Require treating doctors to document a clear clinical justification for each transfusion request on the blood request form, including latest relevant investigation values and clinical indication.","Conduct monthly transfusion appropriateness audits using a standardised review tool; report any case where transfusion was given outside defined criteria to the blood transfusion committee for peer review and feedback.","Track the number of units transfused per patient per month and benchmark against clinical outcome data to identify opportunities to reduce unnecessary transfusions, documenting results in quarterly committee minutes."]'::jsonb where oe_code = 'COP.5.c';
update public.shco_full_oes set achieve_tips = '["Design a transfusion-specific informed consent form in the patient''s preferred language that explains the procedure, alternatives, risks (including transfusion reactions), and the right to refuse; obtain and file this form before every transfusion.","Train all doctors to discuss transfusion risks and benefits with the patient or guardian before obtaining consent, and document the discussion in the clinical notes along with the signed consent form reference.","Establish a consent audit process: review ten random transfusion files each month to confirm that a completed, signed consent form is present before the transfusion start time recorded in the nursing chart.","Prepare a consent register for transfusion procedures that logs consent form number, patient name, date, and obtaining doctor; present this register to assessors as evidence of systematic consent management."]'::jsonb where oe_code = 'COP.5.d';
update public.shco_full_oes set achieve_tips = '["Define in writing the maximum acceptable time from blood requisition to issue for emergency situations (e.g., within 15 minutes for massive haemorrhage) and communicate this standard to the blood bank and all clinical departments.","Maintain a small emergency stock (O-negative units or group-specific blood) in the blood bank at all times and log daily stock levels; define the minimum stock level and escalation process when stock falls below the threshold.","Conduct quarterly timed drills simulating an emergency blood request, measuring the time from doctor''s order to blood reaching the ward; document results and act on any breach of the defined time standard.","Review emergency blood request records monthly to calculate actual average turnaround times, compare against the defined standard, and present trend data to the blood transfusion committee with corrective actions where targets are not met."]'::jsonb where oe_code = 'COP.5.e';
update public.shco_full_oes set achieve_tips = '["Introduce a standardised post-transfusion monitoring form that is sent back to the blood bank within 24 hours of transfusion completion, capturing the patient''s clinical response and any reaction observed during or after transfusion.","Create a transfusion reaction register in the blood bank to record all reported reactions with details of reaction type, severity, investigation findings, and outcome; review this register at every blood transfusion committee meeting.","Investigate every reported transfusion reaction using a root cause analysis template, identify contributing factors, and implement corrective actions (e.g., staff retraining, revised checklists) within 30 days.","Calculate monthly transfusion reaction rates, display them on the blood bank quality dashboard, and compare rates over time to demonstrate a downward trend as evidence of an effective quality improvement programme."]'::jsonb where oe_code = 'COP.5.f';
update public.shco_full_oes set achieve_tips = '["Develop written ICU/HDU admission and discharge criteria based on recognised scoring systems (e.g., APACHE II, SOFA) and document them in an SOP accessible to all ICU staff; include a specific plan for managing bed shortages (e.g., step-down protocols, transfer criteria).","Record the clinical justification for every ICU/HDU admission and discharge in the patient record, including the relevant severity score and the name of the authorising intensivist or designated doctor.","Conduct monthly bed management audits that review ICU occupancy rates, bed shortage episodes, and how the shortage protocol was implemented; present findings at the ICU quality meeting with corrective actions documented.","Train all ICU and ward staff on admission and discharge criteria through quarterly in-service sessions; retain training records and demonstrate to assessors that staff can correctly apply the criteria when interviewed."]'::jsonb where oe_code = 'COP.6.a';
update public.shco_full_oes set achieve_tips = '["Prepare a written ICU/HDU operational policy specifying nurse-to-patient ratios, minimum equipment requirements (ventilator, infusion pump, cardiac monitor, defibrillator), and prescribing authority for the unit.","Conduct daily equipment rounds in the ICU/HDU, verify functionality of all life-support and monitoring devices, and record findings on a signed equipment check log filed in the unit.","Maintain ICU staffing rosters for the past 12 months to demonstrate that recommended nurse-to-patient ratios were maintained on all shifts; flag and document any shortfall and the immediate compensatory measures taken.","Allow assessors to observe ICU nursing rounds and interview ICU staff regarding their care protocols; ensure all written guidance documents are current, signed by the medical director, and available at the nursing station."]'::jsonb where oe_code = 'COP.6.b';
update public.shco_full_oes set achieve_tips = '["Develop and display ICU-specific infection control SOPs covering hand hygiene compliance, central line bundle care, ventilator-associated pneumonia (VAP) prevention, and catheter-associated urinary tract infection (CAUTI) prevention.","Track ICU-specific infection rates (CLABSI, VAP, CAUTI) monthly, display trend graphs in the ICU, and review them at multidisciplinary infection control meetings with documented corrective actions.","Conduct weekly hand hygiene and bundle compliance audits in the ICU using a structured observation checklist; share results with ICU staff at morning meetings and post corrective-action notices where compliance falls below 90%.","Prepare an infection control audit portfolio for the ICU covering the past 12 months of compliance data, infection rates, and corrective actions taken, to present to assessors as documented evidence of ongoing infection prevention practice."]'::jsonb where oe_code = 'COP.6.c';
update public.shco_full_oes set achieve_tips = '["Define at least six measurable ICU quality indicators (e.g., ventilator days, length of stay, unexpected ICU readmission rate, unplanned extubation rate, mortality rate) and begin data collection immediately.","Review ICU quality indicator data monthly in a multidisciplinary ICU committee meeting, document discussions and action points in meeting minutes, and assign owners with deadlines for each improvement activity.","Set improvement targets for each indicator, implement changes (protocol revisions, equipment upgrades, staffing adjustments), and track whether the target is met over three consecutive months.","Compile an ICU quality report covering 12 months of indicator data with trend analysis and before-and-after outcome comparisons; present this to assessors as evidence of a sustained quality assurance programme."]'::jsonb where oe_code = 'COP.6.d';
update public.shco_full_oes set achieve_tips = '["Establish a written family communication policy for the ICU/HDU that specifies the frequency of physician-family meetings (e.g., daily or every 48 hours), who conducts them, and what information is covered.","Create a family counselling record form that captures the date, time, topics discussed, family members present, and doctor''s signature; file this in the patient record after every counselling session.","Designate a quiet counselling room adjacent to or near the ICU and ensure doctors and nurses use it for all family discussions to maintain privacy and improve the quality of communication.","During assessments, produce a sample of ICU patient files showing completed counselling records at defined intervals and allow assessors to interview nursing staff about the counselling process to verify consistent implementation."]'::jsonb where oe_code = 'COP.6.e';
update public.shco_full_oes set achieve_tips = '["Develop a written end-of-life care policy that addresses withholding or withdrawing life-sustaining treatment, palliative comfort measures, do-not-resuscitate (DNR) orders, and documentation requirements, in accordance with Indian law.","Create a standardised DNR order form and palliative care plan template; require that any end-of-life decision is documented by the treating physician and co-signed by a second senior doctor, with family consent noted.","Train all ICU and ward doctors and nurses in end-of-life communication skills and legal obligations through an annual workshop; retain attendance records and circulate a written summary of key legal requirements.","Audit ten end-of-life patient records quarterly to verify that care plans, family counselling notes, and DNR orders (where applicable) are properly documented; report audit findings to the ethics committee with any corrective actions required."]'::jsonb where oe_code = 'COP.6.f';
update public.shco_full_oes set achieve_tips = '["Develop an obstetric services SOP covering antenatal registration, risk stratification, intrapartum monitoring, labour management, and postpartum care, aligning it with national safe motherhood guidelines and LaQshya standards where applicable.","Maintain a labour room register that records each delivery with time of admission, gravida/para status, mode of delivery, attendant''s name, baby outcome, and maternal outcome; review the register at monthly obstetric review meetings.","Conduct quarterly skills drills for obstetric emergencies (postpartum haemorrhage, eclampsia, shoulder dystocia) in the labour room; document scenario details, staff participation, and corrective actions identified from the drill debrief.","Ensure obstetric patients'' case records contain completed partographs, intrapartum monitoring sheets, and delivery notes; audit ten random delivery records each month for completeness and present findings to the obstetrics department head."]'::jsonb where oe_code = 'COP.7.a';
update public.shco_full_oes set achieve_tips = '["Create a high-risk obstetric identification checklist (covering conditions such as severe anaemia, pre-eclampsia, diabetes, malpresentation, and previous caesarean section) and ensure it is completed for every antenatal patient at registration.","Maintain a high-risk obstetric register, review it at every antenatal visit, and ensure care is assigned to a qualified obstetrician and trained nurse with documented evidence of their credentials.","Develop written referral criteria and a referral pathway for high-risk cases requiring tertiary care; keep MoUs with referral centres current and document all referrals with the reason, patient condition at transfer, and receiving centre''s acknowledgement.","Audit high-risk obstetric case records monthly to confirm that risk identification, specialist involvement, management plans, and referral documentation are complete and timely; report audit results to the medical committee."]'::jsonb where oe_code = 'COP.7.b';
update public.shco_full_oes set achieve_tips = '["Incorporate a structured maternal nutrition assessment tool into the standard antenatal booking form, capturing body mass index, dietary history, haemoglobin level, and micronutrient supplementation status at every antenatal visit.","Train antenatal nurses and doctors to counsel all pregnant women on nutrition requirements and document the counselling in a nutrition counselling record retained in the antenatal case file.","Refer antenatal patients identified as nutritionally at-risk (low BMI, anaemia, poor dietary intake) to a dietitian or nutrition counsellor; document the referral and the follow-up nutritional assessment in the patient record.","Conduct a quarterly audit of antenatal case files to verify that a nutrition assessment is documented for every patient; calculate the completion rate and use it as a quality indicator reviewed by the obstetrics team."]'::jsonb where oe_code = 'COP.7.c';
update public.shco_full_oes set achieve_tips = '["Develop a peri-natal and post-natal monitoring SOP specifying minimum vital sign and foetal heart rate (FHR) monitoring frequencies for each stage of labour and for the 48-hour post-natal period, aligned with national clinical guidelines.","Use a standardised partograph for every woman in active labour, completing all sections including FHR, uterine contractions, cervical dilatation, and maternal vitals at the required intervals; file the completed partograph in the patient record.","Implement post-natal check rounds at defined intervals (e.g., every 4 hours in the first 24 hours post-delivery) for both mother and neonate, documenting each round''s findings on a structured post-natal monitoring chart.","Audit fifteen random delivery records per month to verify that partographs are fully completed and post-natal monitoring charts are present with all entries; share compliance rates with the obstetrics team and track improvement."]'::jsonb where oe_code = 'COP.7.d';
update public.shco_full_oes set achieve_tips = '["Ensure that any facility managing high-risk obstetric cases has a functional neonatal resuscitation area in or immediately adjacent to the delivery room, equipped with a radiant warmer, bag-mask device, suction, and oxygen.","Maintain a roster of at least one staff trained in Neonatal Resuscitation Programme (NRP) available in the labour room on every shift; keep NRP certificates in personnel files with renewal tracking.","Develop a written neonatal care SOP for high-risk deliveries covering immediate newborn assessment, Apgar scoring, resuscitation steps, and criteria for transfer to the NICU or special newborn care unit.","Audit all high-risk delivery records quarterly to confirm that a trained neonatal care provider was present, Apgar scores are documented at 1 and 5 minutes, and any neonatal intervention is fully recorded in the baby''s case file."]'::jsonb where oe_code = 'COP.7.e';
update public.shco_full_oes set achieve_tips = '["Develop a paediatric services SOP covering patient assessment, age-appropriate monitoring parameters, weight-based medication calculation, and specific safety requirements for children, referenced to IAP or WHO paediatric guidelines.","Maintain a paediatric ward safety checklist (cot-side rails, secured IV lines, age-appropriate equipment sizes, no sharps within child reach) completed by the nursing in-charge at the start of every shift and filed in the unit log.","Conduct quarterly paediatric emergency drills (e.g., neonatal resuscitation, febrile seizure management) in the paediatric ward; document staff participation, time taken, and any process improvements identified.","Audit ten random paediatric patient records each month to verify that age-specific vital sign ranges were used, weight-based drug calculations are documented, and nursing assessments are completed at required intervals."]'::jsonb where oe_code = 'COP.8.a';
update public.shco_full_oes set achieve_tips = '["Display current national (NNF) or WHO neonatal care guidelines in the nursery and SNCU, and develop unit-specific SOPs for temperature maintenance, feeding support, infection prevention, and oxygen therapy for neonates.","Maintain a neonatal temperature log, feeding record, and daily weight chart for every admitted neonate; ensure nursing staff complete these records at every care contact and sign each entry.","Conduct monthly neonatal outcome audits (hypothermia rate, hypoglycaemia rate, infection rate, breastfeeding initiation rate) and review results at neonatal unit meetings with documented corrective actions.","Train all neonatal unit staff in neonatal resuscitation and kangaroo mother care annually; keep training records and present them alongside outcome data to assessors as evidence that guidelines are translated into measurable improvements."]'::jsonb where oe_code = 'COP.8.b';
update public.shco_full_oes set achieve_tips = '["Develop an age-specific competency framework for staff working in the paediatric unit, covering normal developmental milestones, age-appropriate vital sign ranges, pain assessment tools (FLACC, Wong-Baker), and paediatric drug safety.","Assess each paediatric nurse and doctor against the competency framework at induction and annually thereafter using a written and practical evaluation; retain completed competency assessment forms in staff files.","Conduct quarterly peer skill-checks in the paediatric ward where senior staff observe and document whether junior staff correctly use age-appropriate assessment tools and equipment during routine care.","During assessor visits, allow assessors to interview paediatric nurses and doctors on age-specific assessment techniques; ensure staff can name the age-appropriate tools used in the unit and demonstrate correct pain scoring on a paediatric patient."]'::jsonb where oe_code = 'COP.8.c';
update public.shco_full_oes set achieve_tips = '["Create an SOP for special paediatric care needs, covering care for premature neonates, children with disabilities, child protection concerns, and children requiring isolation, and make it accessible to all paediatric unit staff.","Equip the paediatric unit with child-friendly furniture (cots with secured rails, size-appropriate equipment), age-appropriate distraction materials, and a parent sleeping provision; document these provisions in the ward inspection register.","Establish a referral pathway to paediatric sub-specialists (paediatric surgery, paediatric neurology, etc.) for children with complex needs; document all referrals with clinical justification and receiving specialist''s response in the patient record.","Conduct a biannual paediatric unit environment audit to verify that special care provisions are in place and functional; record findings and corrective actions in the quality management system."]'::jsonb where oe_code = 'COP.8.d';
update public.shco_full_oes set achieve_tips = '["Incorporate a structured paediatric assessment template into the admission form that includes sections for nutritional status (weight-for-age, height-for-age), developmental milestones, growth chart plotting, and immunisation history.","Train all paediatric nursing staff to use standardised growth charts (IAP or WHO), record immunisation status, and identify developmental red flags at every patient contact; assess their competency annually.","Refer any child identified as malnourished, developmentally delayed, or with incomplete immunisation to the appropriate specialist or immunisation clinic; document the referral and follow-up in the patient record.","Audit ten random paediatric admission records each month to verify that all four assessment domains (nutrition, growth, development, immunisation) are documented; report completion rates to the paediatric department head."]'::jsonb where oe_code = 'COP.8.e';
update public.shco_full_oes set achieve_tips = '["Develop a child/neonate security policy that includes parent/guardian identification band matching (baby band linked to mother band), visitor pass controls, CCTV coverage of the paediatric and neonatal units, and a defined alarm response protocol for missing child.","Implement a daily security round of the paediatric and neonatal units conducted by nursing supervisor and security staff; document findings and any security concerns in a unit security log.","Train all paediatric and neonatal unit staff in child abduction and abuse prevention protocols at induction and annually; include recognising signs of abuse and the mandatory reporting pathway to the child welfare committee.","Conduct a quarterly security drill simulating a missing child scenario in the paediatric unit; time the response to activation of the search protocol and document results, identifying gaps and implementing corrective measures."]'::jsonb where oe_code = 'COP.8.f';
update public.shco_full_oes set achieve_tips = '["Develop a procedural sedation SOP specifying eligible procedures, patient selection criteria, pre-sedation assessment requirements, drug choices, dosing guidelines, and monitoring parameters for each level of sedation.","Train all doctors who administer procedural sedation in the SOP and assess their competency through a structured practical evaluation; maintain training and assessment records and restrict sedation privileges to credentialled staff only.","Create a structured pre-sedation assessment form that documents patient ASA classification, airway assessment, allergies, last oral intake, and planned sedation agent, and file this form in the patient record before every procedure.","Audit ten random procedural sedation records monthly to verify SOP adherence, documentation completeness, and that only credentialled staff administered sedation; report compliance rates to the quality committee."]'::jsonb where oe_code = 'COP.9.a';
update public.shco_full_oes set achieve_tips = '["Design a procedural sedation consent form that explains the purpose, process, risks (over-sedation, respiratory depression, aspiration), and alternatives; make it available in the patient''s preferred language.","Train all doctors to discuss sedation risks with the patient or guardian before obtaining consent, and ensure this discussion and the signed consent form are documented in the patient record before the procedure begins.","Conduct a monthly consent audit for procedural sedation cases, checking that signed consent forms are present, pre-date the procedure, and contain the patient''s or guardian''s signature; report compliance percentages to the quality committee.","Prepare a consent register for all procedural sedation cases that logs the date, consent form number, obtaining doctor, and patient or guardian name; present this register to assessors as evidence of a systematic consent process."]'::jsonb where oe_code = 'COP.9.b';
update public.shco_full_oes set achieve_tips = '["Define and document the minimum qualifications and training required for staff who administer and monitor procedural sedation; maintain a credentialling register listing all authorised staff with their qualification proof and last competency assessment date.","Ensure that the staff member monitoring the patient during sedation has no other duties during the procedure; document their name and role in the sedation record for every case.","Conduct annual competency re-assessments for all sedation providers covering drug knowledge, monitoring techniques, and management of sedation complications; remove privileges for staff who do not meet competency standards until remedial training is completed.","During assessor visits, present the credentialling register and allow assessors to interview the sedation monitoring nurse about monitoring parameters and emergency response steps to verify practical competency."]'::jsonb where oe_code = 'COP.9.c';
update public.shco_full_oes set achieve_tips = '["Create a mandatory intra-procedure monitoring chart for procedural sedation that has pre-printed fields for heart rate, cardiac rhythm, respiratory rate, blood pressure, oxygen saturation, and sedation depth score (e.g., Ramsay Scale) to be completed at minimum every 5 minutes.","Ensure that monitoring equipment (pulse oximeter, NIBP, ECG monitor) is connected and functional before administering any sedation agent, and document equipment verification on the pre-sedation checklist.","Train nursing staff to immediately alert the doctor if any monitored parameter deviates from the defined acceptable range, and ensure the emergency response (reversal agent, airway support) is rehearsed quarterly.","Audit ten random sedation monitoring charts monthly to verify that all six parameters are documented at appropriate intervals and that the monitoring nurse''s name is recorded; report compliance rates to the quality committee."]'::jsonb where oe_code = 'COP.9.d';
update public.shco_full_oes set achieve_tips = '["Design a post-sedation recovery chart with objective discharge criteria (e.g., modified Aldrete score ≥9, or equivalent validated scale) that must be met and documented before any patient is transferred from the recovery area.","Train recovery nurses to perform and record objective assessments at defined intervals (e.g., every 15 minutes) until discharge criteria are met, and to document the time of discharge from recovery along with the achieved score.","Ensure that a doctor reviews and countersigns the recovery chart before the patient is transferred out of the recovery area, and that verbal and written post-procedure instructions are given to the patient or escort and documented.","Audit ten random post-sedation recovery records each month to verify that objective discharge criteria scores are recorded, criteria were met before transfer, and post-procedure instructions are documented; report findings to the quality committee."]'::jsonb where oe_code = 'COP.9.e';
update public.shco_full_oes set achieve_tips = '["Develop an anaesthesia services SOP covering pre-anaesthesia assessment, pre-induction check, intraoperative monitoring standards, post-anaesthesia care, and emergency protocols, and ensure it is signed off by the department head and available in the OT.","Train all anaesthesiologists on the SOP at induction and during annual updates; maintain training attendance records and document any SOP revisions with version number and effective date.","Implement a pre-operative anaesthesia check using a standardised machine checklist (covering equipment, gas supply, emergency drugs) completed by the anaesthesiologist before every list; file the signed checklist in the OT register.","Conduct monthly anaesthesia record audits selecting ten random cases to verify SOP adherence, completeness of documentation, and consistent monitoring; present findings with compliance rates at the anaesthesia department meeting."]'::jsonb where oe_code = 'COP.10.a';
update public.shco_full_oes set achieve_tips = '["Design a pre-anaesthesia assessment form that captures patient history, physical examination findings, relevant investigations, ASA classification, airway assessment (Mallampati score), planned anaesthesia technique, and anticipated risks, and require completion for every elective and emergency case.","Ensure the anaesthesiologist completes and signs the pre-anaesthesia assessment at least 6 hours before elective surgery (or as soon as possible for emergencies) and files it in the patient''s operative record.","Train all anaesthesiologists to document the anaesthesia plan explicitly, including type of anaesthesia, induction agents, maintenance agents, airway management plan, and anticipated post-operative pain management in the pre-anaesthesia form.","Audit ten random surgical patient records each month to confirm pre-anaesthesia assessment forms are complete, signed, and include a clearly documented anaesthesia plan; report the compliance rate at the anaesthesia departmental meeting."]'::jsonb where oe_code = 'COP.10.b';
update public.shco_full_oes set achieve_tips = '["Develop a structured pre-induction checklist (covering patient identity verification, consent confirmation, NPO status, IV access, pre-medication given, allergy alert, and anaesthesia machine check) that the anaesthesiologist completes and signs immediately before induction.","Make the pre-induction checklist a mandatory component of the anaesthesia record; do not allow induction to proceed unless the checklist is completed and any identified concern is resolved and documented.","Train all anaesthesiologists and OT nurses in the pre-induction checklist procedure during OT orientation; conduct a quarterly OT drill where the checklist completion is timed and observed by the quality team.","Audit ten random anaesthesia records monthly to verify that pre-induction checklists are signed, completed, and precede the induction time on the anaesthesia chart; report non-compliance immediately to the anaesthesia department head."]'::jsonb where oe_code = 'COP.10.c';
update public.shco_full_oes set achieve_tips = '["Design an anaesthesia-specific informed consent form that explains the planned anaesthesia technique, alternatives (e.g., regional vs. general), common and serious risks, and the post-anaesthesia recovery process in simple language.","Require the anaesthesiologist to obtain and document anaesthesia consent separately from the surgical consent during the pre-anaesthesia visit, filing the signed form in the patient record before the patient enters the OT.","Conduct a monthly consent audit for all surgical cases, checking that a signed anaesthesia consent form is present and pre-dates the OT admission time; calculate and report compliance rates to the quality committee.","Train all anaesthesiologists on informed consent principles and patient rights during annual training; retain attendance records and address any consent compliance gaps identified in audits through targeted retraining."]'::jsonb where oe_code = 'COP.10.d';
update public.shco_full_oes set achieve_tips = '["Ensure every anaesthesia record contains a standardised intraoperative monitoring section with fields for ECG, heart rate, NIBP, SpO2, EtCO2, temperature, and fluid balance to be recorded at minimum every 5 minutes, as per ASA monitoring standards.","Connect all monitoring devices to the patient before induction and verify their functionality; document the pre-use check on the anaesthesia checklist; do not proceed with induction if any mandatory monitor is non-functional.","Train OT nurses and anaesthesia technicians to assist with monitoring setup, identify alarm conditions, and immediately alert the anaesthesiologist of any parameter outside defined safe ranges; assess their competency annually.","Audit ten random anaesthesia charts each month to verify that intraoperative monitoring parameters are recorded at required intervals throughout the procedure and that the anaesthesiologist''s signature is present; report compliance to the department head."]'::jsonb where oe_code = 'COP.10.e';
update public.shco_full_oes set achieve_tips = '["Implement a post-anaesthesia care unit (PACU) monitoring chart with objective discharge criteria (modified Aldrete or White-Song score) that must be documented and met before any patient is transferred from the recovery area.","Require PACU nurses to record vital signs, pain score, sedation level, airway status, and nausea/vomiting score at minimum every 15 minutes until discharge criteria are met; ensure the anaesthesiologist signs off on discharge.","Train all PACU nursing staff in post-anaesthesia monitoring, management of common complications (hypoxia, hypotension, shivering, PONV), and reversal agent administration protocols; assess competency annually.","Audit ten random PACU records monthly to verify that objective discharge criteria scores are documented, discharge criteria were met before ward transfer, and the time of PACU discharge is recorded; report compliance rates at the anaesthesia meeting."]'::jsonb where oe_code = 'COP.10.f';
update public.shco_full_oes set achieve_tips = '["Create a mandatory anaesthesia drug and technique documentation section on the anaesthesia record form with pre-printed fields for induction agent, dose, route, maintenance agents, regional anaesthetic agents (if used), reversal agents, and emergency drugs administered.","Require the anaesthesiologist to complete drug documentation in real time during the procedure and countersign the completed anaesthesia record before handing over the patient to the PACU nurse.","Conduct a quarterly random sample audit of ten anaesthesia records to verify that all drug names, doses, times, and routes are legibly documented for every medication given; report any missing entries as non-compliances to the anaesthesia department head.","During assessor visits, present anaesthesia records alongside the PACU chart to demonstrate a continuous and complete drug and monitoring record for each patient; train anaesthesiologists to articulate the documentation workflow to assessors during interviews."]'::jsonb where oe_code = 'COP.10.g';
update public.shco_full_oes set achieve_tips = '["Define a list of reportable intraoperative adverse events (e.g., unexpected difficult airway, anaphylaxis, intraoperative awareness, cardiac arrest, unplanned conversion to general anaesthesia) and require the anaesthesiologist to flag and document each occurrence on the anaesthesia record.","Maintain an adverse anaesthesia event register that captures date, case, type of event, severity, immediate action taken, and outcome for every reported event; review this register at the monthly anaesthesia committee meeting.","Conduct a root cause analysis for every adverse anaesthesia event, identify contributing factors, and implement corrective actions within 30 days; document the analysis and corrective actions in the event register.","Calculate monthly adverse event rates per 1000 anaesthetics, track trend data over 12 months, and present before-and-after outcome comparisons to assessors as evidence of a functional monitoring and improvement programme."]'::jsonb where oe_code = 'COP.10.h';
update public.shco_full_oes set achieve_tips = '["Develop SOPs for all major clinical procedures performed in the hospital (e.g., IV cannulation, lumbar puncture, central line insertion, wound suturing) and for all OT procedures; display quick-reference guides in procedure rooms and the OT.","Train all clinical and OT nursing staff on each procedure SOP at induction; conduct annual SOP refresher sessions and retain attendance and competency assessment records for every staff member.","Implement a pre-procedure time-out immediately before every invasive procedure: confirm patient identity, procedure, site, and consent aloud with the entire team; document the time-out in the procedure record.","Audit ten random procedural records each month to verify SOP adherence, time-out documentation, and complete procedural notes; present compliance rates at the quality committee meeting."]'::jsonb where oe_code = 'COP.11.a';
update public.shco_full_oes set achieve_tips = '["Implement a mandatory pre-operative assessment form that captures history, physical examination, ASA status, pre-operative investigations, pre-operative diagnosis, and pre-operative instructions given to the patient; require the surgeon to complete it before any elective surgery.","Document patient-specific pre-operative instructions (NPO duration, bowel preparation, pre-operative medications to hold or continue, skin preparation) in the patient record and verify they were communicated to and understood by the patient.","Develop a pre-operative checklist completed by the ward nurse on the day of surgery confirming that all pre-operative requirements have been met; attach the signed checklist to the patient''s file before OT transfer.","Audit ten random surgical case files monthly to verify that pre-operative assessments, diagnoses, and documented patient instructions are present and complete before the OT admission time; report compliance rates to the surgical department head."]'::jsonb where oe_code = 'COP.11.b';
update public.shco_full_oes set achieve_tips = '["Design a procedure-specific informed consent form for every major surgical and invasive procedure, written in simple language and the patient''s preferred language, covering the procedure, alternatives, benefits, risks, and the right to withdraw consent.","Require the operating surgeon to personally obtain and document informed consent during the pre-operative visit, at least 24 hours before elective surgery; do not allow OT admission without a signed consent form in the patient file.","Conduct a monthly surgical consent audit reviewing ten random case files to confirm that signed, completed consent forms are present, pre-date the OT admission time, and bear the operating surgeon''s signature.","Train all surgical and procedure-performing staff on the ethical and legal requirements for informed consent during annual medical-legal training; maintain attendance records and display a summary of consent requirements in all procedure rooms."]'::jsonb where oe_code = 'COP.11.c';
update public.shco_full_oes set achieve_tips = '["Adopt the WHO Surgical Safety Checklist (sign-in, time-out, sign-out) for every surgical and invasive procedure; post the checklist prominently in every OT and procedure room and make its completion mandatory before incision.","Designate a team member (typically the circulating nurse) as the checklist coordinator for each case; train all OT staff in their checklist roles and conduct quarterly observed drills to verify correct checklist execution.","Implement a site-marking policy requiring the operating surgeon to mark the operative site with an indelible marker before the patient enters the OT, and verify the mark during the surgical time-out; document this verification in the operative checklist.","Audit the completed WHO checklist forms from every OT case monthly; calculate the percentage of cases where all three checklist phases (sign-in, time-out, sign-out) were completed, and report non-compliance directly to the OT medical in-charge."]'::jsonb where oe_code = 'COP.11.d';
update public.shco_full_oes set achieve_tips = '["Develop and display a standard precautions SOP for OT and procedure rooms covering hand hygiene, PPE selection (sterile gown, gloves, mask, eye protection), sharps handling, and instrument decontamination; make compliance mandatory for all OT staff.","Conduct monthly observed audits of OT standard precautions adherence using a structured checklist, noting compliance with each precaution for all team members; share results with the OT nursing in-charge for immediate corrective action.","Ensure a complete set of correctly sized PPE is available at every OT table and procedure trolley before the start of each case; assign the circulating nurse to verify and document PPE availability on the pre-case checklist.","Train all OT and procedure room staff in standard precautions at induction and annually; include a practical skills station in training sessions and retain competency assessment records for each staff member."]'::jsonb where oe_code = 'COP.11.e';
update public.shco_full_oes set achieve_tips = '["Develop a structured operative note template that includes pre-operative diagnosis, post-operative diagnosis, procedure performed, findings, complications, estimated blood loss, specimens sent, and post-operative care plan; require the surgeon to complete it before leaving the OT.","Train all surgeons to dictate or write operative notes immediately after each procedure; have a nursing supervisor verify that the operative note is present in the patient file before the patient is transferred to the recovery room.","Design a post-operative monitoring chart for the ward specifying minimum vital sign frequencies, wound check intervals, drain output recording, and pain scores; require nursing staff to complete and sign the chart at each observation.","Audit ten random surgical patient files monthly to verify that operative notes, post-operative monitoring charts, and post-operative care plans are all present and complete; report compliance rates to the surgical department head and quality committee."]'::jsonb where oe_code = 'COP.11.f';
update public.shco_full_oes set achieve_tips = '["Conduct a biannual OT equipment and facility audit using a standardised checklist that covers anaesthesia machine, OT table, surgical lighting, suction, diathermy, sterilised instrument sets, implant inventory, and emergency equipment availability.","Implement a daily OT readiness checklist completed by the OT nursing in-charge before the first case, confirming that equipment is functional, instruments are sterilised, consumables are stocked, and emergency drugs are available.","Establish a preventive maintenance schedule for all major OT equipment and document each service in an equipment maintenance register; ensure critical equipment has a defined backup plan if it fails during a case.","During assessor visits, present the OT equipment audit register and daily readiness checklists; walk assessors through the OT and demonstrate the location and availability of emergency equipment and instrument sterilisation records."]'::jsonb where oe_code = 'COP.11.g';
update public.shco_full_oes set achieve_tips = '["Define OT quality indicators (e.g., surgical site infection rate, OT cancellation rate, case-cart accuracy rate, instrument count discrepancy rate, returnto-OT rate) and collect baseline data for the first three months.","Review OT quality indicator data monthly in an OT committee meeting; document discussion points, improvement targets, and assigned action owners with completion deadlines in the meeting minutes.","Implement at least one targeted improvement project per quarter based on quality indicator findings (e.g., reducing OT cancellations by improving pre-operative preparation); track progress and document outcomes.","Compile a 12-month OT quality report with indicator trend graphs and before-and-after outcome data to present to assessors as evidence of a functioning, data-driven quality assurance programme."]'::jsonb where oe_code = 'COP.11.h';
update public.shco_full_oes set achieve_tips = '["Develop a written organ transplant policy covering legal authorisation requirements under the Transplantation of Human Organs and Tissues Act (THOTA), ethics committee approval, donor and recipient eligibility criteria, and documentation requirements.","Constitute a hospital transplant ethics committee with the composition and functions mandated by THOTA; hold documented meetings before every transplant case, retain minutes, and file committee approval letters in the patient record.","Train all transplant team members in THOTA legal requirements, including mandatory reporting, donor evaluation protocols, and consent documentation; maintain training records and display a THOTA compliance flowchart in the transplant unit.","Conduct an annual internal THOTA compliance audit covering documentation, committee approvals, and registry reporting; present audit findings and corrective actions to hospital management and retain records for regulatory inspections."]'::jsonb where oe_code = 'COP.11.i';
update public.shco_full_oes set achieve_tips = '["Display organ donation awareness materials (posters, brochures, pledging cards) in high-footfall areas such as OPD, reception, and waiting areas, and update them whenever national campaign materials are refreshed.","Train all OPD and ward staff to proactively discuss organ donation with patients and families during appropriate clinical encounters, and document awareness sessions conducted in a hospital awareness activity register.","Organise at least two organ donation awareness events per year (e.g., during National Organ Donation Day on 27 November), open to staff, patients, families, and the community; document attendance and activities conducted.","Track the number of organ donation pledges and family awareness sessions conducted each quarter, and report these figures to hospital management as a quality indicator demonstrating commitment to the national organ donation cause."]'::jsonb where oe_code = 'COP.11.j';
update public.shco_full_oes set achieve_tips = '["Develop a written vulnerable patient identification policy listing categories of vulnerable patients (elderly, paediatric, cognitively impaired, physically challenged, victims of abuse, patients at end of life) and specify the assessment tool and additional care measures for each category.","Use a vulnerability screening checklist at patient admission to identify and flag vulnerable patients; indicate vulnerability status on the patient wristband or bed-head ticket using a designated colour code or symbol.","Train all clinical and nursing staff to recognise and respond to the needs of vulnerable patients, including mandatory reporting of suspected abuse to the patient welfare committee; retain training attendance records.","Conduct monthly audits of vulnerable patient case files to confirm that vulnerability was identified at admission, additional care measures are documented and implemented, and patient safety checks are completed at required intervals."]'::jsonb where oe_code = 'COP.12.a';
update public.shco_full_oes set achieve_tips = '["Conduct a physical environment safety assessment for each area housing vulnerable patients, checking for secured call bells, absence of sharp edges, non-slip flooring, adequate lighting, and controlled visitor access; document findings and rectify hazards within defined timelines.","Assign a dedicated named nurse responsible for each vulnerable patient''s safety checks on every shift, documenting the check time and findings on a structured patient safety observation form.","Install visible monitoring aids (e.g., bed exit alarms for fall-risk patients, identification wristbands for cognitively impaired patients) and document their use in the patient record.","Review any incident involving a vulnerable patient using a root cause analysis framework within 48 hours of the event; document findings, corrective actions, and preventive measures taken, and present the case at the next quality meeting."]'::jsonb where oe_code = 'COP.12.b';
update public.shco_full_oes set achieve_tips = '["Implement a validated fall risk assessment tool (e.g., Morse Fall Scale) for every patient at admission, after any fall, after a change in clinical condition, and at every shift handover; document scores and risk category in the patient record.","Implement fall prevention interventions tailored to each patient''s risk level (e.g., non-slip footwear, bed alarms, low-bed positioning, regular toileting schedule for high-risk patients) and document each intervention in the care plan.","Conduct nursing staff training on fall risk assessment and prevention protocols at induction and annually; include a practical session on using the chosen assessment tool and demonstrate correct documentation.","Track the number of falls per 1000 patient days monthly, classify each fall by severity, and conduct a root cause analysis for every fall; present trend data to the quality committee and document corrective actions implemented to reduce recurrence."]'::jsonb where oe_code = 'COP.12.c';
update public.shco_full_oes set achieve_tips = '["Use a validated pressure ulcer risk assessment tool (e.g., Braden Scale or Waterlow Scale) for every admitted patient within 4 hours of admission, at every shift change, and after any change in mobility or nutritional status; document scores and stage in the patient record.","Implement a structured pressure ulcer prevention bundle for all at-risk patients, including repositioning every 2 hours, use of pressure-relieving mattresses, moisture management, and nutritional supplementation, and document each intervention on the nursing care plan.","Train all nursing staff in pressure ulcer risk assessment, staging (Stages I–IV plus unstageable), and prevention interventions at induction and annually; retain competency assessment records and verify practical skills through observation.","Track pressure ulcer incidence rates monthly (hospital-acquired ulcers per 1000 patient days), conduct root cause analysis for every stage II or higher hospital-acquired ulcer, and present trend data with corrective actions to the quality committee."]'::jsonb where oe_code = 'COP.12.d';
update public.shco_full_oes set achieve_tips = '["Implement a standardised DVT risk assessment tool (e.g., Caprini or Padua score) for every surgical and high-risk medical patient at admission and after surgery; document the score and prescribed thromboprophylaxis plan in the patient record.","Develop and display a DVT prophylaxis protocol in surgical wards and ICUs specifying pharmacological (LMWH dose and timing) and mechanical (compression stockings, pneumatic compression devices) prophylaxis options based on risk score.","Train all surgical, ICU, and general medicine nursing staff to apply compression stockings correctly, administer LMWH as prescribed, and recognise signs of DVT and pulmonary embolism; assess competency annually and retain records.","Audit ten random surgical patient records monthly to verify that DVT risk scores are documented, appropriate prophylaxis was initiated within the prescribed timeframe, and there is evidence of daily monitoring; report compliance rates to the surgical department head."]'::jsonb where oe_code = 'COP.12.e';
update public.shco_full_oes set achieve_tips = '["Develop a restraint policy covering indications for use, types of permissible restraints, duration limits, consent requirements, monitoring frequency, and documentation requirements; align the policy with patient rights and applicable legal standards.","Require a doctor''s written order specifying the type, duration, and reason for restraint before any restraint is applied; document the order in the patient record and obtain consent from the patient or legal guardian.","Train all nursing staff in safe restraint application, monitoring (circulation, skin integrity, psychological status), and de-escalation alternatives; assess competency at induction and annually; retain training and assessment records.","Conduct a daily nursing audit of every restrained patient to verify that the restraint order is current, monitoring documentation is complete, and the least restrictive option is being used; report any non-compliances to the nursing head immediately."]'::jsonb where oe_code = 'COP.12.f';
update public.shco_full_oes set achieve_tips = '["Adopt a validated pain assessment tool appropriate for different patient populations (Numeric Rating Scale for adults, FLACC for paediatric patients, Abbey Pain Scale for non-verbal patients) and make its use mandatory at every nursing assessment and after any pain-related intervention.","Develop a pain management protocol specifying escalation steps from non-pharmacological measures through analgesic ladders; include reassessment timelines after each intervention and document compliance in the patient record.","Train all nursing and clinical staff in pain assessment and management protocols at induction and annually, including use of each pain scale and documentation requirements; retain training attendance and competency assessment records.","Conduct monthly audits of ten random patient records to verify that pain scores are documented at admission, at defined intervals, and after every pain intervention; calculate compliance rates and report findings to the quality committee with corrective actions."]'::jsonb where oe_code = 'COP.13.a';
update public.shco_full_oes set achieve_tips = '["Implement a pain re-assessment policy requiring nursing staff to reassess pain within 30 minutes of administering any analgesic or initiating a non-pharmacological pain measure; document the re-assessment score alongside the intervention in the patient record.","Develop a nurse-initiated analgesic protocol (within defined prescribing authority) for common pain situations, allowing nursing staff to give first-line analgesics without delay; document every administration with dose, route, time, and post-administration pain score.","Train all clinical and nursing staff in titration principles — starting low, reassessing frequently, and escalating doses based on patient response — and document their competency assessment in their personnel files.","Audit ten random inpatient records monthly to verify that post-intervention pain reassessment scores are present and show a downward trend; calculate the percentage of patients achieving a pain score below the target threshold and report this as a quality indicator."]'::jsonb where oe_code = 'COP.13.b';
update public.shco_full_oes set achieve_tips = '["Map the rehabilitation services required to support the organisation''s clinical scope (e.g., physiotherapy for surgical and orthopaedic patients, speech therapy for stroke patients, occupational therapy for paediatric patients) and confirm that each service is either available in-house or accessible through a documented referral arrangement.","Develop written rehabilitation SOPs for each major patient category (post-surgical, neurological, paediatric) specifying assessment methods, goal-setting frameworks, frequency of sessions, and discharge criteria.","Train clinical and nursing staff to refer patients for rehabilitation assessment within a defined timeframe (e.g., within 24 hours of admission for stroke patients) and document the referral and response in the patient record.","Audit ten random rehabilitation patient records monthly to verify that rehabilitation assessments were initiated within the defined timeframe, goals are documented, and patient progress is measured against the goals; report compliance rates to the quality committee."]'::jsonb where oe_code = 'COP.13.c';
update public.shco_full_oes set achieve_tips = '["Establish a formal rehabilitation team structure (physician, physiotherapist, occupational therapist, nurse, speech therapist as applicable) with written terms of reference for multidisciplinary collaboration on rehabilitation care planning.","Implement a unified rehabilitation care plan document in the patient record that is co-authored and co-signed by each team member, specifying individual roles, therapy goals, and planned session frequency.","Hold a weekly rehabilitation team meeting for complex rehabilitation patients to review progress, adjust goals, and update the care plan; retain meeting notes in the patient record as evidence of collaborative planning.","Audit ten random rehabilitation patient records monthly to verify that a multidisciplinary care plan is present and has contributions documented from each relevant discipline; report cases where collaboration is missing to the department head for corrective action."]'::jsonb where oe_code = 'COP.13.d';
update public.shco_full_oes set achieve_tips = '["Implement a standardised nutritional screening tool (e.g., Malnutrition Universal Screening Tool — MUST, or NRS-2002) for every patient within 24 hours of admission; document the screening score and nutritional risk category in the patient record.","Develop a written protocol specifying that any patient identified as nutritionally at-risk receives a full nutritional assessment by a registered dietitian within 48 hours of screening; document the assessment findings and dietary recommendations in the patient file.","Train all ward nursing staff to administer the nutritional screening tool accurately at induction and annually; conduct quarterly observed assessments to verify correct tool usage and retain competency records.","Track the percentage of admitted patients screened for nutritional risk within 24 hours as a monthly quality indicator; report compliance rates to the quality committee and document corrective actions taken when the target is not achieved."]'::jsonb where oe_code = 'COP.13.e';
update public.shco_full_oes set achieve_tips = '["Establish a multidisciplinary nutrition care team (treating physician, dietitian, nurse, and pharmacologist for parenteral nutrition cases) and develop a written policy requiring collaborative development of the therapeutic diet for every at-risk patient.","Create a standardised therapeutic diet prescription form co-signed by the treating doctor and dietitian, specifying caloric targets, macronutrient ratios, consistency modifications, and any therapeutic restrictions; file it in the patient record.","Set up a daily dietitian round for patients on therapeutic diets; document the dietitian''s assessment, dietary tolerance, and any plan modifications in the patient record; communicate updates to the nursing staff at each meal service.","Audit ten random patient records of nutritionally at-risk patients each month to verify that a collaborative therapeutic diet plan is documented, dietary intake is monitored, and plan revisions are made in response to the patient''s intake and clinical progress; report compliance rates to the quality committee."]'::jsonb where oe_code = 'COP.13.f';

-- MOM (52 OEs)
update public.shco_full_oes set achieve_tips = '["Develop and maintain an approved formulary list tailored to your patient case mix and available clinical services, with a formal review at least annually by the pharmacy and therapeutics committee.","Create an SOP for adding new drugs to the formulary, including the approval workflow, and train all prescribers on how to access and use the updated formulary.","Maintain a signed and dated formulary document that is version-controlled and accessible at all prescription points; assessors will verify both the document and staff awareness.","During staff interviews, nurses and doctors should be able to name the process for requesting a non-formulary drug — rehearse this scenario in monthly team briefings."]'::jsonb where oe_code = 'MOM.1.a';
update public.shco_full_oes set achieve_tips = '["Constitute a formal multidisciplinary pharmacy and therapeutics committee with defined membership (physician, pharmacist, nurse, administrator) and document its terms of reference.","Hold committee meetings at a minimum quarterly frequency; maintain signed minutes recording decisions on formulary changes, medication policies, and incident reviews.","Display the committee''s approved written policies at the pharmacy and nursing stations so staff can reference them during daily operations.","Be prepared for assessors to observe whether staff follow committee-approved guidance — conduct mock drills and confirm all nursing and pharmacy staff can cite the relevant SOP."]'::jsonb where oe_code = 'MOM.1.b';
update public.shco_full_oes set achieve_tips = '["Draft a written procedure that clearly differentiates the procurement pathway for formulary medications versus non-formulary medications, including required approvals and documentation.","Train the purchase and pharmacy teams on the non-formulary requisition process and keep requisition forms on file as evidence of compliance.","Maintain a procurement register that logs every non-formulary drug request with date, requestor, clinical justification, approval status, and quantity purchased.","Conduct a quarterly internal audit of procurement records to confirm all purchases follow the approved procedure; file audit reports as audit-ready evidence for assessors."]'::jsonb where oe_code = 'MOM.1.c';
update public.shco_full_oes set achieve_tips = '["Create a written SOP detailing how medications can be obtained when the pharmacy is closed, including the name and contact details of the on-call pharmacist or designated responsible person.","Identify a secure after-hours drug cabinet or satellite stock and document the list of medications kept there, with clear access control and a log for after-hours dispensing.","Train all night and weekend nursing staff on the after-hours medication access procedure; document training attendance and conduct at least one simulation drill every six months.","Keep a logbook of every after-hours medication access event with the time, drug name, quantity taken, staff name, and next-day pharmacy reconciliation signature."]'::jsonb where oe_code = 'MOM.1.d';
update public.shco_full_oes set achieve_tips = '["Document a policy specifying the clinical criteria for selecting and using implantable prostheses and medical devices, including brand equivalence and surgeon qualification requirements.","Maintain a vendor-approved list and ensure purchase orders for implants are matched against this list before procurement.","Create an implant requisition and consent workflow that requires surgeon sign-off on the clinical indication before procurement is initiated, and file all completed forms.","Train operating room and purchase staff on the criteria for implant selection; assessors may ask staff to explain how a specific implant type gets approved for use."]'::jsonb where oe_code = 'MOM.1.e';
update public.shco_full_oes set achieve_tips = '["Run a monthly report of all medications prescribed and cross-reference against the approved formulary to identify off-formulary prescribing patterns.","Share formulary adherence data at the pharmacy and therapeutics committee meeting, naming the top non-formulary drugs and discussing clinical justification or formulary update.","Place the current formulary in a prominent, easily searchable format (printed binder or digital portal) at every doctor''s workstation to remove barriers to adherence.","When non-formulary drugs are unavoidably prescribed, document the clinical justification in the medical record — this demonstrates good practice even where adherence is imperfect."]'::jsonb where oe_code = 'MOM.1.f';
update public.shco_full_oes set achieve_tips = '["Designate clean, lockable storage areas for medications in every care area; label shelves clearly and ensure temperature, humidity, and light conditions match manufacturer specifications.","Conduct daily temperature logs for refrigerated medications and room-temperature medication stores; assign a responsible staff member per shift and file completed logs monthly.","Perform a weekly physical inspection of all medication storage areas covering cleanliness, lock status, expired stock, and labelling; document results in an inspection register.","During assessments, staff should be able to walk assessors through storage conditions and explain the manufacturer-specified requirements for at least two common refrigerated drugs."]'::jsonb where oe_code = 'MOM.2.a';
update public.shco_full_oes set achieve_tips = '["Implement a First Expiry First Out (FEFO) stocking system for all medication storage areas and train pharmacy and ward staff on correct rotation practice.","Set a minimum and maximum stock level for each medication and create a reorder trigger system so stock-outs and overstocking are both prevented.","Conduct a bi-monthly physical stock count and reconcile against the pharmacy dispensing records; retain count sheets as inventory control evidence.","Create an SOP for handling damaged, contaminated, or mislabelled stock, including quarantine procedures, and train all pharmacy staff; assessors will look for a functioning quarantine area."]'::jsonb where oe_code = 'MOM.2.b';
update public.shco_full_oes set achieve_tips = '["Publish a formally approved list of all high-risk and Look-Alike Sound-Alike (LASA) medications specific to your hospital and post it at the pharmacy dispensing counter and all nursing stations.","Apply clear, standardised visual alerts — tall-man lettering labels, red stickers, or physical segregation — to all LASA medications in storage to prevent pick errors.","Store high-alert drugs such as concentrated electrolytes and anticoagulants in a clearly marked, segregated section; never store them with routine medications.","Train all pharmacy and nursing staff on the high-alert and LASA drug list; assessors will observe storage areas and conduct staff interviews to verify recognition of these drugs."]'::jsonb where oe_code = 'MOM.2.c';
update public.shco_full_oes set achieve_tips = '["Identify every clinical area where high-risk medications are clinically necessary (e.g., ICU, OT, emergency) and formally authorise those as the only permitted storage locations.","Restrict access to high-risk medication storage to authorised clinical staff only; use locks, key registers, or access codes and maintain an access log.","Conduct monthly unannounced checks to confirm high-risk drugs have not migrated to non-authorised areas; document findings and corrective actions taken.","Collect and present data on the number of high-risk medication access events per month and confirm all occurred in authorised areas — this serves as measurable outcome evidence for assessors."]'::jsonb where oe_code = 'MOM.2.d';
update public.shco_full_oes set achieve_tips = '["Define the list of emergency medications for each crash cart or emergency tray and document this list in a laminated card affixed to each cart.","Standardise the layout of all emergency medication trays across wards so nursing staff can locate any drug within seconds, regardless of which unit they are working in.","Create an SOP for emergency medication storage, including shelf-life requirements, temperature storage, and the process for replacing used or expired items.","Conduct a monthly emergency tray inspection and seal verification; retain completed checklists as evidence that the defined list is consistently maintained."]'::jsonb where oe_code = 'MOM.2.e';
update public.shco_full_oes set achieve_tips = '["Establish a daily emergency medication availability checklist for each ward and assign a named nurse each shift to verify and sign off that all items are present and in-date.","Create a same-shift replenishment protocol: any emergency medication used must be replaced before the end of the shift, with the pharmacist counter-signing the replenishment record.","Keep a log of every instance where an emergency drug was used and record the time from use to replenishment; track this metric monthly and present at committee meetings.","During assessments, staff should demonstrate they know what to do if an emergency medication is missing — practise this scenario in quarterly in-service sessions."]'::jsonb where oe_code = 'MOM.2.f';
update public.shco_full_oes set achieve_tips = '["Adopt and display the hospital''s rational prescribing guidelines at every doctor''s workstation, referencing national formulary guidance or relevant clinical protocols.","Develop an SOP that defines when polypharmacy review is triggered and train doctors and clinical pharmacists on how to conduct a medication appropriateness review.","Include rational prescribing as a standing agenda item in monthly clinical department meetings, sharing data on antibiotic use, polypharmacy, and high-cost medication trends.","Document prescribing training sessions for new medical staff at induction, covering rational use principles; maintain attendance registers for assessor review."]'::jsonb where oe_code = 'MOM.3.a';
update public.shco_full_oes set achieve_tips = '["Define the minimum required elements of a valid prescription in a written policy (patient name, ID, date, drug, dose, route, frequency, prescriber name, and signature) and circulate to all prescribers.","Attach a quick-reference prescription requirements card to every prescription pad or electronic order screen as a point-of-care reminder for clinical staff.","Train pharmacy staff to reject incomplete prescriptions and document rejections in a daily rejection log, which is reviewed weekly by the pharmacy in-charge.","Assessors will review a sample of medical records for prescription completeness — conduct an internal monthly audit of 20 prescriptions per ward and correct gaps immediately."]'::jsonb where oe_code = 'MOM.3.b';
update public.shco_full_oes set achieve_tips = '["Add a mandatory allergy and adverse drug reaction (ADR) field to every patient admission form, ensuring it is completed before any medication is prescribed.","Introduce a red allergy alert sticker system on the patient''s medical record cover, medication administration record (MAR), and wristband to flag known allergies at a glance.","Create an SOP requiring doctors to verbally confirm allergy status with the patient or their attendant before every new prescription, and document this confirmation in the notes.","During nursing staff interviews, assessors often ask how allergy information is communicated across shifts — ensure allergy status is a mandatory item in every handover checklist."]'::jsonb where oe_code = 'MOM.3.c';
update public.shco_full_oes set achieve_tips = '["Deploy drug interaction checking software or maintain a printed reference (e.g., drug interaction tables) at the pharmacy counter to flag potentially harmful combinations before dispensing.","Train clinical pharmacists to provide bedside or telephone support to prescribers for complex cases, and document all clinical pharmacy interventions in the patient file.","Set up a visual alert system in your electronic or paper-based prescribing system that prompts clinicians when a prescribed drug falls outside recommended dosage ranges for the patient''s age or weight.","Hold monthly case reviews of near-miss events related to prescribing errors and share learnings at clinical meetings — this demonstrates a functional prescribing support mechanism to assessors."]'::jsonb where oe_code = 'MOM.3.d';
update public.shco_full_oes set achieve_tips = '["Develop a written policy on verbal orders specifying that they are permitted only in emergencies, must be repeated back by the receiving nurse, and must be countersigned by the prescriber within a defined timeframe (e.g., 24 hours).","Train all nursing and medical staff on the read-back and countersignature requirement through a dedicated in-service session; document attendance and test comprehension.","Create a verbal order section in the patient''s medication administration record and ensure nurses document verbal orders in real-time, noting the prescribing doctor''s name and the repeat-back confirmation.","Assessors will check that verbal orders in medical records carry timely countersignatures — audit a sample of records monthly and flag any that exceed the defined countersignature deadline."]'::jsonb where oe_code = 'MOM.3.e';
update public.shco_full_oes set achieve_tips = '["Establish a monthly medication order audit programme using a standardised checklist covering rationality, completeness, legibility, allergy check, and dosage appropriateness across a random sample of patient records.","Assign the clinical pharmacist or a senior physician to lead the audit and compile findings into a structured report shared with department heads within five days of the audit.","Track key audit metrics over time — percentage of complete prescriptions, incidence of unsafe prescribing indicators — and display trend charts at pharmacy and clinical governance meetings.","Maintain all audit reports in a dedicated file; assessors want to see evidence that audits are systematic, periodic, and acted upon — not just a one-time exercise before the assessment."]'::jsonb where oe_code = 'MOM.3.f';
update public.shco_full_oes set achieve_tips = '["Document every corrective or preventive action arising from a prescription audit in a CAPA (Corrective and Preventive Action) register, including the responsible person and target closure date.","After implementing a corrective action, re-audit the same area after 30–60 days to verify effectiveness and record re-audit results as before-and-after comparison evidence.","Share CAPA outcomes at the pharmacy and therapeutics committee meeting and record decisions in the minutes; this demonstrates a closed-loop improvement process to assessors.","Present trend data showing reduction in audit deficiencies over consecutive audit cycles — measurable improvement in prescribing quality is the strongest evidence for this achievement OE."]'::jsonb where oe_code = 'MOM.3.g';
update public.shco_full_oes set achieve_tips = '["Implement a structured medication reconciliation form that is completed at every transition point: admission, transfer between units, and discharge; file the completed form in the medical record.","Train all admitting nurses and doctors to conduct medication reconciliation within two hours of a patient''s arrival in a new care area, and document the date and time of reconciliation.","Include a medication reconciliation step in the discharge summary template so that the patient''s home medications are reviewed against hospital-prescribed drugs before they leave.","During assessments, staff will be asked how medication changes are communicated at handover — ensure medication reconciliation is a standing item on every shift handover checklist."]'::jsonb where oe_code = 'MOM.3.h';
update public.shco_full_oes set achieve_tips = '["Maintain a current list of authorised prescribers (doctors with valid registration and hospital credentials) and share it with the pharmacy so only prescriptions from authorised individuals are dispensed.","Create an SOP stating that pharmacy staff must verify the prescriber''s designation on any unfamiliar prescription and document the verification check in the dispensing record.","Train ward clerks and nursing staff that only credentialed doctors and authorised nurse practitioners (where applicable) may enter medication orders, and immediately escalate any unauthorised order.","Assessors may ask staff who is permitted to write medication orders — ensure all nursing and pharmacy staff can correctly name authorised categories without hesitation."]'::jsonb where oe_code = 'MOM.4.a';
update public.shco_full_oes set achieve_tips = '["Designate a specific, consistent section in every patient''s medical record for all medication orders (e.g., a dedicated medication order sheet or electronic order module) and train all staff to write orders only there.","Ensure every medication order sheet is pre-printed with the patient''s name and unique hospital ID number so there is no risk of orders being filed in the wrong patient record.","Conduct a monthly random review of 15–20 medical records to verify that all medication orders are in the designated location and correctly identify the patient; document results.","If assessors find orders written on loose notes or in non-standard locations, it is an immediate deficiency — reinforce through nurse briefings that ad hoc ordering locations are not acceptable."]'::jsonb where oe_code = 'MOM.4.b';
update public.shco_full_oes set achieve_tips = '["Post a sample of a correctly completed medication order at every doctor''s writing station as a visual standard, showing required legibility, date/time format, and signature placement.","Train pharmacists and ward nurses to return any illegible, undated, untimed, or unsigned medication order to the prescriber immediately for correction before it is dispensed.","Maintain a record of returned or rejected medication orders; analyse patterns monthly to identify which prescribers or units most frequently produce non-compliant orders, then address with targeted training.","In monthly chart audits, specifically score each order for legibility, date, time, and signature — track the compliance rate and demonstrate improvement over audit cycles."]'::jsonb where oe_code = 'MOM.4.c';
update public.shco_full_oes set achieve_tips = '["Design or update the medication order form to include mandatory fields for drug name, route, strength, and frequency/time so incomplete orders cannot be inadvertently accepted.","Train pharmacy staff to use a four-point verification checklist (name, route, strength, frequency) before accepting any order for dispensing and to return orders missing any element.","Conduct a monthly audit of dispensed orders to confirm all four required elements are present in 100% of orders; report the compliance rate to the pharmacy committee.","Assessors may pick a random medication order from the file and ask the nurse to verify its completeness — practise this scenario in ward training so staff can confidently walk through all four elements."]'::jsonb where oe_code = 'MOM.4.d';
update public.shco_full_oes set achieve_tips = '["Develop a detailed dispensing SOP covering the five rights of dispensing (right patient, drug, dose, route, time), double-check procedures for high-risk drugs, and documentation requirements.","Implement a mandatory second-pharmacist or senior technician check before dispensing any high-risk, controlled, or high-dose medication, and record the checker''s initials on the dispensing label.","Conduct monthly dispensing accuracy checks by auditing a sample of dispensed medications against original orders; track the error rate and present findings at pharmacy meetings.","Train all dispensing staff on the SOP at induction and through bi-annual refresher sessions; maintain training records with assessment scores as evidence of competency."]'::jsonb where oe_code = 'MOM.5.a';
update public.shco_full_oes set achieve_tips = '["Subscribe to drug regulatory authority recall alerts and designate a pharmacist as the recall focal point who receives notifications and initiates the recall response within 24 hours.","Develop and practise a medication recall SOP covering immediate quarantine of affected batches, patient exposure assessment, prescriber notification, and return to supplier documentation.","Maintain a recall register recording every recall event: drug name, batch number, quantity affected, date of quarantine, disposal or return date, and whether any patients were exposed.","After each recall event, brief the pharmacy team on what happened and what was learned; file the debrief record as evidence that recalls are handled as safety incidents, not routine returns."]'::jsonb where oe_code = 'MOM.5.b';
update public.shco_full_oes set achieve_tips = '["Set a near-expiry trigger date — typically three to six months before expiry — and create a near-expiry monitoring register listing all affected stock with expiry dates and responsible action owner.","Apply yellow ''near-expiry'' stickers to flagged medications and move them to the front of shelves (FEFO) so they are used before newer stock, reducing waste.","Establish a process to return near-expiry medications to suppliers or transfer to higher-consumption facilities before they expire; document all transfers with date, quantity, and destination.","Conduct a monthly near-expiry review and report the quantity of medications that expired and had to be discarded; use this data as a performance indicator to improve forecasting and ordering."]'::jsonb where oe_code = 'MOM.5.c';
update public.shco_full_oes set achieve_tips = '["Create a labelling SOP specifying that every dispensed medication must carry a label showing patient name, hospital ID, drug name, strength, dose, route, frequency, and dispensing date.","Print pre-formatted dispensing labels from the pharmacy management system and verify the label against the original prescription before attaching it to the medication package.","Conduct random daily checks of five to ten dispensed medications to confirm all required label elements are present; document checks in a dispensing quality register.","Train nurses to refuse any unlabelled medication received from the pharmacy and return it immediately for proper labelling — assessors will verify labelled medications at ward level during site visits."]'::jsonb where oe_code = 'MOM.5.d';
update public.shco_full_oes set achieve_tips = '["Implement a mandatory independent double-check system for all high-risk medication orders where a second pharmacist verifies the drug, dose, patient, and route before the order is dispensed.","Create a high-risk medication verification checklist form and attach a completed copy to each dispensed high-risk drug package; file a duplicate in the pharmacy dispensing record.","Train all pharmacy staff on which drugs trigger the double-check requirement by maintaining a posted high-risk drug list at the dispensing counter and testing staff awareness quarterly.","Assessors will observe the dispensing process and interview pharmacy staff — ensure every staff member can correctly identify the high-risk drug list and demonstrate the double-check procedure."]'::jsonb where oe_code = 'MOM.5.e';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP for medication returns covering eligibility criteria (e.g., sealed, within expiry, correct temperature storage), documentation requirements, and restock or disposal pathways.","Provide nursing staff with a standardised medication return form that records patient name, drug, quantity, reason for return, condition of the medication, and accepting pharmacist signature.","Maintain a returns register in the pharmacy and cross-reference with ward records monthly to verify that all returned medications are accounted for and correctly processed.","Train both ward nurses and pharmacy staff on return procedures at induction; during assessments staff should be able to describe what happens to a partially used medication pack that is no longer needed."]'::jsonb where oe_code = 'MOM.5.f';
update public.shco_full_oes set achieve_tips = '["Establish and train all nursing staff on the five rights of medication administration (right patient, drug, dose, route, time) and add a sixth right — right documentation — to the hospital''s standard protocol.","Create an SOP for high-alert medication administration that mandates a two-nurse independent check before administration, with both nurses signing the medication administration record (MAR).","Conduct monthly observation rounds where a senior nurse observes a junior nurse administering medications and documents compliance with the administration protocol.","Assessors will directly observe medication administration and interview nurses about the procedure — practise the full administration sequence in monthly ward-based simulations."]'::jsonb where oe_code = 'MOM.6.a';
update public.shco_full_oes set achieve_tips = '["Develop an SOP that requires any prepared medication to be immediately labelled with drug name, strength, and preparation time before a second medication is drawn up or prepared.","Place a permanent visual prompt at every medication preparation area reminding staff: ''Label before you prepare the next drug'' — laminate and affix this to the preparation tray or counter.","Train all nursing and pharmacy staff on the one-at-a-time preparation and labelling rule during induction and repeat in bi-annual refreshers; keep training attendance records.","During assessor observation, staff will be watched preparing medications — conduct regular supervisory spot-checks to confirm no nurse leaves a prepared, unlabelled syringe or bag unattended."]'::jsonb where oe_code = 'MOM.6.b';
update public.shco_full_oes set achieve_tips = '["Implement a two-identifier patient identification policy (full name plus hospital ID or date of birth) that must be verified verbally and against the wristband before every medication administration.","Train all nursing staff on the wristband check protocol and ensure wristbands are applied to every patient at admission; missing wristbands must be replaced immediately and documented.","Add patient identification confirmation as a mandatory step in the medication administration record (MAR) — nurses sign or initial the MAR only after completing the identity check.","Assessors will ask nurses to demonstrate the patient identification process at the bedside — practise this during monthly ward simulation drills to ensure it is second-nature to all staff."]'::jsonb where oe_code = 'MOM.6.c';
update public.shco_full_oes set achieve_tips = '["Train all medication-administering nurses and doctors to read the medication order, then physically inspect the drug (label, expiry, appearance, packaging integrity) before administration — and never skip either step.","Create a bedside administration checklist that prompts staff to confirm the drug against the order and inspect its physical condition; attach the checklist to the MAR folder.","Document any physical inspection failure (e.g., discoloured injection, broken seal) in the incident reporting system and return the drug to the pharmacy; analyse these events monthly.","During assessments, staff will be asked to walk through the pre-administration verification process — ensure every nurse can describe both order verification and physical inspection steps without prompting."]'::jsonb where oe_code = 'MOM.6.d';
update public.shco_full_oes set achieve_tips = '["Incorporate a mandatory three-point verification step in the MAR: before picking the drug, before preparing it, and before administering it — each step requiring the nurse to check strength, route, and time against the order.","Post the administration verification checklist at every medication trolley and require nurses to initial each verification step in the MAR for every medication given.","Conduct monthly audits of MARs to confirm the three verification steps are consistently documented; report compliance rates to the nursing department head.","During training sessions, role-play common errors — such as administering a drug via the wrong route — so staff internalise the importance of re-reading the order at each verification step."]'::jsonb where oe_code = 'MOM.6.e';
update public.shco_full_oes set achieve_tips = '["Procure and deploy colour-coded, non-interchangeable connectors for IV, enteral, and epidural lines in all clinical areas where multiple infusions are used simultaneously.","Create a visual guide showing correct tubing connections for the most common medication delivery routes used in your facility and laminate it for display in the ICU, OT, and all inpatient wards.","Train all nursing staff on catheter and tubing mis-connection risks and prevention during induction and at bi-annual competency refreshers; document attendance and competency sign-off.","Investigate and formally report any tubing mis-connection near-miss or error as a critical incident; present the investigation findings at a clinical safety meeting and implement corrective actions."]'::jsonb where oe_code = 'MOM.6.f';
update public.shco_full_oes set achieve_tips = '["Use a standardised medication administration record (MAR) for every patient and ensure nurses sign immediately after administering each drug, including the exact time of administration.","Define the documentation requirements in an SOP: drug name, dose given, route, time, administering nurse''s signature, and any patient response or refusal must all be recorded.","Conduct weekly spot audits of MARs across wards to verify timely and complete documentation; share results with ward sisters and set a target of 100% MAR completion.","Train nursing staff that retrospective or pre-emptive entries in the MAR are not acceptable — assessors will check timestamps and may ask nurses about their documentation practice."]'::jsonb where oe_code = 'MOM.6.g';
update public.shco_full_oes set achieve_tips = '["Develop a written policy governing patient self-administration, specifying which medications may be self-administered (e.g., insulin by diabetic patients), the patient competency assessment process, and documentation requirements.","Before allowing self-administration, assess and document the patient''s competency through a structured checklist covering knowledge of the drug, correct technique, and ability to recognise adverse effects.","Educate patients on correct self-administration technique and have them demonstrate it back to the nurse; document the teach-back session and the patient''s demonstrated competency in the medical record.","Store self-administered medications securely at the bedside in a locked personal medication box and conduct daily nursing checks to ensure only approved medications are being self-administered."]'::jsonb where oe_code = 'MOM.6.h';
update public.shco_full_oes set achieve_tips = '["Establish a policy requiring that any medication a patient brings from home is identified, assessed for compatibility with hospital treatment, and either stored securely by the pharmacy or documented as approved for continued use.","Create a patient-brought medication assessment form where the admitting nurse lists each home medication, the prescribing doctor reviews it, and the disposition (continue, hold, or discontinue) is clearly recorded.","Measure and report the percentage of patients with home medications who received a formal pharmacist or physician review within 24 hours of admission as a monthly compliance metric.","Provide brief patient education at admission on the hospital''s home medication policy so patients understand they must disclose all drugs including supplements and over-the-counter medications; document this counselling."]'::jsonb where oe_code = 'MOM.6.i';
update public.shco_full_oes set achieve_tips = '["Define in a written SOP which medications require post-administration monitoring, specify the type of monitoring (vital signs, blood glucose, pain score, lab values), the frequency, and the minimum observation window.","Create a post-administration monitoring section in the nursing care record or MAR where nurses document patient response after each high-risk or new medication is given.","Train nursing staff to recognise common adverse reactions for the top 20 medications used in each ward and document any observed reactions immediately in the medical record and incident system.","Assessors will review medical records for evidence of post-administration monitoring entries — conduct monthly chart audits and provide targeted feedback to nurses who do not consistently document patient responses."]'::jsonb where oe_code = 'MOM.7.a';
update public.shco_full_oes set achieve_tips = '["Create a medication review workflow where the prescribing doctor is notified of any abnormal patient response to a medication within a defined timeframe (e.g., one hour for acute reactions) and a review is documented in the notes.","Document every medication change in the patient''s medical record with a clear clinical rationale, including what monitoring finding prompted the change and the new therapy decision.","Train nurses to proactively communicate monitoring findings to doctors using a structured SBAR (Situation, Background, Assessment, Recommendation) communication tool; document the communication and response.","Conduct case reviews of patients whose medications were changed during admission and use these as teaching cases in ward rounds to reinforce the monitoring-to-adjustment cycle for all staff."]'::jsonb where oe_code = 'MOM.7.b';
update public.shco_full_oes set achieve_tips = '["Implement a simple, non-punitive reporting form for near-miss events, medication errors, and adverse drug reactions (ADRs) and place copies at every nursing station and in the pharmacy.","Train all clinical staff that reporting near-misses is a safety duty, not an admission of fault, and demonstrate that reports lead to system improvements rather than individual blame.","Ensure the pharmacovigilance officer or designate reviews every ADR report within 48 hours and enters it into the national ADR reporting system (e.g., Vigiflow) where required.","Assessors will check both the number and quality of incident reports — a zero-report rate signals under-reporting, not a safe environment; aim for a steady stream of near-miss reports as a sign of a healthy safety culture."]'::jsonb where oe_code = 'MOM.7.c';
update public.shco_full_oes set achieve_tips = '["Set a defined reporting timeframe in your SOP — for example, all medication errors must be reported to the pharmacy or patient safety officer within 24 hours and analysed within 72 hours.","Assign a pharmacovigilance or medication safety officer responsible for collating all near-miss, error, and ADR reports, conducting root cause analysis, and escalating serious events to management.","Use a standardised analysis template (e.g., fishbone or 5-Why analysis) for every reported event; retain completed analysis forms in a dedicated safety file accessible for assessment.","Report summary data — number of events, categories, severity, and trend — at the pharmacy and therapeutics committee meeting each quarter and record in the minutes."]'::jsonb where oe_code = 'MOM.7.d';
update public.shco_full_oes set achieve_tips = '["Log every corrective or preventive action arising from a medication safety event in a CAPA register with a named owner, implementation date, and verification method.","After implementing a corrective action, re-measure the specific safety metric that triggered the event (e.g., wrong-drug incident rate) to demonstrate measurable improvement.","Share closed CAPA outcomes with frontline nursing and pharmacy staff through a monthly ''lessons learned'' bulletin so the whole team benefits from individual event analyses.","Assessors will look for evidence that actions are implemented, not just planned — ensure every CAPA entry in the register has a completed and verified closure section before the assessment date."]'::jsonb where oe_code = 'MOM.7.e';
update public.shco_full_oes set achieve_tips = '["Develop a comprehensive SOP for the handling of narcotics, psychotropics, chemotherapy, and radioactive agents covering procurement, receipt, storage, dispensing, administration, and disposal in compliance with applicable laws.","Train all staff who handle these agents on the specific legal and safety requirements for each category; document training with competency sign-off and retain for assessor review.","Establish strict access controls for narcotic and psychotropic storage: double-locked cabinets, dual-key access for nurses and pharmacists, and a real-time usage log maintained at the storage point.","Conduct a monthly audit of narcotic and psychotropic records comparing quantities received, dispensed, and remaining against physical counts; investigate and report any discrepancy immediately."]'::jsonb where oe_code = 'MOM.8.a';
update public.shco_full_oes set achieve_tips = '["Maintain an updated register of physicians authorised to prescribe narcotics and psychotropics, specifying their Narcotics User Certificate (or applicable credential) number, validity, and care area.","Create a prescriber authorisation checklist that pharmacy staff use to verify credentials before accepting any narcotic or psychotropic prescription from a new or infrequent prescriber.","For chemotherapy, document the oncologist''s qualification and specific chemotherapy prescribing approval in the medical staff credentials file, and cross-reference before dispensing any regimen.","Assessors may ask the pharmacist to demonstrate how prescriber authorisation is verified for a narcotic order — practise this scenario with pharmacy staff to ensure a confident, documented response."]'::jsonb where oe_code = 'MOM.8.b';
update public.shco_full_oes set achieve_tips = '["Store narcotics and psychotropics in a double-locked, wall-fixed metal cabinet with a dual-key system; one key held by the shift nurse and the other by the on-duty pharmacist or in-charge.","Maintain a running narcotic stock register at the storage point with entries for every receipt and issue, countersigned by two staff members for each transaction.","Chemotherapy drugs must be stored in a dedicated, labelled, locked refrigerator or cabinet separate from other medications, with a daily temperature log maintained by pharmacy staff.","Radioactive material storage must comply with radiation safety regulations; the storage area must be clearly labelled with radiation warning signs, and only trained and authorised staff may access it."]'::jsonb where oe_code = 'MOM.8.c';
update public.shco_full_oes set achieve_tips = '["Designate a dedicated, ventilated chemotherapy preparation area (biological safety cabinet) and ensure only trained and certified pharmacy staff or nurses prepare chemotherapy agents.","Create a chemotherapy preparation and administration SOP that specifies PPE requirements, spill management, and patient verification steps; train all involved staff and certify them annually.","Verify that staff administering chemotherapy have documented competency in cytotoxic handling, including IV access assessment and extravasation management; file competency certificates.","Establish a radioactive material handling protocol in compliance with the Atomic Energy Regulatory Board requirements; document every administration event with staff credentials, dose delivered, and waste disposal."]'::jsonb where oe_code = 'MOM.8.d';
update public.shco_full_oes set achieve_tips = '["Maintain a double-entry narcotic register that records every vial received, every dose dispensed to a patient, the patient name and MRD number, the administering nurse, and the witness; reconcile daily.","For psychotropics, maintain a separate register with the same detail level and submit monthly reports to the designated regulatory authority as required by the Narcotic Drugs and Psychotropic Substances Act.","Document chemotherapy administration in the patient''s medical record with the drug name, dose, batch number, route, date, and administering clinician''s signature; retain records for the legally required period.","Record radioactive agent usage in a radiation logbook maintained by the licensed radiation safety officer; all disposal must follow regulatory disposal protocols and be documented with disposal certificates."]'::jsonb where oe_code = 'MOM.8.e';
update public.shco_full_oes set achieve_tips = '["Develop a written policy and SOP for implantable prosthesis procurement that specifies vendor qualification criteria, prior approval requirements, CDSCO registration verification, and pricing caps or committee approval thresholds.","Create an implant request form that requires the surgeon to specify the clinical indication, product name, size, and preferred vendor before procurement is initiated, with HOD countersignature for high-value items.","Maintain an approved vendor register for implant suppliers and verify their CDSCO licence, post-market surveillance registration, and biocompatibility certification before placing orders.","Train the surgical team and purchase department on the written procurement guidance; assessors will verify that actual implant purchase orders follow the approved SOP and are supported by the required forms."]'::jsonb where oe_code = 'MOM.9.a';
update public.shco_full_oes set achieve_tips = '["Develop a structured patient and family counselling protocol for each category of implantable prosthesis, covering what the device is, why it is needed, expected outcomes, and any specific precautions or restrictions post-implantation.","Obtain and file a separate implant-specific informed consent that details the type of prosthesis, brand, potential complications, and alternatives discussed — distinct from the general surgical consent.","Document counselling sessions in the medical record and have the patient or family member sign an acknowledgement confirming they understood the information and had their questions answered.","Create patient education leaflets in the local language for the most commonly implanted devices (e.g., joint replacements, pacemakers, mesh) and provide a copy to the patient at discharge for reference."]'::jsonb where oe_code = 'MOM.9.b';
update public.shco_full_oes set achieve_tips = '["Design a standardised implant sticker or label — printed with the batch number, serial number, product name, and manufacturer — and attach it to three locations: the patient''s medical record, the implant master logbook, and the discharge summary.","Maintain a centralised implant master logbook in the OT or medical records department with one entry per implantation, cross-referenced to the patient''s hospital number.","Train scrub nurses and OT coordinators to capture and record implant details immediately after implantation while the packaging is still available, preventing data loss after the procedure.","Conduct a quarterly audit of a sample of implant cases to verify that all three records (medical record, logbook, discharge summary) consistently carry the correct batch and serial number; document audit findings."]'::jsonb where oe_code = 'MOM.9.c';

-- PRE (39 OEs)
update public.shco_full_oes set achieve_tips = '["Draft a written Patient Rights and Responsibilities charter in simple language, get it approved by management, and display laminated copies at OPD reception, admission counter, and all ward entrances.","Create an SOP requiring admission staff to verbally walk every patient through their rights and hand over a printed rights card; document this briefing in the admission register with patient signature.","Train all front-desk, nursing, and ward-boy staff annually on the content of the rights charter using a structured module; maintain attendance records and a post-training quiz score sheet for assessor review.","Conduct quarterly internal audits verifying that rights displays are present, legible, and current at all mandated locations; record findings and corrective actions in the audit register."]'::jsonb where oe_code = 'PRE.1.a';
update public.shco_full_oes set achieve_tips = '["Run a monthly patient-facing awareness activity such as a display board update, pamphlet distribution, or a short video in the waiting area; record each activity with date, topic, and number of patients reached.","Measure promotion effectiveness by including a ''Were you informed of your rights?'' question in the patient satisfaction survey; track monthly scores and document improvement trends as before/after evidence.","Post rights information in multiple local languages across clinical areas and photograph each display with a date stamp; maintain a photo log showing progressive improvements in visibility and multilingual coverage.","Compile a quarterly report summarising promotion activities, patient feedback on rights awareness, and any gap-closure actions taken; present this at the patient safety committee meeting and file the minutes."]'::jsonb where oe_code = 'PRE.1.b';
update public.shco_full_oes set achieve_tips = '["Maintain a patient rights protection log where any reported concern (e.g., denied privacy, coercive treatment) is recorded, investigated, and closed within a defined timeline; keep this register available for assessor inspection.","During ward rounds, staff should actively observe whether curtains are drawn during examinations, confidentiality is maintained at nurses'' stations, and patients are spoken to respectfully; supervisors should document these observations on a monthly checklist.","Assessors will interview nursing and ward staff — prepare staff to articulate at least three specific rights they are responsible for upholding and give a real example of how they applied one in the past month.","Review patient records each month for evidence that rights-related obligations (e.g., consent, confidentiality agreements) are consistently documented; flag and correct missing entries before the next assessment cycle."]'::jsonb where oe_code = 'PRE.1.c';
update public.shco_full_oes set achieve_tips = '["Install a clearly labelled complaint/rights-violation reporting box at a visible, accessible location and appoint a designated staff member to review submissions daily; document each submission and its resolution in a register.","Create an SOP outlining the step-by-step process for a patient or family to report a rights violation, including whom to contact, expected response time, and escalation path; display this process prominently near the complaint box.","Train staff on how to receive, record, and escalate a rights violation report without retaliating against the patient; include scenario-based practice in the training and retain attendance and assessment records.","Assessors will ask staff to explain the complaint mechanism — conduct mock drills quarterly where a staff member role-plays receiving a violation report, documents it correctly, and escalates it; record drill outcomes."]'::jsonb where oe_code = 'PRE.1.d';
update public.shco_full_oes set achieve_tips = '["Compile a monthly rights-violation summary report showing number of complaints received, nature of violations, resolution timelines, and pending cases; present this report to top leadership and file signed minutes as evidence.","Perform root-cause analysis for recurring or serious violations and document a formal corrective/preventive action plan with responsible owners and target dates; track completion of each action item.","Assessors will review records of leadership involvement — ensure that meeting minutes, email approvals, or signed CAPA forms clearly show that the medical superintendent or equivalent has personally reviewed and acted on violation data.","Set a measurable target (e.g., zero unresolved complaints beyond 7 days) and track monthly performance against it; display a trend chart in the quality office showing month-on-month improvement for the past year."]'::jsonb where oe_code = 'PRE.1.e';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP that requires staff to ask each patient at admission about any religious, cultural, or dietary preferences and document responses in the patient file; include a standardised ''special preferences'' field in the admission form.","Create a referral pathway in the SOP for spiritual care requests (e.g., access to a priest, maulvi, or pandit), define the turnaround time, and maintain a log of requests made and fulfilled for assessor review.","Train nursing and front-office staff through a dedicated session on cultural sensitivity and religious diversity using real case scenarios; maintain attendance sheets, training materials, and post-session acknowledgment forms.","Conduct quarterly audits of a sample of patient files to verify that cultural/spiritual preference fields are consistently filled; record audit findings and share corrective action plans with the nursing in-charge."]'::jsonb where oe_code = 'PRE.2.a';
update public.shco_full_oes set achieve_tips = '["Create an SOP mandating the use of screens or curtains during all physical examinations, dressing changes, and procedures; include a checklist item for this in the daily ward nursing round form and retain completed forms.","Train all clinical and paramedical staff to knock before entering, address patients by name, and avoid discussing patient conditions in public corridors; conduct an observed scenario exercise annually and record outcomes.","Assessors will walk through clinical areas and observe privacy practices — perform unannounced internal checks at least bi-monthly to confirm curtains are functional, screens are available, and staff follow dignity protocols; document findings.","Include a patient satisfaction question specifically about privacy and dignity; review scores monthly and present trend data at the quality committee meeting as evidence of a sustained improvement effort."]'::jsonb where oe_code = 'PRE.2.b';
update public.shco_full_oes set achieve_tips = '["Develop and display an anti-abuse and anti-neglect policy that defines what constitutes neglect or abuse in a healthcare setting; include a clear reporting mechanism and consequences for staff violation, and obtain staff acknowledgment signatures annually.","Create an SOP for mandatory reporting of suspected patient abuse or neglect — including who is responsible to report, to whom, and within what timeframe; maintain a log of all reports and their resolution as audit-ready records.","Train all staff — including housekeeping and security — to identify signs of patient neglect or abuse and report immediately without fear of retaliation; document training attendance and use a competency checklist for verification.","Conduct quarterly case reviews to confirm no patient has experienced delays in care or inadequate attention; identify cases flagged by nursing staff as ''at risk'' and document follow-up actions taken to prevent neglect."]'::jsonb where oe_code = 'PRE.2.c';
update public.shco_full_oes set achieve_tips = '["Implement a written confidentiality policy covering physical records, verbal discussions, and digital data; require all staff to sign a confidentiality agreement at joining and annually thereafter, keeping signed copies in their personnel files.","Ensure patient records, files, and lab reports are never left open at unattended desks, corridors, or nurses'' stations; conduct monthly spot-checks and log any breach observed along with corrective action taken.","Assessors will interview staff to test confidentiality awareness — train staff to articulate the hospital''s confidentiality rules and demonstrate correct behaviour, such as lowering their voice when discussing patient details and locking file cabinets.","Review all cases where records were shared externally (e.g., with insurance companies, legal bodies) against a documented authorisation log; ensure written patient consent or legal authorisation exists for each disclosure and is filed in the patient record."]'::jsonb where oe_code = 'PRE.2.d';
update public.shco_full_oes set achieve_tips = '["Develop an SOP that outlines the step-by-step process when a patient refuses treatment: inform the treating doctor, document the refusal with patient/family signature, explain consequences, and offer alternatives; keep the signed form in the patient file.","Create a standardised ''Refusal of Treatment'' form in the local language that captures the patient''s understanding of risks and the alternatives offered; ensure the form is signed by both the patient (or legal guardian) and the treating clinician.","Train clinical staff through a role-play scenario where a patient refuses a recommended procedure, so staff practise how to counsel respectfully without coercing, then document the outcome; retain training records and scenario assessment forms.","Conduct a monthly audit of inpatient files to check whether any refusal-of-treatment events occurred and were correctly documented with signed forms; report audit findings to the nursing supervisor and file corrective actions for gaps found."]'::jsonb where oe_code = 'PRE.2.e';
update public.shco_full_oes set achieve_tips = '["Incorporate a clause in the Patient Rights charter explicitly stating the patient''s right to a second opinion; brief every admitted patient on this right at admission and document in the admission checklist that this briefing occurred.","Develop an SOP for facilitating a second opinion — including internal referral to a senior specialist or guidance on seeking external consultation — and maintain a log of all second-opinion requests and outcomes.","Train admitting doctors and nurses to respond positively when a patient or family requests a second opinion; use a staff training module that includes do''s and don''ts, and retain signed acknowledgment of training.","Quarterly, review a sample of patient files where second-opinion requests were noted; verify that each was facilitated without delay or objection and document the audit finding for quality committee review."]'::jsonb where oe_code = 'PRE.2.f';
update public.shco_full_oes set achieve_tips = '["Maintain a hospital-wide list of all procedures requiring mandatory informed consent (blood transfusion, anaesthesia, surgery, research, high-risk interventions); post this list in operation theatres, procedure rooms, and the nursing station and update it annually.","Assessors will review patient records — ensure that every surgical, anaesthesia, and blood transfusion file contains a completed and signed consent form before the procedure date; implement a pre-procedure checklist that blocks proceeding without signed consent.","Train all doctors and nurses involved in high-risk procedures on the legal and ethical requirement for prior informed consent; use case studies of consent failures as training examples and document attendance and competency assessment.","Conduct a monthly random audit of 10 files from each high-risk category to verify consent documentation is complete, signed, dated, and obtained before the procedure; record audit results and corrective actions in the quality register."]'::jsonb where oe_code = 'PRE.2.g';
update public.shco_full_oes set achieve_tips = '["Display a clear, step-by-step complaints process poster at the OPD, reception, and each ward — including the complaint box location, Grievance Officer contact, and expected response timeline; update displays when the process changes.","Create an SOP for complaint management specifying receipt, acknowledgement within 24 hours, investigation, resolution, and communication of outcome to the complainant; maintain a complaints register with all these fields completed for each complaint.","Train admission and nursing staff to proactively inform patients at the time of admission about the complaint mechanism and to hand over a written guide; document this briefing in the admission checklist with patient signature.","Conduct quarterly reviews of the complaints register to verify every complaint was acknowledged and resolved within the defined timeframe; present summary statistics (volume, resolution rate, repeat complaints) to management and file the review report."]'::jsonb where oe_code = 'PRE.2.h';
update public.shco_full_oes set achieve_tips = '["Develop an SOP requiring the billing/admissions desk to provide every patient with a written cost estimate at the time of admission; include an acknowledgement column in the admission form where the patient signs to confirm they received the estimate.","Create standardised cost-estimate templates for the 10 most common procedures and diagnoses; keep these templates updated quarterly and make them readily available to admission staff for quick patient briefing.","Train admission and billing staff to explain cost estimates clearly, including items likely to vary (e.g., medicines, investigations); conduct a competency assessment annually and retain training records showing staff can handle common patient cost queries.","Review a monthly sample of patient admission files to confirm cost estimates were provided and signed; track the compliance rate as a quality indicator and present trend data to the finance and quality committee."]'::jsonb where oe_code = 'PRE.2.i';
update public.shco_full_oes set achieve_tips = '["Draft an SOP specifying the process for a patient or authorised family member to request access to or a copy of their clinical records, including the designated contact person, required identification, turnaround time, and applicable fees if any.","Inform every patient at admission of their right to access their records; include this in the patient rights briefing script and document the briefing in the admission checklist with patient/family signature.","Train medical records and nursing staff on how to handle record access requests in accordance with the SOP and applicable legal requirements; maintain a request log showing date received, date fulfilled, and any reasons for delay.","Conduct a quarterly audit of the record access request log to verify all requests were fulfilled within the defined timeline; present non-compliance cases to the quality committee with root-cause analysis and corrective actions."]'::jsonb where oe_code = 'PRE.2.j';
update public.shco_full_oes set achieve_tips = '["Introduce a daily ''patient information round'' where the assigned nurse verbally updates each inpatient on the name of their treating doctor, today''s care plan activities, and any significant changes; document this update on the nursing notes with time and signature.","Place a whiteboard or name card at each patient bedside showing the attending doctor''s name, ward nurse''s name, and today''s planned investigations or procedures; update it every shift and check for accuracy during supervisor rounds.","Train nursing staff using a structured communication checklist that covers what minimum information must be shared with patients every 24 hours; retain training records and verify compliance through spot audits of bedside information boards.","Conduct monthly audits of a sample of nursing notes to confirm daily patient information updates are documented; track the documentation compliance rate as a nursing quality indicator and share results at the monthly departmental meeting."]'::jsonb where oe_code = 'PRE.2.k';
update public.shco_full_oes set achieve_tips = '["Add a structured ''Information Sharing Preference'' section to the admission form where the patient specifies who may receive clinical information about them (e.g., spouse, parent, no one other than self); file the completed form in the patient record.","Train nursing and clinical staff to check the patient''s information-sharing preference at the start of every shift before discussing health updates with visiting family members; include this check in the shift handover checklist.","Develop an SOP covering scenarios where the patient is unconscious or a minor, defining the default authorised information recipient and documentation requirements; train staff through role-play exercises on applying this SOP correctly.","Conduct quarterly audits of inpatient files to verify the information-sharing preference section is filled for all admissions; track completion rates and address gaps through targeted retraining of admission staff."]'::jsonb where oe_code = 'PRE.2.l';
update public.shco_full_oes set achieve_tips = '["Develop a structured pre-procedure explanation checklist that the treating doctor completes and signs before any significant intervention, covering the procedure''s purpose, risks, alternatives, and benefits; attach the signed checklist to the patient file.","Train doctors and nurses to use simple, jargon-free language when explaining proposed care and to confirm patient understanding using the teach-back method (''Can you tell me in your own words what we discussed?''); document that teach-back was performed.","Create disease-specific or procedure-specific patient education leaflets in the local language describing the proposed treatment, common risks, and available alternatives; hand these to the patient and note delivery in the clinical record.","Quarterly, audit a sample of inpatient files to confirm that documentation of care explanation (including risks and alternatives) is present and complete before the procedure date; report findings and gaps to the clinical quality team."]'::jsonb where oe_code = 'PRE.2.m';
update public.shco_full_oes set achieve_tips = '["Develop a post-procedure or post-treatment counselling SOP requiring the treating clinician to explain expected outcomes and potential complications within 24 hours of a procedure; document this discussion in the patient''s progress notes with clinician signature.","Create complication-awareness fact sheets for the 10 most frequently performed procedures; give these to patients after the procedure is explained and note in the clinical record that the handout was provided and discussed.","Train all doctors to document a structured ''expected outcome'' note in the patient file that captures what results were communicated, what complications were mentioned, and whether the patient''s questions were addressed; audit this note monthly.","Include a patient satisfaction survey question: ''Were you informed about what to expect and possible complications?'' Track monthly scores as a quality indicator and use low scores to trigger targeted retraining of the relevant clinical team."]'::jsonb where oe_code = 'PRE.2.n';
update public.shco_full_oes set achieve_tips = '["Implement a policy requiring the treating doctor to discuss the initial care plan with the patient and/or family within 12 hours of admission; record this discussion in the clinical notes with the patient''s agreement or concerns documented.","Collect data monthly on how often care plan modifications are documented as occurring ''in consultation with the patient/family''; set a target (e.g., 90% of plan changes documented as discussed) and display trend data as before/after evidence.","Introduce a ''shared care plan'' section in the patient record where the patient or family can sign to confirm they were involved in planning decisions; track the proportion of files where this signature is present and report monthly to the medical committee.","Conduct patient interviews post-discharge (via phone or exit survey) specifically asking whether they felt involved in their care plan; compile responses quarterly to demonstrate measurable improvement in participatory care over successive assessment periods."]'::jsonb where oe_code = 'PRE.2.o';
update public.shco_full_oes set achieve_tips = '["Define in a written policy the clinical criteria that trigger a multidisciplinary counselling session (e.g., chronic disease, terminal diagnosis, major surgery, mental health concern); track how many eligible patients received MDT counselling each month versus how many were eligible.","Maintain a multidisciplinary counselling register recording patient name, date, disciplines represented (doctor, dietitian, physiotherapist, social worker, etc.), topics discussed, and patient response; present this register as outcome evidence during assessments.","Set a measurable target for MDT counselling uptake (e.g., 100% of cancer patients receive at least one session before discharge) and track actual achievement monthly; display a trend chart showing improvement from the baseline before this process was formalised.","Collect patient feedback specifically on MDT counselling sessions using a brief structured form; analyse responses quarterly to identify gaps in information provided or disciplines missing from sessions, and adjust staffing or scheduling accordingly."]'::jsonb where oe_code = 'PRE.2.p';
update public.shco_full_oes set achieve_tips = '["Create a master list of all procedures, treatments, and situations that legally and ethically require informed consent under applicable Indian laws and NABH standards; circulate this list to all clinical departments and review it annually for updates.","Implement a hard-stop in the pre-procedure checklist — no procedure begins unless the consent form is present, completed, signed, and counter-signed by the clinician; train theatre and procedure room staff to enforce this checkpoint every time.","Assessors will cross-check patient files against the mandatory consent list — conduct monthly internal file audits verifying 100% consent form compliance for all applicable procedures; log audit results and escalate any gaps to the chief medical officer immediately.","Train all clinical staff on statutory consent requirements (e.g., MTP Act, Transplantation of Human Organs Act, requirements for minor patients) using a yearly competency session; retain attendance records, test scores, and copy of the training content."]'::jsonb where oe_code = 'PRE.3.a';
update public.shco_full_oes set achieve_tips = '["Redesign consent forms to include dedicated fields for: procedure name, specific risks, expected benefits, available alternatives, and name/designation of the person performing the procedure; have the hospital''s legal or quality team review the form annually.","Train all doctors to explain each consent form element to the patient verbally in the patient''s preferred language before requesting a signature; document in the form that verbal explanation was given and that the patient had the opportunity to ask questions.","Assessors will review consent forms and may interview patients to verify understanding — use the teach-back technique after consent counselling and record the patient''s verbatim confirmation in the clinical notes as evidence of comprehension.","Conduct monthly audits of 10 randomly selected consent forms to check that all mandatory fields are completed, the language is clear, and the performing clinician''s name is present; track compliance rate and address deficiencies through immediate departmental feedback."]'::jsonb where oe_code = 'PRE.3.b';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP defining the hierarchy of authorised consent givers when a patient lacks decision-making capacity (e.g., unconscious, minor, mentally incapacitated): specify spouse, parent, adult child, legal guardian in order of priority; get it approved by the medical committee.","Create a surrogate consent form that captures the relationship of the substitute decision-maker to the patient, the basis for acting as surrogate, and the specific consent being given; file this form in the patient record and train admission staff to initiate it immediately when needed.","Train all nurses and doctors to identify when a patient lacks capacity and to activate the surrogate consent pathway without delay; conduct an annual scenario-based training session and maintain attendance records and competency assessment results.","Audit a quarterly sample of files where surrogate consent was used; verify that the authority of the surrogate is documented, the correct form was used, and the clinician''s assessment of the patient''s incapacity is recorded; present findings to the quality committee."]'::jsonb where oe_code = 'PRE.3.c';
update public.shco_full_oes set achieve_tips = '["Update all consent forms to include a mandatory field for the signature and printed name of the performing clinician, distinct from a witness signature; make this a non-negotiable pre-procedure checklist item in theatres and procedure rooms.","Circulate a written directive from the medical superintendent clearly prohibiting delegation of the informed consent explanation and signature to a non-performing staff member (e.g., a nurse or junior doctor collecting blanket signatures); attach this directive to the SOP.","Assessors will interview patients about who explained the consent and ask staff to demonstrate their understanding of this requirement — train all doctors through an orientation module to reinforce that they personally must explain and sign; keep training records.","Conduct monthly random audits of completed consent forms to verify the performer''s name is present and matches the actual operating or performing clinician documented in the procedure notes; record discrepancies and take immediate corrective action."]'::jsonb where oe_code = 'PRE.3.d';
update public.shco_full_oes set achieve_tips = '["Identify the top five languages spoken by your patient population and ensure key patient education materials (rights charter, consent forms, discharge instructions) are available in each; document the translation and approval process for each language version.","Train nurses to assess literacy and language preference at admission using a standardised two-question screen and record the preferred communication mode (verbal, written, pictorial) in the patient file; tailor all education interactions accordingly.","Assessors will observe patient education interactions and may interview patients — have nurses demonstrate using pictorial leaflets or models when patients are illiterate, and document in the nursing notes that education was delivered in the patient''s preferred format.","Audit monthly a sample of patient education records to verify that the language used and format chosen are documented; track the proportion of files where this field is completed and present the compliance rate at the monthly quality meeting."]'::jsonb where oe_code = 'PRE.4.a';
update public.shco_full_oes set achieve_tips = '["Develop a structured medication counselling SOP requiring the dispensing pharmacist or nurse to counsel every patient on each new medication''s purpose, correct dose, frequency, and key side effects; create a medication counselling checklist to be signed by the counsellor and filed in the record.","Prepare medication information cards for the 20 most commonly prescribed drugs in the hospital listing the drug name, key side effects, storage conditions, and what to do in an emergency; give these cards to patients alongside their medicines.","Train pharmacists and nurses on medication counselling using a competency-based programme; conduct annual observed structured assessments where the trainer watches a live counselling session and scores it against a checklist; retain score sheets.","Monthly, audit a sample of discharge files for evidence of medication counselling documentation; track the percentage of files with completed counselling checklists and present trend data at the clinical quality committee meeting."]'::jsonb where oe_code = 'PRE.4.b';
update public.shco_full_oes set achieve_tips = '["Develop disease-specific diet and food-drug interaction education sheets for common conditions managed in the hospital (e.g., diabetes, hypertension, TB, anaemia); have these reviewed by the dietitian and approved by the medical committee before use.","Create an SOP requiring the dietitian or nurse to provide food-drug interaction counselling for all patients on anticoagulants, antiepileptics, antihypertensives, or antibiotics; document the counselling session in the patient file with the counsellor''s signature.","Train nursing staff and pharmacists on the most clinically significant food-drug interactions relevant to the hospital''s case mix; conduct annual training with a competency checklist and retain attendance and assessment records for assessor review.","Include immunisation status review in the admission checklist for paediatric and postnatal patients; document that immunisation advice was provided, with the date and responsible staff member recorded in the clinical notes."]'::jsonb where oe_code = 'PRE.4.c';
update public.shco_full_oes set achieve_tips = '["Create disease-specific patient education modules for the top 10 diagnoses in the hospital, covering what the disease is, how it progresses, potential complications, and practical prevention steps; approve these through the medical committee and update them annually.","Implement an SOP requiring the treating doctor or nurse to provide structured disease education at least once during every inpatient stay and to document the session — topic covered, patient''s understanding, and questions raised — in the clinical notes.","Train nursing staff to deliver disease education using a teach-back approach; conduct annual competency assessments with a structured observation tool and retain the completed assessment forms as evidence of staff capability.","Develop a disease education checklist for discharge; ensure every patient leaves with a written summary of their diagnosis, key warning signs of complications, and when to seek emergency care; document in the discharge summary that the checklist was completed and handed over."]'::jsonb where oe_code = 'PRE.4.d';
update public.shco_full_oes set achieve_tips = '["Develop a patient-facing hand hygiene education card with illustrations showing the 6-step hand wash technique; distribute it to every admitted patient within 2 hours of admission and ask nursing staff to demonstrate the technique at the bedside; document delivery in the nursing notes.","Create an SOP requiring nurses to educate patients and visitors about cough etiquette, correct mask use, and not touching wound dressings; include this education in the admission nursing checklist and retain completed checklists in patient files.","Display HAI prevention posters (hand hygiene, respiratory hygiene, safe disposal of sharps) in all patient wards and OPD waiting areas in local languages; photograph displays with date stamps and include them in the infection control audit records.","Conduct quarterly patient feedback surveys asking whether they were educated about infection prevention during their stay; track the ''yes'' response rate as an HAI education indicator and present trend data at the infection control committee meeting."]'::jsonb where oe_code = 'PRE.4.e';
update public.shco_full_oes set achieve_tips = '["Introduce a structured SBAR (Situation-Background-Assessment-Recommendation) or equivalent communication framework for all clinician-to-patient handovers and family briefings; train staff on its use and verify application through monthly supervisor observations documented on a checklist.","Conduct an annual patient communication satisfaction survey with questions specifically targeting clarity, compassion, and responsiveness; analyse results by department and share findings with department heads to drive targeted communication improvement plans.","Set up a designated ''Family Communication Area'' — a private, quiet space where doctors can speak with families without interruption; track utilisation monthly as an indicator of structured family communication practice, and include it in the quality dashboard.","Establish a daily scheduled time (e.g., 5–6 PM) for ward doctors to meet with families of inpatients; record attendance and topics discussed in the ward communication log; review compliance monthly and address wards where this practice is inconsistent."]'::jsonb where oe_code = 'PRE.4.f';
update public.shco_full_oes set achieve_tips = '["Display the hospital''s pricing policy notice (covering OPD, emergency, ICU, and inpatient charges) prominently at each of these four entry points; ensure the display is in the local language and at eye level; document display locations in the facility audit checklist.","Train admission and billing staff to verbally explain the pricing structure applicable to each care setting at the point of patient registration; include a pricing policy briefing script in the staff induction manual and retain training records.","Assessors will interview patients about cost awareness — brief every patient and family at admission about applicable charges for their setting; have them sign an acknowledgement in the admission form confirming they received this information.","Conduct monthly audits of admission records to verify that the pricing-awareness acknowledgement field is completed for every admission; track compliance rates and share results at the billing department''s monthly review meeting with corrective actions documented."]'::jsonb where oe_code = 'PRE.5.a';
update public.shco_full_oes set achieve_tips = '["Place a current, dated tariff list at the OPD reception, billing counter, and ward nursing station in a clearly visible format; designate one staff member per shift as responsible for ensuring the tariff list is available and up to date at all times.","Develop an SOP requiring the tariff list to be reviewed and reprinted every time prices change, with the revision date printed on every copy; maintain a tariff list revision log showing old and new price, date of change, and approving authority.","Train billing and front-desk staff to proactively offer the tariff list to patients who ask about costs and to explain items if needed; include this expectation in the customer service training module and verify through quarterly mystery-patient exercises.","Conduct monthly checks to confirm the tariff list is physically present at all three mandatory locations; record the check result and any corrective action in the facility inspection register, and escalate repeated non-compliance to hospital management."]'::jsonb where oe_code = 'PRE.5.b';
update public.shco_full_oes set achieve_tips = '["Develop a cost-estimate SOP requiring the billing team to generate and share a written estimated cost breakdown with every patient at or before admission; include an acknowledgement signature block in the billing form for the patient to confirm they received and understood the estimate.","Create standardised cost-estimate templates for the 20 most common DRGs or procedures in the hospital; update these templates quarterly to reflect current prices and make them immediately accessible to billing staff on the intranet or physical folder.","Train billing counsellors to walk patients through the estimate line by line, highlighting which items are fixed versus variable; include role-play practice in annual training and retain competency assessment records showing staff can handle cost queries confidently.","Monthly, audit a sample of billing records to verify cost-estimate forms are present, signed, and provided before the procedure or admission; track the compliance rate and present findings at the finance committee''s monthly meeting."]'::jsonb where oe_code = 'PRE.5.c';
update public.shco_full_oes set achieve_tips = '["Implement a policy requiring the treating doctor to notify the billing team within 2 hours whenever the care plan changes significantly (e.g., escalation to ICU, addition of surgery, change in drug regimen); the billing team then provides a revised cost estimate to the family within the next hour.","Maintain a ''care plan change'' log that records the date of change, nature of change, date the family was informed of financial implications, and family signature of acknowledgement; track the proportion of care plan changes where family was informed within the defined time frame.","Measure monthly the percentage of care plan changes where financial impact was communicated to the family before the change was implemented; set a target (e.g., 90%) and display before/after trend data showing improvement since the policy was introduced as evidence of achievement.","Collect discharge patient feedback specifically asking: ''Were you informed of cost changes when your treatment plan changed?'' Compile responses quarterly, track the approval rate as an outcome metric, and present improvement data to the billing and clinical quality committees."]'::jsonb where oe_code = 'PRE.5.d';
update public.shco_full_oes set achieve_tips = '["Design a validated patient satisfaction survey with at least 10 questions covering clinical care, nursing, food, billing, and cleanliness; administer it to every inpatient at discharge and to a sample of OPD patients monthly; maintain completed survey forms as records.","Develop an SOP for the feedback collection process specifying: who administers the survey, in which language, by which method (paper/digital/verbal for illiterate patients), and where forms are stored; train designated staff and retain their training records.","Establish a monthly feedback analysis meeting where the quality team reviews satisfaction scores by department, identifies outlier departments, and assigns corrective actions with owners and deadlines; file meeting minutes as evidence of systematic use of patient feedback.","Display monthly patient satisfaction results on a notice board or digital screen in a public area of the hospital; include the current score, last month''s score, and a brief note on what action was taken based on feedback; update this display every month without fail."]'::jsonb where oe_code = 'PRE.6.a';
update public.shco_full_oes set achieve_tips = '["Go beyond satisfaction scores by capturing qualitative patient experience using structured patient narrative interviews or open-ended written feedback forms; aim to conduct at least 5 narrative interviews per month and record verbatim quotes for quality improvement use.","Implement a real-time experience capture tool such as a bedside feedback terminal, QR-code-linked form, or daily nurse-led brief structured conversation; document each interaction in a patient experience log with date, ward, and any issue flagged.","Analyse patient experience data monthly using thematic categorisation (e.g., communication, empathy, environment, wait times); prepare a quarterly patient experience report highlighting recurring themes and improvement actions taken; file reports for assessor review.","Benchmark patient experience scores against your own previous quarters to demonstrate a progressive improvement trend; display a multi-quarter trend chart in the quality office and present it at the hospital''s quality committee meeting as evidence of sustained excellence."]'::jsonb where oe_code = 'PRE.6.b';
update public.shco_full_oes set achieve_tips = '["Appoint a designated Grievance Redressal Officer (GRO) by name and display their name, photograph, and contact number prominently at OPD, reception, and all wards; ensure every patient is told the GRO''s name at admission and document this in the admission checklist.","Maintain a complaints register with columns for: complaint date, complainant name, nature of complaint, date acknowledged, date resolved, resolution details, and complainant''s satisfaction with resolution; keep this register updated daily and available for immediate assessor review.","Assessors will interview patients and staff about the complaints process — train all patient-facing staff to explain in two minutes exactly how a patient can lodge a complaint, who handles it, and how long resolution takes; validate this through annual role-play assessments.","Conduct quarterly reviews of the complaints register to verify every complaint was acknowledged within 24 hours and resolved within the defined timeframe; calculate the resolution compliance rate and escalate overdue complaints to hospital management with a written explanation."]'::jsonb where oe_code = 'PRE.6.c';
update public.shco_full_oes set achieve_tips = '["Define in the complaints SOP specific analysis timeframes: individual complaints reviewed within 48 hours, aggregate analysis monthly, trend analysis quarterly; document each analysis in the quality register with the date completed and the analyst''s name.","Perform root-cause analysis for all repeat complaints and any serious complaint; document a formal CAPA plan with corrective action, preventive measure, responsible person, and target closure date; track open CAPA items on a live register updated weekly.","Measure monthly the percentage of complaints resolved within the defined timeframe and the percentage of CAPA actions closed on time; display a trend chart showing both metrics over the past 12 months as before/after evidence of a functioning quality improvement cycle.","Present the quarterly complaint analysis report to the hospital''s quality or management committee meeting; include a summary of root causes identified, actions taken, and impact measured; retain signed meeting minutes as documentary evidence of leadership engagement with patient feedback outcomes."]'::jsonb where oe_code = 'PRE.6.d';

-- HIC (36 OEs)
update public.shco_full_oes set achieve_tips = '["Maintain a written Hospital Infection Prevention and Control (HIC) programme document that clearly outlines goals, scope, and responsibilities; review it at least annually and update it whenever new risks emerge.","Ensure assessors can immediately access the HIC programme document during visits — file it in a dedicated infection control binder kept at the nursing station or quality office.","Conduct quarterly internal audits against the HIC programme objectives and record findings in a logbook so staff can demonstrate ongoing programme implementation to assessors.","Brief all clinical and support staff during induction on the HIC programme goals so they can accurately describe programme aims and their own role when interviewed by assessors."]'::jsonb where oe_code = 'HIC.1.a';
update public.shco_full_oes set achieve_tips = '["Use the NABH Infection Control Assessment Tool checklist to formally score your programme every six months; document the scores, identify gaps, and record the improvement actions taken.","Assign the Infection Control Nurse to lead each assessment tool review cycle and file completed tool forms with dates and signatures so trend improvement is visible over time.","After each assessment tool review, prepare a one-page gap-closure summary and present it to the Infection Control Committee; retain minutes of this discussion as evidence.","Track your assessment tool scores on a wall-mounted dashboard in the infection control office so staff and assessors can see whether ratings are improving cycle over cycle."]'::jsonb where oe_code = 'HIC.1.b';
update public.shco_full_oes set achieve_tips = '["Constitute a multidisciplinary Infection Control Committee with members from medicine, nursing, microbiology, housekeeping, and administration; publish the committee''s terms of reference and meeting schedule on the hospital notice board.","Hold Infection Control Committee meetings at least quarterly; prepare formal agenda and minutes, file them chronologically, and ensure they are readily available for assessor review.","Designate a trained Infection Control Nurse or Officer to the Infection Control Team with clearly defined daily responsibilities; display their name and contact on every ward.","Maintain an attendance register for every committee meeting and cross-reference action items with responsible persons and deadlines so the team can demonstrate coordinated follow-up."]'::jsonb where oe_code = 'HIC.1.c';
update public.shco_full_oes set achieve_tips = '["Develop and implement an IEC (Information, Education, Communication) calendar for patients, visitors, and community members covering topics such as hand hygiene, respiratory etiquette, and safe disposal of waste.","Display visual IEC materials — posters, pamphlets, and digital displays — in OPD waiting areas, casualty, and patient wards in the local language to maximise community reach.","Document community outreach activities, including health camps and school visits on infection prevention, with attendance records and photographs filed in the IEC register.","Establish a written pandemic/outbreak response protocol that specifies activation triggers, communication channels, and coordination with local health authorities; train staff annually and record participation."]'::jsonb where oe_code = 'HIC.1.d';
update public.shco_full_oes set achieve_tips = '["Prepare an annual infection control budget proposal listing required PPE, disinfectants, surveillance tools, and training costs; obtain management approval in writing and retain the signed document.","Maintain a stock register for infection control consumables (gloves, masks, hand rub, colour-coded bags) with minimum stock levels defined; replenish before stocks fall below threshold.","Ensure assessors can observe functional hand hygiene stations — running water, soap, and alcohol-based hand rub — at every point of care; log any deficiency and corrective action taken.","Document management review of infection control resource requests in committee minutes so staff can demonstrate that leadership actively supports the programme."]'::jsonb where oe_code = 'HIC.1.e';
update public.shco_full_oes set achieve_tips = '["Designate at least one room with negative pressure or physical separation capability for isolation; label it clearly and maintain an up-to-date inventory of isolation equipment (gowns, masks, dedicated equipment).","Post a standard isolation protocol on the door of every isolation room so nursing staff can implement barrier nursing without referencing a separate manual.","Record each patient placed in isolation — date, indication, precaution type, and duration — in a dedicated isolation register; make this register available for assessor review.","Conduct monthly mock drills for barrier nursing procedures and document observations and corrective actions to show assessors that staff competency in isolation is actively maintained."]'::jsonb where oe_code = 'HIC.1.f';
update public.shco_full_oes set achieve_tips = '["Display the standard precautions bundle (gloves, mask, gown, eye protection, safe sharps disposal) as a laminated quick-reference card at every nursing station and procedure room.","Conduct unannounced spot checks by the Infection Control Nurse at least weekly to observe whether staff are using PPE correctly; record findings and share feedback with department heads.","Ensure a signed standard precautions compliance checklist is completed for each clinical area every week; file these checklists so assessors can trace compliance trends over time.","Include standard precautions adherence as a standing agenda item in ward staff meetings, and document any deviations along with corrective steps taken."]'::jsonb where oe_code = 'HIC.2.a';
update public.shco_full_oes set achieve_tips = '["Install alcohol-based hand rub dispensers at every bed entry point, procedure trolley, and exit from each ward; check and refill them daily and log refill dates.","Train all clinical staff, housekeeping, and dietary personnel in the WHO 5 Moments for Hand Hygiene; maintain training attendance records that assessors can review.","Conduct monthly hand hygiene compliance audits using the WHO observation tool; post the results on the ward notice board and set a minimum 80% compliance target.","Ensure assessors can observe and interview staff on the correct hand hygiene technique — post step-by-step visual guides above every sink and hand rub dispenser throughout the facility."]'::jsonb where oe_code = 'HIC.2.b';
update public.shco_full_oes set achieve_tips = '["Draft a written Transmission-Based Precautions SOP covering contact, droplet, and airborne categories with clear activation criteria; obtain infection control committee approval and circulate to all wards.","Train nursing and housekeeping staff on donning and doffing sequences for each precaution category; conduct return-demonstration sessions and record staff names, dates, and competency scores.","Maintain a precaution-type assignment register linking each patient to the appropriate precaution level; update it within two hours of a new order and verify it during nursing handover.","During assessments, staff should be able to describe from memory which PPE is required for each transmission category — reinforce this through monthly awareness sessions and post visual cues in isolation areas."]'::jsonb where oe_code = 'HIC.2.c';
update public.shco_full_oes set achieve_tips = '["Standardise a one-drug, one-patient, one-syringe policy through a written SOP and display it at every medication preparation area; include a prohibition on multi-dose vial sharing where feasible.","Audit IV line insertion and maintenance bundles (aseptic technique, dressing changes, access frequency) weekly using a structured checklist; document findings and corrective actions.","Ensure all clinical staff can demonstrate safe needle recapping-free technique and proper sharps disposal during assessor observation — conduct competency checks at least twice a year.","Record all needlestick and sharps injuries in an incident register and review them monthly in the ICC to identify systemic gaps in safe injection practice."]'::jsonb where oe_code = 'HIC.2.d';
update public.shco_full_oes set achieve_tips = '["Draft an Antimicrobial Usage Policy defining approved empirical regimens, restricted antibiotics requiring approval, and de-escalation criteria; have it ratified by the medical committee and pharmacy.","Ensure the policy is accessible at every ward as a printed formulary guide or electronic quick-reference; orient all prescribers during induction and document their acknowledgement.","Maintain a restricted antibiotic approval register recording prescriber name, patient ID, indication, approving authority, and date for every restricted drug issued.","Review the antimicrobial usage policy annually using local antibiogram data; document the review meeting with signatures and update the policy version number and effective date."]'::jsonb where oe_code = 'HIC.2.e';
update public.shco_full_oes set achieve_tips = '["Generate a monthly antibiotic consumption report from pharmacy records, categorised by ward and drug class; present it to the ICC with comments on deviations from the approved policy.","Conduct quarterly prescription audits on a random sample of 10 inpatient files per ward; record findings in an audit register and give prescribers individual feedback within one week.","Ensure assessors can observe the process by which a restricted antibiotic prescription is reviewed and approved — walk them through a live or recent example using the approval register.","Post the list of restricted antibiotics requiring senior approval on every ward and in the pharmacy; train ward pharmacists to flag non-compliant prescriptions before dispensing."]'::jsonb where oe_code = 'HIC.2.f';
update public.shco_full_oes set achieve_tips = '["Establish a formal Antibiotic Stewardship Programme (ASP) with a written charter, designated ASP team (physician, microbiologist, pharmacist), and clear goals such as reducing days of antibiotic therapy.","Implement prospective audit and feedback: the ASP team reviews all patients on antibiotics beyond 72 hours each week and provides written recommendations to prescribers; file all recommendations.","Use local antibiogram data updated at least annually to guide empirical prescribing guidelines; display the antibiogram summary in the ward and ICU for quick prescriber reference.","Track monthly ASP outcome metrics — antibiotic defined daily doses per 100 bed-days, restricted drug usage, and culture positivity rates — and present trend data to hospital leadership quarterly."]'::jsonb where oe_code = 'HIC.2.g';
update public.shco_full_oes set achieve_tips = '["Document all engineering infection control measures (HVAC maintenance schedules, air exchange rates for OT and ICU, water system flushing logs) in a dedicated preventive maintenance register.","Ensure HVAC filters in OT, ICU, and isolation rooms are cleaned or replaced per manufacturer schedule; maintain a filter change log with dates and technician signatures as evidence.","Conduct quarterly water quality testing for Legionella and coliforms in plumbing systems serving patient care areas; file test reports and any remediation steps taken.","During assessor walk-throughs, staff should be able to locate and describe engineering controls in their area — brief housekeeping and facility managers monthly on their specific responsibilities."]'::jsonb where oe_code = 'HIC.3.a';
update public.shco_full_oes set achieve_tips = '["Before any construction or renovation, prepare a written Infection Control Risk Assessment (ICRA) classifying the project type and patient risk level; get ICC sign-off before work begins.","Implement physical containment barriers (sealed plastic sheeting, dedicated construction-area entry points) during any renovation near patient care areas and inspect them daily; log inspection results.","Restrict construction worker movement to approved pathways and ensure they wear masks and shoe covers in transition zones; maintain a sign-in register showing compliance with these controls.","Conduct post-construction environmental cleaning with surface and air monitoring before reopening renovated areas to patients; document clearance inspection results and the date of patient area reactivation."]'::jsonb where oe_code = 'HIC.3.b';
update public.shco_full_oes set achieve_tips = '["Develop written housekeeping SOPs specifying cleaning frequency, detergent-to-water ratios, colour-coded mop and cloth allocations by zone (OT, ward, toilet), and correct disinfectant contact times.","Train all housekeeping staff on the SOPs before deployment; maintain a training register with staff names, trainer name, date, and competency assessment score so assessors can verify training.","Conduct daily supervisor sign-off on cleaning checklists for each area; file completed checklists weekly so a six-month trail of housekeeping compliance is available for review.","Perform random environmental surface swab cultures in high-risk areas (OT, ICU, procedure rooms) monthly; record results and take corrective action within 24 hours if counts exceed limits."]'::jsonb where oe_code = 'HIC.3.c';
update public.shco_full_oes set achieve_tips = '["Ensure all clinical and housekeeping staff are trained in BMW segregation using the colour-coded bag/container system (yellow, red, white/blue, black) per national BMW rules; maintain training records.","Place labelled, foot-operated BMW bins at every point of generation; inspect all bins daily and record inspection findings in a BMW monitoring checklist signed by the floor supervisor.","Maintain a BMW logbook recording daily waste weight by category, transporter details, and manifest numbers; file manifests so assessors can trace the complete chain of custody for one year.","Ensure staff can correctly demonstrate waste segregation and explain safe sharps disposal during assessor observation — conduct quarterly re-training drills and record attendance and observations."]'::jsonb where oe_code = 'HIC.3.d';
update public.shco_full_oes set achieve_tips = '["Draft a linen management SOP covering collection in leakproof bags at point of use, transport routes separated from clean linen, washing temperature standards, and inspection before re-issue.","Train housekeeping and nursing staff on linen handling procedures; verify competency through direct observation of bag labelling and transport practices and record findings in a supervision log.","Conduct weekly audits of the linen flow — from soiled collection to clean storage — using a structured checklist; file completed checklists and escalate any hygiene lapses to the laundry supervisor.","Maintain clean linen storage in a dedicated, ventilated area off the floor on shelving; inspect storage conditions weekly and record in the linen audit register."]'::jsonb where oe_code = 'HIC.3.e';
update public.shco_full_oes set achieve_tips = '["Develop a written kitchen sanitation SOP covering surface cleaning schedules, equipment sanitisation frequencies, food storage temperatures, and personal hygiene requirements for kitchen staff.","Conduct daily temperature checks on refrigerators, hot-holding equipment, and cooked food; record readings in a food safety logbook and take immediate corrective action if temperatures deviate.","Arrange annual food handler medical examinations and hygiene training; maintain certificates and training records for each kitchen staff member in a personnel file accessible to assessors.","Perform quarterly kitchen hygiene audits using a structured checklist covering pest control, waste disposal, hand washing facilities, and food cross-contamination risks; document findings and corrective actions."]'::jsonb where oe_code = 'HIC.3.f';
update public.shco_full_oes set achieve_tips = '["Implement the CAUTI prevention bundle as a written SOP: sterile insertion technique, closed drainage system, daily catheter necessity review, and prompt removal documentation; train all nursing staff.","Maintain a catheter insertion and removal register for every indwelling urinary catheter patient, recording insertion date, indication, daily review decision, and removal date.","Track monthly CAUTI rates per 1,000 catheter-days by ward; display trending data on the infection control dashboard and present to the ICC with analysis of contributing factors.","Ensure assessors can observe nurses performing catheter care correctly during ward rounds and verify that catheter necessity is reviewed and documented in the patient record every 24 hours."]'::jsonb where oe_code = 'HIC.4.a';
update public.shco_full_oes set achieve_tips = '["Implement the VAP/VAC prevention bundle SOP covering head-of-bed elevation at 30–45 degrees, oral care every four hours, cuff pressure checks, and subglottic secretion drainage where applicable.","Maintain a VAP bundle compliance checklist in every ventilated patient''s chart; the nurse on each shift must complete and sign the checklist before handover.","Calculate and record monthly VAP/VAC rates per 1,000 ventilator-days in the ICU; share trend data with ICU nursing and physician leads and document discussions in ICC minutes.","Train all ICU nursing staff on VAP bundle elements annually and conduct unannounced competency observations; record observation findings and any corrective training provided."]'::jsonb where oe_code = 'HIC.4.b';
update public.shco_full_oes set achieve_tips = '["Document the CLABSI prevention bundle SOP covering maximal barrier precautions at insertion, chlorhexidine skin antisepsis, optimal catheter site selection, and daily removal-necessity assessment.","Maintain a central line insertion checklist in every patient file where a central venous catheter is placed; the inserting clinician and supervising nurse must both sign the completed checklist.","Record monthly CLABSI rates per 1,000 central line-days broken down by ICU and non-ICU areas; review data at ICC meetings and implement targeted corrective actions when rates rise.","Conduct at least biannual simulation-based training on central line insertion and maintenance for all ICU medical and nursing staff; retain attendance records and competency assessment results."]'::jsonb where oe_code = 'HIC.4.c';
update public.shco_full_oes set achieve_tips = '["Implement the SSI prevention bundle as a written SOP: preoperative skin preparation, timely antibiotic prophylaxis (within 60 minutes of incision), normothermia, and glucose control; ensure surgical team sign-off on each element.","Use a pre-operative safety checklist (or integrate SSI bundle compliance into the surgical safety checklist) and file completed checklists in the patient''s operative record.","Conduct 30-day post-discharge SSI surveillance for all elective surgical procedures; record SSI cases, wound classification, and outcomes in a surgical site infection register.","Calculate and trend monthly SSI rates by procedure category; present data to the surgical team and ICC, and document any targeted improvement actions such as antibiotic protocol revisions."]'::jsonb where oe_code = 'HIC.4.d';
update public.shco_full_oes set achieve_tips = '["Develop a written Occupational Health SOP covering pre-employment screening, annual health checks, hepatitis B vaccination, and respiratory fit-testing for staff working in high-risk areas.","Maintain a staff immunisation register recording vaccine name, dose, date, and batch number for each employee; update it whenever new staff join and make it available for assessor review.","Conduct annual occupational health training sessions covering transmission prevention, correct PPE use, and early symptom reporting; document attendance and content covered.","Establish a confidential mechanism for staff to report health concerns or potential occupational exposures; log all reports and ensure a designated occupational health officer reviews each case within 24 hours."]'::jsonb where oe_code = 'HIC.4.e';
update public.shco_full_oes set achieve_tips = '["Display a laminated Post-Exposure Prophylaxis (PEP) protocol at every nursing station and in the emergency department specifying steps to take within 2 hours of a blood-body fluid exposure.","Maintain a PEP register recording every exposure incident: date, staff member, nature of exposure, source patient details (if known), PEP drugs administered, and follow-up serology dates.","Ensure a stock of first-line PEP medications is available 24/7 in the pharmacy or emergency department; document a monthly stock check so availability is never a barrier to timely treatment.","Brief all new staff on PEP protocol during induction and reinforce annually; ensure staff can accurately describe the protocol steps when interviewed by assessors."]'::jsonb where oe_code = 'HIC.4.f';
update public.shco_full_oes set achieve_tips = '["Establish a formal HAI surveillance programme with a written scope document identifying target infections (CAUTI, CLABSI, VAP, SSI), definitions used, data sources, and collection frequency.","Assign the Infection Control Nurse responsibility for weekly active surveillance rounds across all wards; record all potential HAI cases in a surveillance register with patient ID, ward, infection type, and onset date.","Generate monthly infection rate reports per 1,000 device-days or patient-days by ward; trend data over at least six months should be available in graphical form for assessors to review.","Ensure ward staff can describe the HAI surveillance process and know how to report a suspected infection to the infection control team when interviewed during assessments."]'::jsonb where oe_code = 'HIC.5.a';
update public.shco_full_oes set achieve_tips = '["Use the WHO hand hygiene observation tool to conduct structured audits in each ward at least monthly; record individual observations, calculate compliance percentages, and file results by ward and date.","Post ward-level hand hygiene compliance rates on a visual board updated monthly so staff, patients, and assessors can immediately see current performance and improvement trends.","Set a minimum compliance target (e.g., 80%) and trigger an automatic retraining session for any ward falling below target; document the retraining and re-audit within four weeks.","Ensure assessors can observe the audit process live or review completed observation forms covering at least the past three months across all clinical areas."]'::jsonb where oe_code = 'HIC.5.b';
update public.shco_full_oes set achieve_tips = '["Set up an MDRO and highly virulent organism surveillance protocol that links microbiology laboratory reports to the infection control team within 24 hours of a positive culture result.","Maintain a dedicated MDRO register recording organism type, patient ID, ward, isolation date, and decolonisation or contact precaution measures initiated for each confirmed case.","Calculate monthly MDRO incidence rates (new cases per 1,000 patient-days) and track trends on the infection control dashboard; present data with analysis to the ICC each quarter.","Ensure the microbiology lab flags all MDRO isolates on the report with a standardised alert sticker or electronic alert code so clinical staff and the infection control team are notified simultaneously."]'::jsonb where oe_code = 'HIC.5.c';
update public.shco_full_oes set achieve_tips = '["Define outbreak thresholds in writing (e.g., two or more linked cases of the same organism within 72 hours) and activate a documented outbreak response protocol whenever the threshold is crossed.","Maintain an outbreak investigation file for each event, including line listing of cases, environmental investigation results, control measures implemented, and date of outbreak resolution.","Establish a communication tree so that the Medical Superintendent, ICC chair, and relevant ward heads are notified within four hours of a declared outbreak; document all notifications and responses.","Conduct a post-outbreak debrief meeting within two weeks of resolution; prepare a written lessons-learned report and implement at least one systemic corrective action to prevent recurrence."]'::jsonb where oe_code = 'HIC.5.d';
update public.shco_full_oes set achieve_tips = '["Develop a housekeeping surveillance checklist that covers surface cleanliness, colour-coded equipment use, clean-to-dirty workflow, and disinfectant preparation; complete it daily per ward with supervisor signature.","Perform environmental cultures (surface swabs and air settle plates) in the OT, ICU, and procedure rooms monthly; record results and initiate corrective cleaning if colony counts exceed defined limits.","Compile a monthly housekeeping surveillance summary comparing findings across wards; present to the ICC and share feedback with the housekeeping team lead within 48 hours.","Ensure assessors can observe a supervisor conducting a housekeeping audit in real time or review at least three months of completed audit checklists filed in the infection control office."]'::jsonb where oe_code = 'HIC.5.e';
update public.shco_full_oes set achieve_tips = '["Prepare a monthly infection surveillance data analysis report that calculates rates, identifies trends, and highlights outliers; circulate the report to department heads and ICC members within the first week of the following month.","Document all corrective and preventive actions (CAPAs) arising from surveillance data in a CAPA register with responsible person, deadline, and status; review open CAPAs at every ICC meeting.","Provide formal written feedback on surveillance findings to ward nursing-in-charges each month; maintain copies of all feedback communications so assessors can trace the feedback loop.","Present surveillance trend graphs at the quarterly medical staff meeting and record attendance and discussion in the minutes; this demonstrates that data drives clinical decision-making at all levels."]'::jsonb where oe_code = 'HIC.5.f';
update public.shco_full_oes set achieve_tips = '["Ensure the CSSD has clearly demarcated dirty, clean, packing, and sterile storage zones with physical barriers or spatial separation; label each zone with a permanent sign.","Document the zone layout in a floor plan filed in the CSSD SOP manual; during assessor visits, the CSSD in-charge should be able to walk assessors through the workflow from soiled receipt to sterile dispatch.","Verify that the CSSD ventilation provides positive pressure in clean/sterile areas and negative pressure or neutral in the dirty area; maintain HVAC maintenance records confirming this configuration.","Conduct a quarterly CSSD space and workflow audit using a structured checklist; document any congestion, cross-contamination risk, or workflow deviation and implement corrective measures within 30 days."]'::jsonb where oe_code = 'HIC.6.a';
update public.shco_full_oes set achieve_tips = '["Develop written SOPs for each stage of instrument processing — decontamination, inspection, packing, sterilisation cycle selection, cool-down, and sterile storage — with step-by-step instructions and staff sign-off requirements.","Train all CSSD staff on the SOPs before they work independently; conduct competency assessments with return demonstrations and record each staff member''s name, assessment date, and result.","Maintain a sterilisation load log for every cycle run, recording load number, contents, cycle parameters, indicator results, and staff initials; this log must be available for at least two years.","Ensure assessors can observe CSSD staff correctly labelling sterile packs with load number, sterilisation date, expiry date, and autoclave number, and verify this against the load log entries."]'::jsonb where oe_code = 'HIC.6.b';
update public.shco_full_oes set achieve_tips = '["Identify all single-use items currently being reprocessed and validate each against a written reprocessing SOP that meets manufacturer guidance and regulatory requirements; list approved items in a policy document.","Maintain a reprocessing register recording item name, number of reprocessing cycles completed, visual inspection results, sterilisation parameters, and the authorising supervisor''s signature for every batch.","Set a clear maximum reprocessing cycle limit for each approved single-use item and retire items that reach this limit immediately; document retirement and disposal in the register.","Train CSSD staff on how to inspect items for integrity loss (cracks, discolouration, deformation) before reprocessing; conduct six-monthly competency checks and file observation records."]'::jsonb where oe_code = 'HIC.6.c';
update public.shco_full_oes set achieve_tips = '["Conduct and document Bowie-Dick tests daily for pre-vacuum autoclaves and biological indicator tests weekly for all sterilisers; file the results in a validation logbook with dates and pass/fail outcomes.","Perform quarterly physical parametric monitoring (temperature, pressure, time) calibration checks on all sterilisers using calibrated measuring instruments; document calibration reports and retain them.","Record chemical indicator (Class 5 or 6 integrator) results for every sterilisation pack and mark the pack as released only when the indicator confirms adequate process exposure; file batch records accordingly.","Present the sterilisation validation logbook for assessor review showing at least six months of continuous daily and weekly test results; highlight any failed tests and the corrective actions taken."]'::jsonb where oe_code = 'HIC.6.d';
update public.shco_full_oes set achieve_tips = '["Document a written recall SOP specifying the trigger criteria for recall (e.g., failed biological indicator, steriliser malfunction), the tracing method using load logs, and the quarantine procedure for suspect items.","When a sterilisation failure is detected, immediately quarantine all items from the affected load, trace them to patient use using the load log, and document every step in a recall incident report.","Notify the clinical departments that received potentially non-sterile items within two hours of a confirmed failure; file all communication records as part of the recall incident file.","Conduct a root cause analysis after every recall event and implement a documented corrective action; review recall incident reports at the next ICC meeting to verify effectiveness of the corrective measures."]'::jsonb where oe_code = 'HIC.6.e';

-- PSQ (28 OEs)
update public.shco_full_oes set achieve_tips = '["Form a multi-disciplinary patient safety committee with members from medical, nursing, pharmacy, and administration, and hold documented monthly meetings to review safety concerns.","Maintain a register of committee attendance, agenda items, and action-taken records so assessors can verify active participation across disciplines.","During assessor interviews, department heads should be prepared to describe their role in the patient safety committee and cite at least one improvement driven by the committee.","Conduct periodic ward observations to ensure safety committee decisions — such as fall prevention protocols or hand hygiene drives — are visibly implemented at the point of care."]'::jsonb where oe_code = 'PSQ.1.a';
update public.shco_full_oes set achieve_tips = '["Schedule quarterly patient safety programme review meetings and document findings, gaps identified, and improvement actions agreed upon during each session.","Maintain a rolling log of safety improvement opportunities with target dates, responsible persons, and closure status so progress is visible at each review cycle.","Train the quality coordinator to present trend data — such as incident rates or near-miss patterns — at each review meeting to drive evidence-based improvement decisions.","Create a standard review template that captures what was reviewed, what changed, and what the next cycle will focus on, making audit readiness straightforward."]'::jsonb where oe_code = 'PSQ.1.b';
update public.shco_full_oes set achieve_tips = '["Use a Failure Mode and Effects Analysis (FMEA) tool annually on at least one high-risk process such as medication administration or patient handover, and document findings.","Maintain records of proactive risk assessments including risk registers, severity ratings, and the corrective actions taken as a result of each analysis.","Designate a small team each quarter to walk through a critical care area and identify potential hazards before they cause incidents, logging observations and actions formally.","During assessor walkthroughs, staff should be able to explain how a recent risk analysis led to a visible process change, such as a new checklist or labelling practice."]'::jsonb where oe_code = 'PSQ.1.c';
update public.shco_full_oes set achieve_tips = '["Download and display the current WHO or NABH patient safety goals and create a facility-specific action plan showing how each goal is operationalised in your setting.","Assign ownership of each patient safety goal to a department head and maintain documented evidence of implementation, such as signed checklists, training records, or audit results.","Conduct brief daily safety huddles at shift handovers where staff confirm adherence to at least two patient safety goals, and log these huddles as records for assessors.","Display visual cues — wristbands, colour-coded alerts, medication labels — that directly map to adopted patient safety goals so assessors can observe implementation during walkthroughs."]'::jsonb where oe_code = 'PSQ.1.d';
update public.shco_full_oes set achieve_tips = '["Constitute a formal quality improvement committee with representatives from clinical and non-clinical departments, document its charter, terms of reference, and meeting minutes.","Maintain a master quality improvement plan listing active projects, assigned owners, timelines, and current status, reviewed and updated at every committee meeting.","Ensure staff at all levels can articulate the organisation''s quality priorities when interviewed by assessors — conduct internal mock interviews as part of QI awareness training.","Observe quality improvement activities in practice during internal audits — look for whether improvement actions from the previous cycle have been implemented at ward level."]'::jsonb where oe_code = 'PSQ.1.e';
update public.shco_full_oes set achieve_tips = '["Issue a formal appointment letter designating a specific individual as the Quality Coordinator, clearly outlining their responsibilities, authority, and reporting line.","Ensure the Quality Coordinator maintains a structured activity log covering audits conducted, trainings delivered, indicator data compiled, and committee meetings facilitated.","Train the Quality Coordinator to be the primary point of contact during assessor visits, able to retrieve documents, explain QI processes, and demonstrate programme continuity.","Create an SOP defining the Quality Coordinator''s monthly and quarterly responsibilities so the role remains functional even during staff transitions or absences."]'::jsonb where oe_code = 'PSQ.1.f';
update public.shco_full_oes set achieve_tips = '["Define a fixed review calendar for the quality improvement programme — for example, monthly data review and quarterly programme review — and publish it to all department heads.","Document what triggered each improvement cycle, what was changed as a result, and what the measurable outcome was, creating a clear cause-effect trail for assessors.","Use a structured review template that compares current performance against targets, highlights deviations, and records the corrective actions agreed for the next interval.","Train department leads to present department-level quality data at programme reviews so improvement identification is a shared, multi-departmental process rather than top-down only."]'::jsonb where oe_code = 'PSQ.1.g';
update public.shco_full_oes set achieve_tips = '["Develop an annual audit calendar covering clinical, nursing, and support service areas and share it with department heads so audits are planned, not ad hoc.","Use standardised audit tools with scoring rubrics and maintain completed audit forms in a centralised register accessible to the quality team and assessors.","Follow each audit with a documented action plan noting deficiencies found, corrective actions assigned, responsible person, and a target closure date.","Track audit compliance rates as a quality indicator — present the proportion of planned audits completed versus scheduled in your monthly quality report."]'::jsonb where oe_code = 'PSQ.1.h';
update public.shco_full_oes set achieve_tips = '["Establish nursing quality indicators — such as pressure injury rate, medication error rate, and patient falls — and collect data monthly from all inpatient areas.","Hold a monthly nursing quality meeting where ward sisters present their area''s indicator data, identify gaps, and agree on corrective actions, maintaining written minutes.","Train ward-level nursing staff to self-audit using simple observation checklists so that monitoring is continuous, not limited to formal audit visits.","During assessor interviews, nursing staff should be able to cite current values of key nursing indicators and describe one recent improvement action taken in their unit."]'::jsonb where oe_code = 'PSQ.1.i';
update public.shco_full_oes set achieve_tips = '["Define a core set of clinical key performance indicators — covering areas such as surgical site infection, readmission, and medication errors — approved by the quality committee.","Collect indicator data monthly from source departments and compile it in a structured dashboard that shows current value, target, trend, and responsible department.","Conduct a quarterly clinical data review meeting where each indicator is assessed against its benchmark and opportunities for improvement are formally documented.","Train department heads to present their clinical indicator data during assessor interviews and explain what actions were taken when a target was not met."]'::jsonb where oe_code = 'PSQ.2.a';
update public.shco_full_oes set achieve_tips = '["Define and actively track infection control indicators such as healthcare-associated infection rate, hand hygiene compliance, and antibiotic consumption, reporting monthly to the quality committee.","Ensure the Infection Control Officer maintains a structured monthly report with indicator values, trends, and actions taken — available for assessor review at any time.","Conduct regular observation audits of hand hygiene, aseptic technique, and biomedical waste segregation and document findings as part of the infection control indicator system.","During assessor walkthroughs, infection control staff should be able to show data dashboards and explain how a rising infection indicator triggered a specific corrective intervention."]'::jsonb where oe_code = 'PSQ.2.b';
update public.shco_full_oes set achieve_tips = '["Identify managerial indicators such as patient satisfaction scores, staff attendance rates, equipment downtime, and complaint resolution time, and report them monthly.","Maintain a structured managerial performance dashboard reviewed by senior leadership at monthly management meetings, with decisions and action points recorded in minutes.","Link managerial indicator targets to departmental performance reviews so department heads are accountable for data accuracy and improvement actions.","Create an SOP for data collection and reporting timelines for each managerial indicator to ensure consistency and prevent gaps that assessors would flag during review."]'::jsonb where oe_code = 'PSQ.2.c';
update public.shco_full_oes set achieve_tips = '["Define patient safety indicators including incident rates, near-miss frequency, patient fall rates, and medication error rates, and monitor them with monthly data collection.","Display patient safety indicator trends on a quality board visible to staff, showing whether the facility is improving, stable, or requires urgent action on each metric.","Ensure the incident management team links safety indicator data to specific events — assessors will look for evidence that data drives action, not just reporting.","During assessor interviews, safety committee members should be able to quote current indicator values and describe at least one recent patient safety improvement driven by data."]'::jsonb where oe_code = 'PSQ.2.d';
update public.shco_full_oes set achieve_tips = '["Establish a monthly data verification protocol where the quality team cross-checks reported indicator values against source documents such as registers, discharge summaries, and audit forms.","Maintain a data verification log noting who verified each dataset, when, any discrepancies found, and how they were corrected, making the process transparent to assessors.","Train data collectors in each department on accurate documentation and standardised data entry so that verification consistently finds minimal errors.","Use verified data to populate a monthly quality analysis report that identifies at least two improvement opportunities each cycle, with documented follow-up plans."]'::jsonb where oe_code = 'PSQ.2.e';
update public.shco_full_oes set achieve_tips = '["Maintain a clinical audit register listing all audits conducted, the parameters assessed, audit scores, findings, and the improvement actions implemented, updated after every audit cycle.","Develop standardised clinical audit tools for key processes such as consent documentation, surgical checklist compliance, and medication prescribing, using them consistently across departments.","Ensure clinical audit findings are formally presented to the quality committee with documented action-taken records so that improvement is traceable from audit to outcome.","Train staff who will be interviewed by assessors to describe a recent clinical audit they participated in, including what was found and what changed as a result."]'::jsonb where oe_code = 'PSQ.3.a';
update public.shco_full_oes set achieve_tips = '["Document a formal list of audit parameters approved by the quality committee, covering clinical care, documentation quality, infection control, and support services.","Review and update audit parameters annually based on incident trends, quality indicator performance, and accreditation feedback to ensure they remain relevant and comprehensive.","Make the audit parameter list part of the department''s annual quality plan so every team knows in advance what will be audited and to what standard.","Ensure audit parameters are linked to measurable criteria — for example, ''100% of surgical patients have signed consent forms'' — so audit results are objective and assessor-verifiable."]'::jsonb where oe_code = 'PSQ.3.b';
update public.shco_full_oes set achieve_tips = '["Maintain attendance records from clinical audit meetings showing that both medical and nursing staff are consistently present and actively contributing to discussions.","Assign at least one doctor and one senior nurse as mandatory members of the clinical audit team for each audit cycle, with their names documented in the audit report.","Train medical and nursing staff in basic audit methodology — including data collection, gap analysis, and action planning — so participation is meaningful and skill-based.","During assessor interviews, both a doctor and a nurse from a clinical department should be able to describe their direct involvement in a recent audit and its outcome."]'::jsonb where oe_code = 'PSQ.3.c';
update public.shco_full_oes set achieve_tips = '["For every clinical audit finding, create a corrective action plan with specific steps, a named responsible person, a target completion date, and a re-audit date to confirm closure.","Maintain a remedial action tracker reviewed monthly at quality committee meetings, noting which actions are open, overdue, or closed with evidence of implementation.","Conduct follow-up audits within 90 days of the original audit to verify that remedial measures have been implemented and have resulted in measurable improvement.","Train department heads to present the status of corrective actions during management meetings so accountability for implementation is embedded at a leadership level."]'::jsonb where oe_code = 'PSQ.3.d';
update public.shco_full_oes set achieve_tips = '["Maintain an active list of quality improvement projects with each project''s objective, methodology, team members, current phase, and measurable outcome target.","Use a structured improvement framework — such as PDCA or DMAIC — for each project and document each phase so assessors can follow the logic from problem identification to result.","Select QI project topics based on incident data, indicator trends, or audit findings so projects address real operational gaps rather than theoretical priorities.","Present QI project outcomes — with before-and-after data — at the quality committee meeting and retain these presentations as evidence of continuous improvement activity."]'::jsonb where oe_code = 'PSQ.3.e';
update public.shco_full_oes set achieve_tips = '["Measure safety culture annually using a validated staff survey and publish results to all staff, along with the management''s action plan in response to the findings.","Track sentinel events and near-misses as safety culture indicators — a rising near-miss reporting rate signals an improving culture of openness, and this data should be presented to assessors.","Ensure leadership visibly participates in patient safety activities such as safety walkrounds, hand hygiene campaigns, and incident debrief sessions, with photographic or documented evidence.","Establish a non-punitive incident reporting policy in writing, communicate it at orientation and refresher training, and record the number of staff trained to demonstrate culture commitment."]'::jsonb where oe_code = 'PSQ.4.a';
update public.shco_full_oes set achieve_tips = '["Conduct an annual orientation for all department heads and supervisors covering the objectives, scope, and implementation approach of the patient safety and quality improvement programme.","Maintain attendance records and brief assessment results from leadership awareness sessions so assessors can verify that knowledge is not limited to the quality team alone.","Include patient safety and quality programme updates as a standing agenda item in monthly leadership meetings, ensuring leaders receive current information and can speak to it during assessor interviews.","Create a one-page programme summary for leaders outlining key indicators, ongoing projects, and improvement priorities, updated quarterly and distributed before assessor visits."]'::jsonb where oe_code = 'PSQ.4.b';
update public.shco_full_oes set achieve_tips = '["Include a specific budget line for patient safety and quality improvement in the annual financial plan, covering training, audit tools, software, and improvement project costs.","Maintain records of expenditure against the quality budget — purchase orders, invoices, and training costs — to demonstrate that funds earmarked for quality are actually utilised.","Create an SOP for requesting quality-related resources that ensures requests are processed promptly and linked to an identified patient safety or quality improvement need.","During assessor interviews, the quality coordinator should be able to cite at least two resources — staffing, equipment, or training — specifically provided by management to support quality activities."]'::jsonb where oe_code = 'PSQ.4.c';
update public.shco_full_oes set achieve_tips = '["Deploy an annual staff satisfaction and safety culture survey, analyse results by department, and share a summary report with management along with a formal improvement response plan.","Establish a structured mechanism — such as a suggestion box, digital feedback form, or monthly safety debrief — for frontline staff to raise safety concerns directly to management.","Document each piece of staff feedback received, the management''s response, and any programme change made as a result, creating an auditable feedback loop for assessors.","Track the number and nature of staff-generated safety suggestions year-on-year to demonstrate that the feedback mechanism is active, used, and linked to measurable programme changes."]'::jsonb where oe_code = 'PSQ.4.d';
update public.shco_full_oes set achieve_tips = '["Implement a standardised incident reporting form and a clear reporting pathway so every staff member knows exactly how to report an incident — from verbal notification to written documentation.","Maintain an incident register that captures incident type, date, location, severity, staff involved, and actions taken, and make it available for assessor review at any time.","Train all clinical and support staff at induction and annually on the incident reporting system, maintaining signed attendance records as evidence of training coverage.","During assessor walkthroughs, staff should demonstrate familiarity with the incident form and be able to describe the steps they would follow if they witnessed or were involved in an incident."]'::jsonb where oe_code = 'PSQ.5.a';
update public.shco_full_oes set achieve_tips = '["Define a written list of events that meet the facility''s sentinel event criteria — such as wrong-site surgery, patient suicide, or maternal death — and distribute it to all clinical leads.","Create a sentinel event reporting SOP with clear escalation steps, timelines for notification to management and regulatory bodies, and documentation requirements.","Train charge nurses and department heads to recognise sentinel event criteria and initiate the reporting pathway immediately, without waiting for management instruction.","Maintain a sentinel event register — even if entries are rare — and document each event''s root cause analysis and corrective action to demonstrate an active identification and response system."]'::jsonb where oe_code = 'PSQ.5.b';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP for incident analysis that specifies when root cause analysis is required, who conducts it, the timeline for completion, and how findings are documented and shared.","For every significant incident, complete a structured root cause analysis using a validated tool such as the fishbone diagram or five-whys method, and retain the completed analysis form.","Conduct monthly trend analysis of incident data by category — medication, falls, infection, documentation — and present findings with visual trend charts at the quality committee meeting.","Train the quality team and clinical leads in incident analysis methodology so that investigations are systematic, consistent, and produce actionable findings rather than superficial conclusions."]'::jsonb where oe_code = 'PSQ.5.c';
update public.shco_full_oes set achieve_tips = '["For every incident analysis, generate a formal corrective and preventive action plan with specific tasks, responsible owners, implementation deadlines, and verification methods.","Track CAPA completion status in a register and review it monthly at quality meetings — overdue actions should be escalated to senior management for resolution.","After implementing a corrective action, conduct a follow-up audit or observation within 60 days to verify the action has been embedded in practice and has reduced the risk of recurrence.","Document preventive actions separately from corrective actions — show assessors that the facility learns from individual incidents to prevent similar events in other departments."]'::jsonb where oe_code = 'PSQ.5.d';
update public.shco_full_oes set achieve_tips = '["Develop a stakeholder communication SOP that specifies who must be notified — patient, family, medical staff, management, and regulators — within defined timeframes for near misses, adverse events, and sentinel events.","Maintain a communication log for each significant event recording who was informed, when, by whom, and what information was shared, ensuring full traceability for assessors.","Train clinical and administrative staff on patient and family communication protocols following adverse events, including empathetic disclosure language and documentation of what was discussed.","Conduct periodic drills or tabletop exercises simulating an adverse event scenario to verify that the notification pathway works in practice and all staff know their communication responsibilities."]'::jsonb where oe_code = 'PSQ.5.e';

-- ROM (19 OEs)
update public.shco_full_oes set achieve_tips = '["Prepare a formal governance document listing each board member or trustee by name, designation, and defined role — keep it signed, dated, and filed in the governance records binder accessible during assessor visits.","Display an organogram at the entrance and in key administrative areas showing the governance hierarchy; ensure staff can point assessors to the latest version during walkthroughs.","Conduct a half-yearly review of the roles and responsibilities document, minute the review in governing body meeting notes, and record any changes with the rationale.","Train department heads on who constitutes the governing body and what their mandated responsibilities are, so they can answer assessor interview questions confidently and accurately."]'::jsonb where oe_code = 'ROM.1.a';
update public.shco_full_oes set achieve_tips = '["Draft a one-page vision, mission, and values statement approved and signed by the governing body; display it prominently in the reception, wards, and staff areas so it is visible to patients, visitors, and assessors alike.","Publish the vision and mission on the hospital''s website, notice boards, and patient information leaflets so the organisation can demonstrate public accessibility during assessment.","Include the vision and mission statement in the employee induction kit and verify comprehension during probation reviews — keep a signed acknowledgement form on each staff file.","Minute the governing body meeting at which the vision, mission, and values were formally adopted; retain the signed minutes as the primary governance record for assessors."]'::jsonb where oe_code = 'ROM.1.b';
update public.shco_full_oes set achieve_tips = '["Establish a quarterly governing body scorecard that tracks at least five key performance indicators directly linked to the stated mission — present this at every board meeting and retain signed minutes.","Set annual performance targets at the start of each financial year in a board-approved document, then compare actuals against targets at mid-year and year-end reviews.","Prepare a one-page strategic performance dashboard for each governing body meeting showing trend data, so assessors can see evidence of ongoing measurement rather than a one-time exercise.","Ensure the CEO or administrator presents a written mission-alignment report to the governing body at least twice a year; file these reports in a dedicated governance folder for audit-ready access."]'::jsonb where oe_code = 'ROM.1.c';
update public.shco_full_oes set achieve_tips = '["Document every senior leadership appointment through a formal governing body resolution — maintain a chronological file of appointment letters, resolutions, and job descriptions for each key post.","Define ''senior leader'' positions in the governance charter (e.g., Medical Superintendent, Head of Nursing, Quality Manager) and ensure each role has a board-approved job description on record.","Record all senior leadership appointments in governing body meeting minutes with the date, selection criteria met, and appointing authority noted — this is primary evidence for assessors.","Conduct an annual review of senior leadership positions in a governing body meeting to confirm the appointments remain appropriate and are reflected in current organisational charts."]'::jsonb where oe_code = 'ROM.1.d';
update public.shco_full_oes set achieve_tips = '["Adopt a written ethics policy approved by the governing body covering conflict of interest, patient rights, and staff conduct — display the policy and keep signed staff acknowledgement records.","Establish an Ethics Committee with documented terms of reference, member list, and meeting schedule; ensure minutes are recorded and at least two meetings per year are conducted and filed.","Train all staff on the ethical framework during induction and annually thereafter; maintain attendance sheets and post-training acknowledgement forms that assessors can examine.","When assessors observe ward rounds or interview staff, ensure nursing and clinical staff can cite the ethics policy and describe how ethical dilemmas are escalated — conduct mock Q&A sessions as preparation."]'::jsonb where oe_code = 'ROM.1.e';
update public.shco_full_oes set achieve_tips = '["Prepare a credentials file for the person heading the organisation containing degree certificates, diplomas in hospital administration or management, and any relevant professional registrations — keep it readily retrievable.","Develop a job description for the head of the organisation that explicitly lists the required administrative qualifications; ensure the incumbent''s credentials match these requirements and document the verification.","Create an SOP for leadership appointment that outlines minimum qualification criteria for the head of the organisation, approved by the governing body, so the process is transparent and auditable.","Review and update the qualifications file annually; if the incumbent completes any new training or certification, add the credential to the file and note it in the next governing body meeting."]'::jsonb where oe_code = 'ROM.2.a';
update public.shco_full_oes set achieve_tips = '["Maintain an updated curriculum vitae for the head of the organisation in the HR file, clearly listing years of relevant administrative experience, roles held, and scope of responsibilities.","Define the minimum experience requirement for the leadership post in the appointment SOP — specify years of healthcare or hospital administration experience and document how the current incumbent satisfies this.","Attach a self-declaration or experience verification letter from previous employers to the head''s credential file so assessors can confirm the experience claim independently.","Conduct an annual HR file audit to ensure the experience records for the head of the organisation are current, complete, and free of gaps that might raise questions during assessment."]'::jsonb where oe_code = 'ROM.2.b';
update public.shco_full_oes set achieve_tips = '["Maintain a live legal compliance register listing every applicable act, rule, and notification (e.g., Clinical Establishments Act, PCPNDT, Bio-Medical Waste rules) with renewal dates and current compliance status — review it monthly.","Designate a compliance officer or assign the task to a senior administrator; document this assignment in writing and ensure the person conducts quarterly internal compliance audits with written reports.","Keep copies of all valid licences, registrations, and NOCs in a single compliance folder, sorted by renewal date, so any licence can be produced within minutes during an assessor visit.","When assessors interview the leader, demonstrate knowledge of key legal obligations by rehearsing responses to questions about statutory compliance — conduct a pre-assessment mock interview as part of preparation."]'::jsonb where oe_code = 'ROM.2.c';
update public.shco_full_oes set achieve_tips = '["Develop a formal performance appraisal tool for the head of the organisation with measurable criteria (e.g., budget adherence, patient satisfaction scores, staff turnover) — conduct the review annually at governing body level.","Document the performance review outcome in governing body meeting minutes, including targets set, achievements, gaps identified, and any agreed corrective actions.","Set SMART (specific, measurable, achievable, relevant, time-bound) performance goals for the leader at the beginning of each year in a board-signed document and track progress at mid-year.","Maintain a file of all completed leader performance appraisals so assessors can see a trend of reviews over time, demonstrating that governance over leadership effectiveness is sustained."]'::jsonb where oe_code = 'ROM.2.d';
update public.shco_full_oes set achieve_tips = '["Present a fully costed annual budget and a one-year operational plan to the governing body before each financial year begins; record the approval as a formal resolution in the meeting minutes.","Develop a three-to-five year strategic plan document, have it ratified by the governing body, and distribute it to all department heads so operational decisions are aligned to strategic priorities.","Ensure both the strategic plan and the annual budget are signed by the chairperson of the governing body and the head of the organisation — these signed documents serve as primary evidence for assessors.","Track budget utilisation quarterly and present variance reports to the governing body; retain these reports as evidence that approved plans are actively monitored, not just created for documentation."]'::jsonb where oe_code = 'ROM.3.a';
update public.shco_full_oes set achieve_tips = '["Set up formal departmental coordination meetings (weekly or fortnightly) with structured agendas and recorded minutes; ensure action items are tracked to closure and the register is available for assessors.","Establish a documented liaison protocol with key external agencies (referral hospitals, blood banks, ambulance services) and maintain correspondence or MOU files as evidence of active coordination.","Use a goals and objectives tracker — a simple spreadsheet or dashboard updated monthly — to show measurable progress against the hospital''s defined targets; present this at management review meetings.","Assign ownership of each organisational goal to a named department head, document accountability in the strategic plan, and review progress in monthly management meetings with recorded minutes."]'::jsonb where oe_code = 'ROM.3.b';
update public.shco_full_oes set achieve_tips = '["Prepare a master list of all hospital committees (e.g., Infection Control, Pharmacy and Therapeutics, Quality, Safety) with defined terms of reference, meeting frequency, and member names — keep it updated.","Conduct annual effectiveness reviews of each committee using a structured evaluation form covering meeting regularity, attendance quorum, action closure rate, and impact on outcomes — record findings in writing.","Track committee meeting compliance monthly: if a committee misses its scheduled meeting, document the reason and the rescheduled date — this shows assessors that oversight of committee functioning is active.","Present a consolidated committee effectiveness report to the governing body or management once a year, including recommendations for restructuring underperforming committees; minute the discussion."]'::jsonb where oe_code = 'ROM.3.c';
update public.shco_full_oes set achieve_tips = '["Define at least five measurable service standards (e.g., OPD waiting time, bed turnaround time, discharge processing time) in a formal document approved by management and distributed to relevant departments.","Collect data against each service standard monthly using standardised data collection sheets; compile results into a monthly performance report that is reviewed in management meetings.","When assessors visit departments, ensure supervisors can produce both the documented standard and the most recent performance data for that area — conduct internal mock assessments to test this readiness.","Set threshold values for each service standard and establish a documented escalation process when a threshold is breached; demonstrate this process with at least one recent example during the assessment."]'::jsonb where oe_code = 'ROM.3.d';
update public.shco_full_oes set achieve_tips = '["Draft a Staff Rights and Responsibilities Policy covering safe working conditions, fair treatment, grievance redressal, confidentiality obligations, and duty of care — get it approved by management and signed by a governance representative.","Include the staff rights and responsibilities document in every employee induction programme; collect signed acknowledgement forms and file them in individual staff records so assessors can verify awareness.","Display a summary of staff rights and responsibilities in staff rest rooms, nursing stations, and the HR notice board so they are visible during assessor walkthroughs of staff areas.","Review the staff rights and responsibilities document annually to incorporate any changes in labour law or organisational policy; document the review date, changes made, and re-issue the updated version to all staff."]'::jsonb where oe_code = 'ROM.3.e';
update public.shco_full_oes set achieve_tips = '["Implement a hospital-wide risk register covering clinical, operational, infrastructure, and safety risks — each entry should include risk description, likelihood, impact rating, owner, and mitigation action with a due date.","Conduct proactive risk assessments in every department at least once a year using a standardised risk assessment form; file completed assessments by department and date for assessor review.","Establish a Patient Safety Committee that meets at least quarterly to review the risk register, track mitigation progress, and escalate unresolved high-priority risks to management — keep signed minutes on file.","Train ward staff and department heads on how to identify and report potential risks using incident report forms; assessors will ask frontline staff how risks are identified in their daily work, so practical drill-based training is essential."]'::jsonb where oe_code = 'ROM.4.a';
update public.shco_full_oes set achieve_tips = '["Create a single integrated planning calendar that links quality improvement projects, risk mitigation timelines, and strategic plan milestones — share it across departments so teams see how their work connects.","Present a joint quality-risk-strategy update at every management review meeting, using a common reporting template that shows interconnections between quality indicators, open risks, and strategic objectives.","Document at least two examples per year where a risk identified through the risk management process led to a change in a quality improvement target or a revision of a strategic plan item — these case studies are powerful evidence for assessors.","Establish a cross-functional team (including quality, risk, clinical, and administration representatives) that meets bi-monthly to review integration points; record attendance and decisions in formal minutes."]'::jsonb where oe_code = 'ROM.4.b';
update public.shco_full_oes set achieve_tips = '["Design and implement an internal incident reporting system with a standardised incident report form; ensure every department has printed forms available and staff know the submission process — verify this during ward rounds.","Establish an external reporting protocol for notifiable events (e.g., sentinel events, adverse drug reactions, bio-medical waste violations) with a named responsible officer, defined timelines, and a reporting log.","Conduct monthly reviews of all submitted incident reports in the Patient Safety or Quality Committee; track trends, root causes, and corrective actions — file the reviewed reports with meeting minutes.","During pre-assessment preparation, have the Quality Manager walk assessors through at least three recent incidents showing the full cycle: report received, root cause analysed, corrective action taken, and closure documented."]'::jsonb where oe_code = 'ROM.4.c';
update public.shco_full_oes set achieve_tips = '["Prepare a written agreement (SLA or MOU) for every outsourced service (housekeeping, laundry, security, laboratory, catering) that specifies service parameters, quality standards, response times, and escalation contacts.","Maintain a central file of all outsourced service agreements sorted by vendor, with clear renewal and review dates highlighted — ensure this file is current and accessible on the day of assessment.","Before signing any outsourced service agreement, use a standard checklist to verify that all required service parameters are included; file the signed checklist alongside the agreement as evidence of due diligence.","Conduct an annual review of each outsourced service agreement to confirm that service parameters remain appropriate; document the review with a signed review note and update the agreement if any parameters need revision."]'::jsonb where oe_code = 'ROM.4.d';
update public.shco_full_oes set achieve_tips = '["Set up a monthly outsourced service performance review meeting where each vendor''s performance against contractual service parameters is assessed using quantitative data — document findings in a vendor performance log.","Use a structured vendor scorecard with measurable KPIs (e.g., complaint rate, response time, non-conformance count) to score each outsourced service provider quarterly; share scores with vendors and file reports.","When performance gaps are identified, issue a formal corrective action notice to the vendor, set a response deadline, and track closure — maintain a corrective action register for all outsourced services.","Demonstrate to assessors at least one documented improvement achieved in an outsourced service over the past year: show the original performance data, the action taken, and the improved outcome data in a before-and-after format."]'::jsonb where oe_code = 'ROM.4.e';

-- FMS (29 OEs)
update public.shco_full_oes set achieve_tips = '["Conduct a physical walkthrough of all departments to verify that available space matches the services being delivered, and document any gaps for management review.","Develop a space utilisation checklist covering OPD, IPD, procedure rooms, and support areas, and update it whenever new services are added or reorganised.","Prepare a written SOP that defines minimum space requirements for each service category, and train the facility manager to apply it during any expansion planning.","Maintain a file of approved layout plans alongside current usage maps so assessors can instantly verify that facilities remain appropriate to declared services."]'::jsonb where oe_code = 'FMS.1.a';
update public.shco_full_oes set achieve_tips = '["Retrieve the original architectural drawings from the builder or architect and store verified copies in a dedicated statutory-compliance folder accessible to facility management.","Appoint a responsible staff member to update drawings within 30 days of any structural change, renovation, or addition of utility lines, and record the date of each revision.","Create an SOP for maintaining as-built drawings that outlines who initiates updates, who approves them, and where the master copies are stored.","Keep a log of all drawing revisions with dates and the nature of the change so assessors can confirm that records are current and traceable."]'::jsonb where oe_code = 'FMS.1.b';
update public.shco_full_oes set achieve_tips = '["Walk every entry point, corridor, and ward and place clear directional signs at each decision point; use pictograms alongside text to serve patients who cannot read.","Conduct a monthly signage audit using a checklist that covers both internal department signs and external facility identification boards, and record findings in a register.","Ensure all signs are in at least the local language and English, and that sign heights and font sizes meet accessibility standards for visually impaired visitors.","Train housekeeping and security staff to immediately report any damaged, faded, or missing signs so replacements are made within 48 hours; keep replacement records as evidence for assessors."]'::jsonb where oe_code = 'FMS.1.c';
update public.shco_full_oes set achieve_tips = '["Install a 24-hour flow meter or pressure gauge log for the main water supply and designate a staff member to record readings at the start of each shift.","Keep an electricity supply log that captures any interruptions, their duration, and the immediate corrective action taken, and review it weekly with the facility manager.","Test all water taps, RO systems, and overhead tank levels daily, and document results in a utility checklist signed by the duty engineer.","Train ward nurses and housekeeping staff to report water or power failures immediately through a defined escalation channel, and ensure assessors can observe the functioning supply and review the daily logs."]'::jsonb where oe_code = 'FMS.1.d';
update public.shco_full_oes set achieve_tips = '["Install a diesel generator with automatic changeover and a water storage tank of sufficient capacity, and document their specifications in the facility infrastructure register.","Write a formal SOP specifying the testing schedule for backup electricity (at least monthly load test) and backup water (quarterly tank flush and fill test), and record every test in a dated log.","Assign a named technician responsible for each backup system, train them on startup and shutdown procedures, and maintain training records as evidence.","Display the backup system testing schedule on the engineering notice board and keep test result records for at least two years so assessors can verify consistent functioning."]'::jsonb where oe_code = 'FMS.1.e';
update public.shco_full_oes set achieve_tips = '["Audit current energy consumption by reviewing electricity bills for the past 12 months and identify the top three areas of high usage for targeted improvement.","Install energy-saving LED lighting in at least one high-traffic area and document the initiative with before-and-after consumption data to demonstrate measurable impact.","Start a simple waste-segregation initiative — paper, plastic, and general waste bins with clear labels — and brief all staff during morning meetings to build participation.","Create a green initiatives register where each new energy or environment-friendly measure is recorded with the date started, responsible person, and outcome observed."]'::jsonb where oe_code = 'FMS.1.f';
update public.shco_full_oes set achieve_tips = '["Prepare a comprehensive inventory of all patient-safety devices — bed rails, call bells, anti-slip mats, grab rails, restraints — and map their locations across every ward and procedure area.","Establish a monthly inspection checklist for each safety device, sign off each check with the inspector''s name and date, and retain the completed checklists in a safety register for assessor review.","Set up a reported-defect log so any staff member who finds a faulty safety device can record it; require the facility team to resolve and close each entry within 24 hours with documented corrective action.","Conduct periodic unannounced spot-checks of patient areas so assessors can observe safety devices in place; brief staff during ward rounds to explain the purpose and correct use of each device."]'::jsonb where oe_code = 'FMS.2.a';
update public.shco_full_oes set achieve_tips = '["Map every patient-access route in the facility and identify locations where ramps, handrails, wider doorways, or accessible toilets are required, then prioritise installation based on patient footfall.","Write an SOP for receiving and assisting differently-abled patients that covers wheelchair allocation, escort procedures, and accessible parking, and train front-desk and security staff to follow it consistently.","Display the international symbol of access at all adapted entrances, parking bays, and accessible washrooms, and verify signage is visible and unobstructed during monthly facility rounds.","Maintain a register of all differently-abled facilities — ramps, tactile floors, hearing loops, Braille signage — with their installation dates and last inspection dates so records are audit-ready."]'::jsonb where oe_code = 'FMS.2.b';
update public.shco_full_oes set achieve_tips = '["Prepare a written security plan that identifies high-risk zones — ICU, labour room, pharmacy, cash counter, server room — and defines who is authorised to enter each zone with what form of identification.","Install access-control measures such as key-coded doors, visitor passes, or security guard posts at each restricted area, and maintain a daily access log for each high-security zone.","Create a measurable outcome register that tracks the number of unauthorised access incidents per month, reviews trends quarterly, and records corrective actions taken to reduce recurrence.","Conduct quarterly security briefings with all staff covering their responsibilities for controlling access, and keep attendance records and briefing notes so assessors can verify staff awareness."]'::jsonb where oe_code = 'FMS.2.c';
update public.shco_full_oes set achieve_tips = '["Schedule a formal facility safety inspection round on the first Monday of every month and document the route, findings, and actions in a signed inspection register.","Use a standardised inspection checklist covering flooring conditions, lighting adequacy, sharps disposal bins, fire extinguisher positions, and emergency exit clearance to ensure nothing is missed each round.","Assign a cross-functional team — nursing, housekeeping, engineering — to participate in each monthly round so safety issues are identified from multiple perspectives and recorded collectively.","Ensure that deficiencies noted during rounds have corrective action entries with a deadline and responsible person; close each entry with a dated sign-off so assessors can trace compliance to the inspection findings."]'::jsonb where oe_code = 'FMS.2.d';
update public.shco_full_oes set achieve_tips = '["Engage a licensed electrical engineer or authorised agency to conduct a formal electrical safety audit at least once a year and retain the written audit report with findings and recommendations.","Maintain a corrective action tracker that lists each electrical deficiency identified during the audit alongside the target closure date, responsible engineer, and actual date of resolution.","Track measurable outcomes such as number of electrical faults reported per quarter and reduction in tripping events, and review the trend with management to demonstrate improvement over time.","Keep all electrical test certificates — earthing tests, insulation resistance tests, load tests — in a dedicated file with dates so assessors can verify that audits are current and deficiencies resolved."]'::jsonb where oe_code = 'FMS.2.e';
update public.shco_full_oes set achieve_tips = '["Develop an SOP for identifying items no longer in use — expired consumables, broken furniture, obsolete equipment — and specify how each category should be labelled, stored temporarily, and disposed of.","Create a disposal request form that any department can raise when surplus or condemned material is identified; route it through the purchase or biomedical team for authorisation before removal.","Train housekeeping supervisors and department in-charges on the identification procedure during a dedicated session, and maintain a training attendance register as evidence.","Keep a disposal log recording the item description, quantity, date removed, disposal method, and approving authority so the complete audit trail is available for assessors."]'::jsonb where oe_code = 'FMS.2.f';
update public.shco_full_oes set achieve_tips = '["Prepare a labelled hazardous materials inventory covering disinfectants, flammable cleaning agents, cytotoxic drugs, laboratory chemicals, and medical gases, and post it in each area where these materials are stored or used.","Write handling and storage SOPs for each category of hazardous material specifying personal protective equipment required, storage conditions, spill response steps, and disposal method; make these accessible at the point of use.","Train relevant staff — housekeeping, laboratory, pharmacy, nursing — on hazardous material handling during induction and annually thereafter, and maintain signed training records for assessor review.","Conduct periodic observations of staff handling hazardous materials and record findings; assessors will observe actual practice, so ensure staff can demonstrate correct PPE use and spill-kit location during any unannounced check."]'::jsonb where oe_code = 'FMS.2.g';
update public.shco_full_oes set achieve_tips = '["Develop a written equipment procurement policy aligned with the clinical services offered, specifying criteria for selection such as safety features, serviceability, and vendor support before any purchase is approved.","Prepare a five-year equipment plan linked to the strategic growth plan, reviewed annually by management, and keep signed review minutes as evidence of systematic planning.","Write an SOP for the equipment acquisition process covering needs assessment, technical specification preparation, vendor evaluation, and final approval authority, and train the biomedical team to follow it consistently.","Maintain a procurement file for each major equipment purchase containing the justification, specification, vendor comparison, and approval sign-off so the full planning trail is audit-ready."]'::jsonb where oe_code = 'FMS.3.a';
update public.shco_full_oes set achieve_tips = '["Create a master equipment inventory register covering all medical and support service equipment with each item''s unique asset code, department location, purchase date, make, model, and current status.","Establish equipment-specific logbooks — either physical or digital — for each asset where every use, cleaning, breakdown, and service event is entered with date and staff name.","Write an SOP defining who is responsible for updating the inventory when new equipment arrives, when items are condemned, or when assets are relocated between departments.","Conduct a quarterly inventory verification where the physical count is matched against the register; document discrepancies and resolution steps so assessors can confirm that logs are accurate and current."]'::jsonb where oe_code = 'FMS.3.b';
update public.shco_full_oes set achieve_tips = '["Develop a written preventive maintenance (PM) schedule for every piece of medical and support service equipment, specifying the frequency, tasks to be performed, and responsible technician.","Implement a breakdown maintenance log where any equipment failure is recorded immediately with the date, nature of fault, downtime start time, and service team notified, and closed with the repair date and action taken.","Train biomedical technicians and department operators on daily pre-use checks for their equipment, and ensure signed daily check sheets are retained in the equipment logbook for assessor review.","Monitor PM compliance monthly — track how many scheduled PMs were completed on time versus deferred — and review the rate with management so the plan is demonstrably implemented."]'::jsonb where oe_code = 'FMS.3.c';
update public.shco_full_oes set achieve_tips = '["Prepare a calibration schedule listing every medical device requiring periodic calibration, the calibration frequency, the responsible agency, and the due date for the next calibration.","After each calibration or inspection, affix a sticker on the equipment showing the calibration date and next due date, and file the calibration certificate in the equipment folder.","Write an SOP for managing equipment found to be out of calibration — immediate removal from service, tagging, investigation, recalibration, and reintroduction — and train the biomedical team to follow it.","Maintain a calibration compliance tracker showing percentage of devices calibrated on schedule each quarter; review with management and keep records so assessors can verify systematic inspection."]'::jsonb where oe_code = 'FMS.3.d';
update public.shco_full_oes set achieve_tips = '["Prepare job descriptions for all biomedical and engineering staff that specify required qualifications and training for operating and maintaining equipment assigned to their role.","Maintain individual training records for each technician and operator documenting equipment-specific competency training, on-the-job assessments, and refresher sessions with dates.","Write an SOP requiring that only trained and authorised personnel operate designated equipment, and implement a visible authorisation system — signed competency card or logbook entry — for each equipment-operator combination.","Schedule annual refresher training for all equipment operators, especially when new models are procured or after any near-miss event, and keep signed attendance sheets so assessors can confirm ongoing competence."]'::jsonb where oe_code = 'FMS.3.e';
update public.shco_full_oes set achieve_tips = '["Subscribe to the manufacturer''s and regulatory authority''s hazard alert and recall notification channels, and designate a responsible officer to review all incoming notices and initiate action within a defined timeframe.","Maintain an adverse event register specifically for medical equipment incidents — near-misses, patient injuries, device malfunctions — with investigation findings and corrective actions closed out with dates.","When a recall notice is received, immediately check the inventory register to determine if the affected device is in use, quarantine it if required, and document the action taken in the recall tracking log.","Review the adverse event and recall register monthly with the biomedical committee, track trends in equipment-related incidents, and retain review minutes so assessors can confirm that monitoring is active and systematic."]'::jsonb where oe_code = 'FMS.3.f';
update public.shco_full_oes set achieve_tips = '["Define critical equipment for your facility — ventilators, anaesthesia machines, ECG monitors, infusion pumps — and set acceptable maximum downtime targets for each category in a written policy.","Implement a downtime tracking log for every breakdown of critical equipment recording the exact time of failure report, time of technician response, time of repair completion, and total downtime in hours.","Review downtime data monthly to calculate average response and resolution times; compare against targets and implement corrective action — such as spare parts stocking or vendor SLA revision — when targets are missed.","Keep cumulative downtime reports for each critical equipment item accessible in the biomedical office so assessors can verify that monitoring is continuous and that corrective actions are data-driven."]'::jsonb where oe_code = 'FMS.3.g';
update public.shco_full_oes set achieve_tips = '["Draft a comprehensive medical gas SOP covering approved suppliers, purchase order procedures, receipt inspection, cylinder storage rules, distribution records, and reorder trigger levels; get it approved by management.","Develop a cylinder tracking log that records each cylinder''s unique number, gas type, date received, location assigned, date emptied, and date returned to supplier to maintain a complete audit trail.","Train all staff involved in handling medical gases — store, ward nurses, technicians — on the SOP during induction and annually thereafter, and keep signed training records readily available for assessors.","Conduct quarterly internal audits of medical gas storage areas against the SOP checklist, record findings and corrective actions, and file audit reports so compliance history is visible."]'::jsonb where oe_code = 'FMS.4.a';
update public.shco_full_oes set achieve_tips = '["Label every medical gas cylinder and pipeline outlet clearly with the gas name and colour code, and train staff never to use an unlabelled or unclear cylinder under any circumstances.","Ensure cylinders are stored upright, secured with chains or brackets, and segregated by gas type and status — full versus empty — with clear zone markings on the floor of the storage area.","Display the SOP for safe medical gas handling at every storage point and near every bedside terminal, and ensure staff can demonstrate correct connection and leak-check procedures during assessor observations.","Conduct monthly checks of all cylinder valves, connections, and pressure gauges; document results in a safety inspection register and take immediate corrective action for any leaks or pressure anomalies found."]'::jsonb where oe_code = 'FMS.4.b';
update public.shco_full_oes set achieve_tips = '["Identify the alternate or backup source for each medical gas, vacuum line, and compressed air system — spare cylinders, portable compressors, backup manifold — and document their specifications and locations.","Write a formal testing protocol specifying how often each backup system is tested, who conducts the test, what parameters are verified, and how results are recorded; schedule tests at least quarterly.","Train the engineering team to perform failover tests safely, including simulation of main supply failure and confirmation that the backup source activates within the required timeframe; keep signed test records.","Maintain a backup-system test log with each test date, tester name, result, and any corrective action taken so assessors can verify regular testing and readiness."]'::jsonb where oe_code = 'FMS.4.c';
update public.shco_full_oes set achieve_tips = '["Prepare a written operations and maintenance plan for the piped medical gas, compressed air, and vacuum installation covering daily checks, monthly inspections, annual service, and pressure testing schedules.","Implement a daily line-pressure monitoring log where the duty engineer records pipeline pressures for each gas at the manifold and at key terminal points, signing off each shift entry.","Engage a qualified piped medical gas engineer for annual inspection and testing, retain the technical report with findings, and track all identified deficiencies to closure with dated records.","Write an SOP for responding to pipeline pressure failures — isolation steps, backup activation, patient safety actions, and notification chain — and ensure all relevant staff are trained and can demonstrate the steps."]'::jsonb where oe_code = 'FMS.4.d';
update public.shco_full_oes set achieve_tips = '["Install fire detection devices — smoke detectors, heat sensors, manual call points — in all departments, corridors, and utility areas, and verify their positions meet the fire safety layout plan for the building.","Maintain a fire emergency response plan document that defines the R-A-C-E procedure (Rescue, Alarm, Contain, Extinguish or Evacuate) and post laminated quick-reference cards at each nursing station and exit.","Ensure first-aid firefighting equipment — extinguishers and hose reels — is placed at all designated points, inspected monthly, and tagged with the last inspection date so staff and assessors can see compliance at a glance.","Train all staff — including housekeeping and security — in fire response during induction and annually; assessors will observe and interview staff, so every team member should be able to explain their role in an emergency."]'::jsonb where oe_code = 'FMS.5.a';
update public.shco_full_oes set achieve_tips = '["Draw a clear floor plan for each floor showing all emergency exits, evacuation assembly points, fire extinguisher locations, and escape routes; laminate and display the plan at the entrance of every ward and corridor.","Write an SOP detailing the evacuation sequence for each zone, the staff responsible for leading patients, the assembly point for each ward, and the roll-call procedure to account for all occupants after evacuation.","Conduct a staff briefing when new employees join, using the displayed exit plan as a visual aid, and document attendance; ensure all staff can locate the nearest exit and assembly point from their usual work area.","Audit the visibility and accuracy of all posted exit plans monthly; replace damaged or outdated plans immediately and record the audit date and auditor name in the facility safety register."]'::jsonb where oe_code = 'FMS.5.b';
update public.shco_full_oes set achieve_tips = '["Schedule two mock drills per year — one announced and one unannounced — covering fire and at least one non-fire emergency scenario such as a medical gas leak or structural damage, and record dates in the annual safety calendar.","Prepare a mock drill report template that captures time of alarm, staff response time, evacuation completion time, headcount result, and debrief findings; complete a report for every drill conducted.","Conduct a structured debrief within 24 hours of each drill involving all participating staff to identify gaps in response and update the emergency plan accordingly, documenting changes made as a result.","Maintain a mock drill register with dates, scenarios used, participants, drill duration, debrief summary, and improvement actions so assessors can confirm that drills are conducted, evaluated, and acted upon."]'::jsonb where oe_code = 'FMS.5.c';
update public.shco_full_oes set achieve_tips = '["Prepare an inventory of all fire-related equipment — extinguishers, hose reels, sprinkler heads, smoke detectors, manual call points, fire doors — and map each item''s location in the facility.","Write a maintenance schedule specifying monthly visual checks, six-monthly servicing, and annual pressure testing for each equipment type, and assign responsibility to a named engineer or contracted vendor.","After every maintenance or service event, update the equipment tag with the service date and next due date, and file the service certificate in the fire safety maintenance folder.","Conduct an annual fire equipment compliance review comparing the inventory against the maintenance log to confirm all items are serviced on schedule; document the review outcome and any gaps addressed for assessor verification."]'::jsonb where oe_code = 'FMS.5.d';
update public.shco_full_oes set achieve_tips = '["Develop a written service continuity plan that identifies the minimum services the facility must maintain during and after an emergency — critical care, emergency surgery, essential medications — and assigns responsible staff for each.","Define escalation contacts, backup service providers, and mutual aid agreements with nearby hospitals in the continuity plan, and test contact lists every six months to confirm they are current.","Map critical utilities — electricity, water, oxygen, data systems — against the continuity plan and specify the backup arrangements and maximum acceptable downtime for each, recording the plan in a retrievable document.","Review and update the service continuity plan annually or after any actual emergency, document the review with management sign-off, and keep previous versions archived so assessors can trace the improvement history."]'::jsonb where oe_code = 'FMS.5.e';

-- HRM (45 OEs)
update public.shco_full_oes set achieve_tips = '["Conduct an annual workforce gap analysis comparing current staff numbers and skill mix against patient load projections, and document findings with a signed review date.","During assessor visits, be ready to walk through your HR planning register and explain how staffing ratios are determined for each shift and department.","Maintain a rolling 12-month workforce plan updated quarterly; assessors will interview department heads to verify that staffing decisions align with patient care needs.","Keep records of all manpower requisitions linked back to the workforce plan so staff can demonstrate the chain of decision-making from plan to hire."]'::jsonb where oe_code = 'HRM.1.a';
update public.shco_full_oes set achieve_tips = '["Draft and approve a Recruitment SOP that specifies every step from vacancy identification to offer letter issuance, including timelines and approval authorities.","Maintain a recruitment register with entries for each vacancy showing date advertised, candidates shortlisted, interview panel members, and final selection rationale.","Assessors will review recruitment files and may ask staff about how the process works — ensure HR staff can explain each step without referring to notes.","Display the recruitment policy in HR office and include it in the HR induction pack so all panel members follow the same documented process."]'::jsonb where oe_code = 'HRM.1.b';
update public.shco_full_oes set achieve_tips = '["Post a department-wise sanctioned versus actual staff strength chart in each nursing station and department, updated monthly and signed by the department head.","Assessors will observe shift handovers and may count on-duty staff against the posted roster — ensure real-time staffing matches approved norms at all times.","Maintain duty rosters for at least the past 6 months, showing staff names, designations, and shift timings so records substantiate observed staffing levels.","Conduct a monthly HR compliance review where shortfalls in any department are escalated to administration with a corrective action plan on record."]'::jsonb where oe_code = 'HRM.1.c';
update public.shco_full_oes set achieve_tips = '["Document a formal contingency staffing plan covering scenarios such as mass leave, epidemic absences, and sudden surge in patient admissions, with activation triggers clearly stated.","Maintain a pre-approved on-call staff list per department that can be activated within 2 hours, and test this list during mock drills at least twice a year.","Track and report monthly metrics on unplanned absenteeism rate and time-to-fill temporary gaps; present trend data at HR committee meetings to show the plan is working.","Record each instance of an unplanned staffing shortage, the contingency measure used, and resolution time so assessors can see measurable outcomes of the plan."]'::jsonb where oe_code = 'HRM.1.d';
update public.shco_full_oes set achieve_tips = '["Create a Job Description (JD) template that includes reporting relationships, key responsibilities, qualifications required, and KPIs for every staff category, reviewed annually.","Ensure each employee''s personnel file contains a signed copy of their current JD and org chart position so credential verification and role clarity are immediately demonstrable.","During induction, have new hires sign that they have received and understood their JD and reporting structure; file this acknowledgement in their personal record.","Assessors will interview staff at all levels to confirm they know their supervisor and job scope — hold quarterly team briefings reinforcing reporting lines."]'::jsonb where oe_code = 'HRM.1.e';
update public.shco_full_oes set achieve_tips = '["Implement a pre-employment background verification checklist covering identity, previous employment, criminal record, and credential authenticity, completed before the joining date.","Maintain a background check register logging each new hire, the verification agency or method used, date completed, and outcome — this record must be audit-ready at all times.","File verification certificates and police clearance letters (where applicable) in personnel files so assessors can cross-check during a document review without additional retrieval.","Establish a policy that no staff member handles patients until background verification is cleared, and document any interim arrangements with a risk approval signature."]'::jsonb where oe_code = 'HRM.1.f';
update public.shco_full_oes set achieve_tips = '["Draft a Code of Conduct document covering patient interaction, confidentiality, dress code, social media use, and professional behaviour, and have all staff sign it at induction.","Display summarised conduct norms in staff areas and patient care zones; assessors will observe whether staff behaviour is consistent with the documented code.","Conduct at least one annual refresher session on the Code of Conduct and record attendance; keep sign-in sheets in personnel files as evidence of compliance.","Assessors may ask staff to explain what the code of conduct requires — ensure all team leads can articulate the key provisions without prompting."]'::jsonb where oe_code = 'HRM.1.g';
update public.shco_full_oes set achieve_tips = '["Use a standardised exit interview form covering reasons for leaving, workplace concerns, and suggestions for improvement; have HR conduct the interview on the last working day.","Compile exit interview data quarterly into a trend report showing top reasons for attrition by department, and present this at the HR committee meeting with proposed actions.","Document corrective actions taken in response to exit feedback — e.g., policy changes or facility improvements — and track whether attrition rates improve over the next quarter.","Keep exit interview records confidential and numbered sequentially so assessors can verify that interviews are being conducted consistently across all departing staff."]'::jsonb where oe_code = 'HRM.1.h';
update public.shco_full_oes set achieve_tips = '["Develop a Disciplinary and Grievance Handling SOP that defines types of misconduct, escalation steps, timelines for resolution, and the appeal process — approved by management.","Maintain a grievance register with a unique case number for each complaint, recording date received, nature of grievance, actions taken, and closure date.","Ensure all staff are informed of the grievance mechanism at induction and that the process is posted on the staff notice board so assessors can confirm visibility.","File all disciplinary proceedings and their outcomes in a secure, confidential register; assessors may request to see anonymised records to verify the process is followed consistently."]'::jsonb where oe_code = 'HRM.1.i';
update public.shco_full_oes set achieve_tips = '["Design a structured induction checklist covering hospital policies, safety procedures, department tour, role-specific orientation, and NABH standards, completed within the first week of joining.","Obtain a signed induction completion form from every new hire and file it in their personnel record so assessors can verify induction was provided systematically.","Assessors will interview recently joined staff to confirm they received induction — ensure that all new employees can name key policies and safety procedures they were trained on.","Observe new staff during their initial weeks and document a supervisor''s feedback form on induction effectiveness, linking observations to the induction checklist topics."]'::jsonb where oe_code = 'HRM.2.a';
update public.shco_full_oes set achieve_tips = '["Write and approve a Training and Development Policy that covers mandatory training frequencies, nomination processes, budget provisions, and documentation requirements for all staff categories.","Maintain an annual training calendar shared with all departments, specifying topics, target groups, trainers, and scheduled dates so staff can plan attendance in advance.","Assessors will review the training policy document and may ask department heads how training needs are identified — ensure HODs can explain the Training Needs Assessment (TNA) process.","Verify that the policy is accessible to all staff digitally or in a printed form in each department; collect acknowledgement signatures that staff have read and understood it."]'::jsonb where oe_code = 'HRM.2.b';
update public.shco_full_oes set achieve_tips = '["Map each staff role''s JD to a training matrix that lists mandatory competencies and the corresponding training programmes; update this matrix whenever job descriptions change.","Before each training cycle, HR must cross-check completed training against the role-specific training matrix and ensure gaps are scheduled before the next assessment window.","File training completion certificates in each staff member''s personnel file so that credential verification during an assessment can confirm training aligns with the job description.","Conduct quarterly compliance reviews showing percentage of staff per department who have completed all role-specific training, with a corrective action plan for any below 90%."]'::jsonb where oe_code = 'HRM.2.c';
update public.shco_full_oes set achieve_tips = '["Schedule BLS/CPR training for all direct patient care staff during induction week and maintain a refresher schedule every 12 months, with dates and participant lists on record.","Keep original CPR certification cards or in-house training completion records in personnel files and a master CPR competency register updated after each session.","Assessors may observe a mock CPR scenario or interview staff — ensure all patient care staff can demonstrate correct chest compression technique and AED use without hesitation.","Track CPR certification expiry dates in a master register and send automated reminders 30 days before expiry so no staff member lapses into an uncertified status."]'::jsonb where oe_code = 'HRM.2.d';
update public.shco_full_oes set achieve_tips = '["Use a three-level training evaluation model: collect participant feedback immediately post-training, assess knowledge retention via a post-test, and observe on-the-job behaviour change after 30–60 days.","Maintain training effectiveness records showing pre- and post-assessment scores for each programme, and calculate a departmental training effectiveness rate to present at HR committee meetings.","If a training programme scores below an effectiveness threshold, document a revised training approach and re-evaluate within 60 days to demonstrate continuous improvement.","Assessors will look for evidence that training results in practice change — pair training records with quality indicator data (e.g., infection rates, incident reports) to show impact."]'::jsonb where oe_code = 'HRM.2.e';
update public.shco_full_oes set achieve_tips = '["Develop a Safety Training SOP that lists all mandatory safety topics, target staff groups, delivery frequency, and the responsible trainer for each topic area.","Conduct safety programme induction for every new hire within the first 3 days and document completion with a signed acknowledgement form filed in their personnel record.","Assessors will interview staff to check whether they can describe the hospital''s safety programme elements — hold monthly 10-minute safety stand-up reminders to reinforce knowledge.","Maintain a safety training compliance dashboard showing completion percentages by department, updated monthly so management can intervene when any area falls behind."]'::jsonb where oe_code = 'HRM.3.a';
update public.shco_full_oes set achieve_tips = '["Conduct a formal risk identification exercise for each department and build a risk-specific training module for the hazards identified (e.g., chemical exposure in labs, needle-stick in OT).","Train all relevant staff on handling, minimising, and reporting each identified risk; maintain attendance records and post-training competency assessments per risk category.","Post risk management quick-reference cards in relevant work areas so staff have immediate guidance; assessors will check whether displayed information matches formal training content.","Review risk training records annually against the facility''s current risk register to ensure training remains relevant as new risks emerge or existing ones are mitigated."]'::jsonb where oe_code = 'HRM.3.b';
update public.shco_full_oes set achieve_tips = '["Create and display a laminated incident reporting flowchart at each nursing station and department showing the exact steps staff must follow within the first 30 minutes of an incident.","Train all staff during induction on incident reporting procedures including near-miss reporting, and verify understanding through a short written test with results filed in personnel records.","Conduct a quarterly incident reporting drill by simulating a scenario and timing how quickly and accurately staff respond — document drill results and debrief actions.","Assessors may ask frontline staff what they would do if they discovered a medication error — ensure every staff member can name the immediate steps without looking at a poster."]'::jsonb where oe_code = 'HRM.3.c';
update public.shco_full_oes set achieve_tips = '["Develop an Occupational Safety Training SOP covering topics such as manual handling, ergonomics, PPE usage, sharps disposal, and chemical handling relevant to each department.","Schedule occupational safety training at least once per year for all staff and maintain attendance registers cross-referenced with department risk profiles.","Issue and document PPE provision to every relevant staff member; keep a PPE issue register showing item type, staff name, date issued, and acknowledgement signature.","Assessors will observe PPE compliance during the site visit — conduct unannounced spot checks each month to ensure staff are wearing PPE correctly and document results."]'::jsonb where oe_code = 'HRM.3.d';
update public.shco_full_oes set achieve_tips = '["Incorporate disaster management plan training into annual mandatory training for all staff, covering roles during internal and external disasters with clear department-wise assignments.","Maintain signed attendance records for every disaster preparedness session and store them with the Disaster Management Plan so assessors can cross-reference training with the plan.","Assessors will observe mock disaster drills and may question staff on their assigned roles — conduct at least two drills per year and debrief outcomes in writing.","Post department-specific disaster response cards outlining staff roles, evacuation routes, and escalation contacts in visible locations so staff can act without delay during a real event."]'::jsonb where oe_code = 'HRM.3.e';
update public.shco_full_oes set achieve_tips = '["Schedule fire safety and non-fire emergency (e.g., gas leak, electrical failure, bomb threat) training for all staff twice a year, with separate sessions for day and night shifts.","Conduct fire evacuation drills at least twice annually, document participant numbers, evacuation time achieved, and corrective actions for any procedural gaps observed.","Assessors will question staff on their designated assembly point and the first step when a fire alarm sounds — hold monthly reminders so all shifts retain this knowledge.","Maintain a fire drill register and training attendance log; ensure records reflect participation from all departments including housekeeping, kitchen, and security, not just clinical staff."]'::jsonb where oe_code = 'HRM.3.f';
update public.shco_full_oes set achieve_tips = '["Develop a Quality Improvement (QI) training module explaining the hospital''s QI framework, quality indicators, and how staff contribute to improvements at the departmental level.","Include QI orientation in the induction programme and conduct annual refresher training; maintain attendance records linking each staff member to the QI training they attended.","Display the current quality indicators and their performance trend on a department quality board so staff see real data and connect their daily work to quality outcomes.","Assessors will check whether frontline staff can describe at least one quality indicator relevant to their department — quiz staff regularly during team meetings to reinforce this awareness."]'::jsonb where oe_code = 'HRM.3.g';
update public.shco_full_oes set achieve_tips = '["Develop a formal Performance Appraisal SOP that describes the appraisal format, rating scale, reviewer qualifications, and the timeline for conducting reviews for each staff category.","Include performance appraisal process information in the induction programme and have new hires sign an acknowledgement confirming they understand how and when they will be evaluated.","Maintain appraisal schedules in HR and send department heads a reminder 4 weeks before appraisal due dates so no staff member''s appraisal is overdue during an assessment visit.","Assessors will ask staff if they are aware of the appraisal system — hold brief departmental briefings after each appraisal cycle summarising outcomes and next steps for the team."]'::jsonb where oe_code = 'HRM.4.a';
update public.shco_full_oes set achieve_tips = '["Define measurable performance criteria for each job category in the appraisal form, including clinical quality metrics, attendance, teamwork, and compliance with hospital protocols.","Share the appraisal criteria document with each staff member at induction and annually before the appraisal cycle begins so there are no surprises during the evaluation.","Ensure appraisal forms are standardised across the organisation, with role-specific sections, and retain completed forms in personnel files for at least 3 years for audit readiness.","Assessors may ask staff how their performance is measured — ensure department heads can name specific criteria used and explain how they link to organisational quality goals."]'::jsonb where oe_code = 'HRM.4.b';
update public.shco_full_oes set achieve_tips = '["Following each appraisal cycle, document an Individual Development Plan (IDP) for every staff member identifying training needs, career goals, and actions agreed between the employee and supervisor.","Track IDP completion rates as an HR metric presented quarterly — measure the percentage of staff with an active development plan and the percentage who completed planned development activities.","Link training nominations to appraisal outcomes so staff with identified skill gaps are automatically enrolled in relevant programmes before the next performance cycle.","Assessors will look for evidence that appraisals lead to action — prepare a summary report showing how many staff improved on development goals from the prior year''s appraisal."]'::jsonb where oe_code = 'HRM.4.c';
update public.shco_full_oes set achieve_tips = '["Define in the appraisal policy the exact frequency of reviews (e.g., probationary at 3 months, annual thereafter) and document each review date in both the personnel file and a central HR tracker.","Ensure every completed appraisal form is signed by both the appraiser and the appraisee, dated, and filed in the personnel record within 7 days of the appraisal meeting.","Generate a monthly HR dashboard report showing percentage of appraisals completed on time versus overdue; escalate overdue cases to department heads for immediate resolution.","Assessors will request appraisal records during document review — organise personnel files so that the most recent appraisal is the first document visible for each staff member."]'::jsonb where oe_code = 'HRM.4.d';
update public.shco_full_oes set achieve_tips = '["Establish an Occupational Health SOP that defines how staff health hazards are identified, how at-risk employees are flagged, and what wellness interventions are available, approved by the Medical Director.","Maintain an occupational health register listing staff who have been assessed for health hazards, the hazard type, assessment date, and any preventive or corrective action taken.","Conduct annual health awareness sessions on common occupational risks (e.g., musculoskeletal disorders, burnout, bloodborne pathogen exposure) and document attendance in personnel files.","Assessors will check whether health hazard data is being used to inform workplace changes — present examples where staff health findings led to procedural or ergonomic improvements."]'::jsonb where oe_code = 'HRM.5.a';
update public.shco_full_oes set achieve_tips = '["Schedule annual health check-ups for all staff by category (clinical, administrative, housekeeping) and maintain a master health check register with staff name, designation, date, and outcome.","File individual health check reports in each staff member''s personnel file under a dedicated health section; ensure results are treated as confidential and accessible only to authorised HR personnel.","Assessors will verify health check records and may ask staff when their last check-up was — send reminders 30 days before each staff member''s annual check-up anniversary.","Act on health check findings by referring staff with identified conditions to appropriate care, documenting the referral and follow-up in the occupational health register."]'::jsonb where oe_code = 'HRM.5.b';
update public.shco_full_oes set achieve_tips = '["Develop a Workplace Injury Management SOP covering immediate first aid, incident reporting, treatment access, and return-to-work planning for staff injured during duty hours.","Maintain a workplace injury register with entries for each incident including date, nature of injury, treatment provided, days lost, and corrective action taken to prevent recurrence.","Ensure all injured staff receive treatment promptly without financial barrier, and document that treatment was provided free of cost as a matter of policy accessible in the SOP.","Assessors may ask staff what would happen if they got a needle-stick injury — conduct quarterly drills covering the exact steps from exposure to post-exposure prophylaxis documentation."]'::jsonb where oe_code = 'HRM.5.c';
update public.shco_full_oes set achieve_tips = '["Develop and approve a Workplace Violence Prevention Policy covering definitions of violence, reporting mechanisms, immediate support for affected staff, and zero-tolerance disciplinary consequences.","Install CCTV in high-risk areas such as emergency, psychiatry, and cash counters; display signage that workplace violence will not be tolerated and that surveillance is active.","Train all staff, especially frontline and emergency personnel, in de-escalation techniques and the immediate steps to take if threatened or assaulted; maintain training attendance records.","Assessors will observe whether violence prevention measures are visible and operational — hold quarterly reviews of all reported incidents and demonstrate trends and corrective actions to the assessment team."]'::jsonb where oe_code = 'HRM.5.d';
update public.shco_full_oes set achieve_tips = '["Assign every staff member a unique personnel file ID and maintain files in a locked cabinet or secured HR system accessible only to authorised personnel, with an access log.","Create a personnel file checklist that lists every mandatory document (appointment letter, ID proof, qualifications, signed JD, appraisals, training records) and verify completeness for every file quarterly.","Implement a file confidentiality policy signed by all HR staff handling personal records, and include this as part of HR induction so assessors see a culture of data privacy.","Assessors will request personnel files during document review — ensure files are organised with a standard section order so any document can be retrieved within 2 minutes."]'::jsonb where oe_code = 'HRM.6.a';
update public.shco_full_oes set achieve_tips = '["Use a personnel file index that mandates inclusion of: photo ID, educational certificates, registration proof, appointment letter, signed JD, credential verification report, and latest health check result.","Verify all credentials — degrees, registration numbers, and previous employment — at the time of joining and file the verification evidence alongside the original copies in the personnel file.","Assessors will cross-check qualifications listed in the file against primary source verifications — ensure every credential has an accompanying verified confirmation (letter, online printout, or third-party certificate).","Conduct a semi-annual personnel file audit using the mandatory document checklist; document the audit findings and close any gaps within 30 days with HR sign-off."]'::jsonb where oe_code = 'HRM.6.b';
update public.shco_full_oes set achieve_tips = '["Create a Training Record Sheet for each staff member that logs every in-service training attended, with date, topic, trainer, duration, and a copy of the attendance register or certificate.","File training records in a dedicated training section within each personnel file so assessors can see at a glance the complete training history of any staff member.","Maintain a centralised HR training register that mirrors individual file records and allows HR to run reports on any staff member''s training history within minutes.","Cross-reference training records against mandatory training requirements annually to identify gaps and generate a catch-up training plan before any NABH assessment visit."]'::jsonb where oe_code = 'HRM.6.c';
update public.shco_full_oes set achieve_tips = '["File every completed appraisal form, performance improvement plan, commendation letter, and disciplinary warning in a chronological evaluation section within each staff member''s personnel file.","Ensure all evaluation documents are signed by the appraiser, countersigned by the department head, and dated before filing so records are legally defensible and audit-ready.","Conduct an annual file review to verify that appraisal records are complete and that evaluations have been carried out at the correct frequency for every staff member.","Assessors will check whether evaluation records reflect continuity — prepare a summary sheet at the front of each file showing the dates and outcomes of all appraisals to date."]'::jsonb where oe_code = 'HRM.6.d';
update public.shco_full_oes set achieve_tips = '["Develop a Credentialing and Privileging SOP that defines which medical professional categories are permitted to practice independently, based on applicable law and regulatory requirements.","Maintain a Privileging Register listing every independently practising medical professional with their registration number, qualification, and the specific privileges granted by the competent authority.","Assessors will verify that every doctor providing unsupervised care is listed in the privileging register — audit the register quarterly and remove or update listings when scope of practice changes.","Display the list of credentialed medical professionals in relevant departments so nursing and support staff know who is authorised to issue orders without supervision."]'::jsonb where oe_code = 'HRM.7.a';
update public.shco_full_oes set achieve_tips = '["Collect certified copies of degrees, registration certificates, training completion records, and experience letters for every medical professional at joining, and verify them with the issuing body before granting privileges.","Set up calendar reminders for registration renewal dates of all medical professionals and initiate re-verification 60 days before expiry, documenting the outcome in the personnel file.","Maintain a credential verification log showing each verification action taken, the source contacted, date of verification, and the officer who completed it so the process is traceable.","Assessors will cross-check credentials with the registration council database during the visit — ensure all registration numbers are current and the most recent renewal certificates are filed."]'::jsonb where oe_code = 'HRM.7.b';
update public.shco_full_oes set achieve_tips = '["Define clinical privilege categories (e.g., surgical procedures, prescription authority, diagnostic interpretation) and formally document which privileges are granted to each medical professional based on their verified credentials.","Issue each medical professional a signed Privilege Letter specifying exactly what they are authorised to do within the organisation, filed in both the personnel file and the privilege register.","Assessors will test whether privileges match actual practice by reviewing patient records against the treating doctor''s privilege list — audit a sample of patient files quarterly.","Review and revalidate privileges at least annually or after any significant event (e.g., complaint, long absence, scope change) and document the revalidation outcome formally."]'::jsonb where oe_code = 'HRM.7.c';
update public.shco_full_oes set achieve_tips = '["Distribute a current and signed scope-of-services document to each medical professional on joining and share the same document with department heads and nursing in-charges of all relevant units.","Conduct a brief orientation for all departments when a new medical professional joins, covering the services that person is authorised to provide so referrals and orders are appropriate.","Maintain signed acknowledgement from both the medical professional and relevant department heads confirming they have received and understood the scope-of-services document.","Assessors may ask nursing staff what services a particular doctor is authorised to provide — hold quarterly clinical team briefings reviewing any changes to medical professional scopes."]'::jsonb where oe_code = 'HRM.7.d';
update public.shco_full_oes set achieve_tips = '["Maintain a Nursing Privileging Register listing all nurses authorised to provide unsupervised patient care, with their registration council number, qualification level, and date of privilege grant.","Review the nursing privilege register whenever a nurse is promoted, changes unit, or completes additional qualification training, and update privileges in writing within 7 days.","Assessors will observe nursing staff performing care activities and cross-check against the privilege register — ensure every nurse on the floor is listed and that their listed privileges cover their observed duties.","Post a current list of independently practising nurses in each ward so charge nurses and doctors can quickly verify who is authorised to carry out specific care tasks unsupervised."]'::jsonb where oe_code = 'HRM.8.a';
update public.shco_full_oes set achieve_tips = '["At the time of joining, collect and verify educational certificates, nursing council registration, and prior employment letters for every nurse, and file original verification evidence in their personnel file.","Set up a registration renewal tracker for all nursing staff; initiate re-verification 60 days before a registration expires and document the updated certificate in the file immediately on receipt.","Maintain a nursing credential summary sheet in each file listing qualification, registration number, registration validity, and date last verified so assessors can confirm status at a glance.","Conduct a bi-annual credential audit for all nursing staff, comparing file records against the State Nursing Council database and correcting any discrepancies within 15 days."]'::jsonb where oe_code = 'HRM.8.b';
update public.shco_full_oes set achieve_tips = '["Define nursing privilege tiers (e.g., basic care, IV administration, triage assessment) and document in writing which tier each nurse is assigned based on their verified qualifications and experience.","Issue a signed Nursing Privilege Certificate to each nurse specifying authorised activities; retain a copy in the personnel file and the nursing privilege register.","Review nursing privileges whenever a nurse attends additional training or a new competency is assessed; update the privilege document within 7 days and obtain a new signature from the authorising authority.","Assessors will ask nurses what procedures they are and are not authorised to perform — conduct quarterly privilege awareness sessions so nurses can articulate their scope confidently."]'::jsonb where oe_code = 'HRM.8.c';
update public.shco_full_oes set achieve_tips = '["Issue each nurse a written scope-of-services document at joining detailing their authorised nursing activities, and share a department-level summary with the in-charge of every unit the nurse is deployed to.","Conduct a ward-level orientation whenever a nurse is transferred to a new department, briefing both the nurse and the receiving team on the nurse''s authorised services and any limitations.","Maintain signed acknowledgement records from both the nurse and the receiving department in-charge confirming that scope-of-services information has been communicated and understood.","Assessors will interview ward in-charges to verify they know which nurses under their supervision are authorised for specific tasks — hold monthly team briefings reviewing scope boundaries."]'::jsonb where oe_code = 'HRM.8.d';
update public.shco_full_oes set achieve_tips = '["Map all para-clinical roles (e.g., physiotherapists, radiographers, lab technicians, dietitians) against the applicable regulatory requirements to determine who may practice independently, and document this formally.","Maintain a Para-Clinical Privileging Register listing each authorised professional with their regulatory body registration number, qualification, scope of practice, and date of privilege grant.","Assessors will verify that para-clinical staff performing unsupervised procedures are listed in the privilege register — audit the register quarterly and remove anyone whose registration has lapsed.","Communicate the privileging process to all para-clinical department heads and ensure that only registered, credentialed staff are assigned to perform procedures that require independent authorisation."]'::jsonb where oe_code = 'HRM.9.a';
update public.shco_full_oes set achieve_tips = '["Collect degree certificates, regulatory registration documents, training records, and experience letters for every para-clinical professional at joining and verify authenticity with the issuing institution or council.","Create a Para-Clinical Credential Tracker spreadsheet with columns for staff name, qualification, registration number, validity date, verification date, and re-verification due date; update it continuously.","File all verification evidence in each professional''s personnel file with a cover sheet summarising credential status so assessors can complete a document review of any file within 5 minutes.","Conduct annual re-verification of all para-clinical registrations and document outcomes; treat lapsed registrations as a critical non-conformity requiring immediate suspension of independent practice."]'::jsonb where oe_code = 'HRM.9.b';
update public.shco_full_oes set achieve_tips = '["Define specific clinical privileges for each para-clinical category based on verified qualifications and regulatory scope (e.g., a physiotherapist may perform mobilisation but not prescribe medication), and document formally.","Issue a signed Privilege Letter to every para-clinical professional listing their authorised activities; retain copies in both the personnel file and a central para-clinical privilege register.","Assessors will check patient care records against assigned privileges — perform quarterly audits of para-clinical documentation to confirm that procedures recorded match the privileges granted.","Reassess privileges whenever a para-clinical professional completes additional specialisation or changes role, updating the Privilege Letter and register within 7 days of the change."]'::jsonb where oe_code = 'HRM.9.c';
update public.shco_full_oes set achieve_tips = '["Distribute a written scope-of-services summary to each para-clinical professional on joining and share the same document with the head of every department that interacts with or requests their services.","Conduct a brief orientation for referring departments each time a new para-clinical professional joins, clearly communicating what services that person is authorised to provide.","Maintain signed acknowledgement records from the para-clinical professional and all relevant department heads confirming receipt and understanding of the scope-of-services document.","Assessors will ask clinical staff whether they know what services a para-clinical colleague is authorised to deliver — hold cross-departmental briefings at least annually to refresh this knowledge."]'::jsonb where oe_code = 'HRM.9.d';

-- IMS (30 OEs)
update public.shco_full_oes set achieve_tips = '["Conduct a stakeholder mapping exercise to list all information users — patients, visitors, nursing staff, management, lab, and external agencies — and document what specific information each group requires from the hospital system.","Display key information such as service timings, visiting hours, rights and responsibilities, and emergency contacts on notice boards in all patient-facing areas, and maintain a record of updates made each quarter.","During assessor visits, staff must be able to explain verbally which information channels are used for different stakeholder groups and demonstrate at least one recent example of information dissemination to the community.","Review the information needs register at least twice a year, update it based on feedback from patients and staff, and keep signed records of each review meeting to show assessors during audit."]'::jsonb where oe_code = 'IMS.1.a';
update public.shco_full_oes set achieve_tips = '["Prepare a written Information Management and Technology Plan that maps each identified stakeholder information need to a specific tool, software module, or manual process used to fulfil it, and get it approved by management.","Include IT hardware and software procurement decisions in the annual planning cycle and document how each acquisition addresses a documented information gap identified in the stakeholder needs assessment.","Maintain a maintenance log for all IT systems and medical equipment used for data capture, recording dates of servicing, software updates, and any downtime incidents to demonstrate proactive upkeep.","Train the IT in-charge and department heads on the technology plan annually, document attendance, and ensure staff can explain to assessors how the plan aligns with operational information needs."]'::jsonb where oe_code = 'IMS.1.b';
update public.shco_full_oes set achieve_tips = '["Establish a written SOP for data storage covering physical records (MRD filing system) and digital records (HIS or EMR), specifying folder structures, naming conventions, backup frequency, and authorized access levels.","Implement a retrieval turnaround time standard — for example, any requested medical record must be available within 30 minutes during working hours — and log every retrieval request with time-in and time-out to measure compliance.","Conduct quarterly drills where MRD staff retrieve a sample of 10 records and document retrieval times, flagging and correcting delays to demonstrate continuous improvement to assessors.","Train all MRD staff on the storage and retrieval SOP, maintain signed training attendance sheets, and ensure staff can demonstrate the retrieval process step by step when asked during assessment."]'::jsonb where oe_code = 'IMS.1.c';
update public.shco_full_oes set achieve_tips = '["Identify all external databases and regulatory reporting obligations applicable to your hospital — such as birth and death reporting, notifiable disease registers, and PCPNDT records — and create a compliance calendar with monthly submission deadlines.","Designate a responsible officer for each external reporting requirement, document their name and role in the compliance calendar, and ensure they are aware of the legal timelines and formats required.","Maintain copies of all submissions made to external agencies, including acknowledgement receipts or submission confirmation, filed chronologically to show assessors a complete trail of regulatory compliance.","Conduct an internal audit every six months to verify that all mandatory external submissions were made on time, document findings, and take corrective action for any missed or delayed submission."]'::jsonb where oe_code = 'IMS.1.d';
update public.shco_full_oes set achieve_tips = '["Standardize all data collection forms — OPD registers, IPD admission forms, discharge summaries, and lab request slips — using pre-approved templates with clear field definitions, and withdraw all outdated formats from use.","Implement a monthly data analysis routine where the MRD team compiles key indicators such as bed occupancy, average length of stay, readmission rates, and infection counts and shares a summary report with department heads.","Create a standard data dictionary that defines each data element collected across departments, ensuring consistent interpretation, and make it accessible to all data entry staff and MRD personnel.","Retain monthly data analysis reports with evidence of distribution to management, and ensure the person responsible can explain the analysis methodology and findings clearly during an assessor interview."]'::jsonb where oe_code = 'IMS.1.e';
update public.shco_full_oes set achieve_tips = '["Implement a Hospital Registration Number (HRN) or UHID system that assigns a single unique identifier to every patient at first registration, ensuring no duplicate numbers exist across OPD, IPD, emergency, and diagnostic records.","Display the unique identifier prominently on every medical record folder, wristband, prescription, lab report, and discharge summary so staff can cross-reference documents quickly and accurately.","Train registration staff and ward clerks on the importance of searching for an existing UHID before assigning a new one, and maintain a register of any duplicate detections and how they were merged and resolved.","During assessor observation, staff should be able to demonstrate the registration process live, show how the UHID is assigned, and produce any patient''s complete record using only the unique identifier as the search key."]'::jsonb where oe_code = 'IMS.2.a';
update public.shco_full_oes set achieve_tips = '["Define and document the minimum required contents of a medical record in your hospital''s medical records policy, including patient demographics, consent forms, clinical notes, investigation reports, nursing records, and discharge summary.","Conduct a monthly completeness audit of at least 20 randomly selected medical records using a checklist, score each record, and display the compliance percentage on the quality dashboard for all departments to review.","Ensure all entries in the medical record are made in chronological order with clear dates and times, and train clinical staff to complete missing entries within 24 hours of the care event, not retrospectively during discharge.","During assessor review, selected medical records must demonstrate a complete, logical, and time-sequenced account of care — staff must be able to narrate the patient journey using only the record without additional verbal explanation."]'::jsonb where oe_code = 'IMS.2.b';
update public.shco_full_oes set achieve_tips = '["Maintain a current list of all authorized medical record entry personnel — doctors, nurses, physiotherapists, and dieticians — with their designations and specimen signatures filed in the MRD and updated whenever staff join or leave.","Implement a policy that only credentialed and privileged staff may write orders or clinical notes in the medical record; ward supervisors must verify this during every shift handover and document any violations.","Spot-check 10 records monthly to confirm that every entry can be traced to an identified author through a legible name stamp, signature, or unique digital login identifier, and record audit findings with follow-up actions.","Assessors will interview nursing and medical staff to verify they understand who is authorized to make entries; ensure all staff can answer this question correctly and point to the authorization list without hesitation."]'::jsonb where oe_code = 'IMS.2.c';
update public.shco_full_oes set achieve_tips = '["Issue personalized rubber name stamps to all doctors and ensure every clinical note, prescription, and order in the medical record includes the author''s name stamp, signature, date, and time of entry as a non-negotiable standard.","Train all clinical staff during induction that incomplete entries — missing date, time, or signature — are non-compliant, and include this requirement in the annual clinical competency refresher with a post-training checklist sign-off.","Include name-date-time completeness as a specific parameter in monthly medical record audits; any record with more than two incomplete entries should trigger a corrective action memo to the concerned department head.","Display a one-page reminder poster at each nursing station and doctors'' writing desk showing the mandatory entry format: Name | Designation | Signature | Date (DD/MM/YYYY) | Time (HH:MM), so staff have a constant visual reference."]'::jsonb where oe_code = 'IMS.2.d';
update public.shco_full_oes set achieve_tips = '["Prepare and circulate a hospital-approved abbreviation list, ensuring it is available at every nursing station, doctors'' area, and the MRD; remove all unapproved abbreviations from templates and forms immediately.","Incorporate a section in staff orientation and annual refresher training that specifically covers approved versus prohibited abbreviations, with examples of dangerous abbreviations (such as U for units or IU for international units) that must never be used.","During monthly medical record audits, flag any entry containing an unapproved abbreviation, report it to the concerned department head, and track whether the same abbreviation recurs the following month as a trend indicator.","Post the approved abbreviation list prominently in clinical areas and ensure assessors can find it easily; staff must be able to locate the list immediately and explain how they were trained on its use."]'::jsonb where oe_code = 'IMS.2.e';
update public.shco_full_oes set achieve_tips = '["Ensure the medical record''s admission sheet is completed within two hours of patient arrival, documenting the reason for admission, provisional or confirmed diagnosis, and an initial plan of care signed by the admitting doctor.","Create a structured admission note template that prompts clinicians to fill in chief complaint, history of present illness, provisional diagnosis, and immediate management plan, leaving no field blank before the patient is shifted to the ward.","Conduct weekly spot-checks on five recently admitted patients'' records to verify that reason for admission, diagnosis, and care plan are documented before any investigations or treatments are initiated, and record audit findings.","Train junior doctors and residents during departmental orientation that incomplete admission notes are a patient safety and compliance risk; demonstrate a correctly completed admission note as the benchmark during training sessions."]'::jsonb where oe_code = 'IMS.3.a';
update public.shco_full_oes set achieve_tips = '["Develop department-specific medical record templates that include dedicated sections for initial assessment, daily re-assessments, specialist consultation notes, investigation results, and procedure notes so no element is inadvertently omitted.","Establish a policy that investigation reports — lab, radiology, ECG — must be pasted or attached to the medical record within four hours of receipt, with the treating doctor''s acknowledgement signature on each report.","Ensure nursing staff document re-assessments at each shift using structured SOAP or narrative notes, and include vital signs, pain scores, and any change in patient condition with exact time of observation recorded.","During assessor review, pull three active patient records at random and verify they contain all required elements; department heads should rehearse this exercise monthly so clinical staff are always audit-ready."]'::jsonb where oe_code = 'IMS.3.b';
update public.shco_full_oes set achieve_tips = '["Create a standardized inter-hospital transfer form that captures the reason for transfer, patient''s condition at time of transfer, treatment given, pending investigations, and the receiving facility''s name, and attach it to every transferred patient''s record.","Obtain the patient''s or family''s written consent for transfer, attach the signed consent to the medical record, and ensure the transfer note is co-signed by the attending doctor and a nurse who was present at the time of transfer.","Train charge nurses and on-call doctors on the transfer documentation protocol during departmental meetings, covering what must be documented before the patient leaves the premises, and conduct a mock drill twice a year.","Maintain a transfer register in the ward and emergency department that logs all transfers out, cross-referenced with the medical record number so assessors can quickly trace any transfer case and verify documentation completeness."]'::jsonb where oe_code = 'IMS.3.c';
update public.shco_full_oes set achieve_tips = '["Implement a policy that the discharge summary must be completed and signed by the treating doctor within 24 hours of patient discharge, with a copy placed inside the medical record and another given to the patient.","Use a structured discharge summary template that covers diagnosis, procedures performed, treatment given, condition at discharge, follow-up instructions, and medications prescribed so no key element is missed.","Conduct a monthly completeness audit of all discharge summaries filed in the previous month, scoring completeness against the template, and share results with treating doctors and department heads for improvement.","Ensure staff in the MRD can quickly retrieve any discharge summary by patient UHID and that assessors are shown a sample of discharge summaries during audit that demonstrate legibility, completeness, and timely filing."]'::jsonb where oe_code = 'IMS.3.d';
update public.shco_full_oes set achieve_tips = '["Establish a policy that in every case of in-hospital death, the cause of death certificate must be issued by the treating or on-call doctor and a copy filed in the medical record before the body is handed over.","Create a dedicated section in the medical record folder labelled ''Death Documentation'' where the cause of death certificate, time of death note, and information given to relatives are all filed together for easy retrieval.","Train all doctors and ward staff on the death documentation process during induction, including the legal requirement to issue a cause of death certificate and the hospital''s responsibility to maintain a copy in the record.","Maintain a death register in the MRD cross-referenced with medical record numbers, and ensure assessors can retrieve any death case file and find the cause of death certificate filed accurately within two minutes."]'::jsonb where oe_code = 'IMS.3.e';
update public.shco_full_oes set achieve_tips = '["Implement a role-based access control policy in your HIS or manual record system that allows treating doctors, nurses, and allied health staff to access only the records of patients currently under their care, and document the access matrix.","Ensure that past medical records of returning patients are available to the treating team within 30 minutes of a new admission or OPD visit; log retrieval requests and response times to demonstrate consistent access to historical data.","Establish a process for emergency access to records outside working hours, designating an on-call MRD contact or HIS administrator who can retrieve previous records when needed, and document this process in a written SOP.","During assessor interviews, clinical staff must be able to explain how they access a past record for a readmitted patient and demonstrate the retrieval process; conduct mock access drills quarterly to keep all staff familiar with the procedure."]'::jsonb where oe_code = 'IMS.3.f';
update public.shco_full_oes set achieve_tips = '["Implement a written confidentiality policy signed by every staff member at joining, making explicit that patient information — verbal, written, or digital — must not be disclosed to unauthorized persons under any circumstances.","Restrict access to patient files in the MRD to authorized personnel only; keep the MRD door locked when unattended and maintain a visitor entry log to record every person who accesses the record storage area.","Conduct quarterly confidentiality awareness sessions for all clinical and non-clinical staff covering real-world scenarios — such as family members asking for diagnosis details — and document attendance to show assessors during audit.","During assessor interviews, staff must demonstrate knowledge of the confidentiality policy, explain what they would do if asked for patient information by an unauthorized person, and locate the signed confidentiality agreement in their personnel file."]'::jsonb where oe_code = 'IMS.4.a';
update public.shco_full_oes set achieve_tips = '["Establish a policy that no entry in the medical record may be erased, overwritten with correction fluid, or obscured; errors must be crossed out with a single line, marked ''error,'' and initialled with the date so the original entry remains readable.","For digital records, configure the HIS to maintain a complete audit trail of all entries, modifications, and deletions with user ID, timestamp, and reason for change — ensure this audit log is reviewed monthly by the IT or quality team.","Train all clinical staff that altering a medical record entry improperly is a serious violation with legal implications; include a case-based scenario on record integrity in the annual medical ethics and compliance training.","During assessor review of records, demonstrate that correction entries are made correctly with visible original text, initials, and date — pull sample records from the past quarter to show consistent compliance across departments."]'::jsonb where oe_code = 'IMS.4.b';
update public.shco_full_oes set achieve_tips = '["Implement password-protected user accounts for all HIS or digital data systems with a policy requiring password changes every 90 days; disable accounts of staff who have left within 24 hours of their departure.","Secure physical medical record storage by fitting MRD shelving with locked bays for sensitive records, installing CCTV coverage of the MRD area, and maintaining a movement register for every record taken out of storage.","Back up all digital data automatically every day to a secure off-site or cloud location, maintain a backup log with dates and verification status, and test data restoration from backup at least once every six months.","Assessors will look for evidence of physical and digital security controls; ensure the MRD in-charge can demonstrate the locking system, access log, and HIS user management screen without prior preparation during an unannounced visit."]'::jsonb where oe_code = 'IMS.4.c';
update public.shco_full_oes set achieve_tips = '["Develop a written SOP on disclosure of health information covering the three permissible scenarios: patient''s own written request, authorized representative''s request, and mandatory legal or regulatory disclosure, with a separate form for each.","Maintain a Disclosure Register that records every instance of information release — date, requestor name, nature of information disclosed, legal basis for disclosure, and the authorizing officer''s signature — and file it in the MRD.","Train front desk staff, MRD personnel, and nursing staff on how to handle requests for patient information, emphasizing that verbal disclosure over the phone is never permitted without written authorization and documented identity verification.","During assessor interviews, MRD and reception staff must be able to walk through the disclosure process step by step; demonstrate a completed disclosure request form and its corresponding register entry as a concrete example."]'::jsonb where oe_code = 'IMS.4.d';
update public.shco_full_oes set achieve_tips = '["Create a Record Access Request Form that patients, doctors, and external agencies must complete when requesting copies of or access to medical records, specifying the purpose, records required, and identity proof provided.","Establish a turnaround time standard for access requests — for example, patient requests fulfilled within 48 hours and medico-legal requests within 72 hours — and log every request with receipt date, due date, and date fulfilled.","Designate the MRD in-charge as the single point of contact for all access requests and ensure they are trained on patient rights, medico-legal obligations, and data protection, with a documented annual training record.","Conduct a quarterly review of the access request log to identify any requests that exceeded the turnaround time, document root cause analysis for delays, and implement corrective actions before the next NABH assessment cycle."]'::jsonb where oe_code = 'IMS.4.e';
update public.shco_full_oes set achieve_tips = '["Establish a document control system with a Document Master List that records the document name, version number, effective date, review date, and document owner for every policy, SOP, and form in use across the hospital.","Ensure all documents in circulation bear the current version number and review date on the header or footer; collect and destroy or archive all superseded versions immediately upon release of an updated document.","Assign a Document Controller role — typically the Quality Manager — who is responsible for approving, distributing, and withdrawing documents; no document should be issued or updated without this person''s sign-off.","During assessor observation, pick any clinical area at random and verify that all displayed SOPs and forms match the current version in the Document Master List; staff must be able to explain who updates documents and how old versions are removed."]'::jsonb where oe_code = 'IMS.5.a';
update public.shco_full_oes set achieve_tips = '["Document the hospital''s medical record retention policy specifying minimum retention periods — for example, adult records for five years post-discharge, paediatric records until the patient turns 21, and medico-legal records for longer as required by applicable law.","Maintain a retention schedule table in the MRD that lists all record types (OPD, IPD, ICU, emergency, lab, radiology, pharmacy) alongside their mandated retention period and the date after which each batch may be considered for archiving or disposal.","Physically label archived record boxes with the date range, retention deadline, and disposal authorization date, and store them in a dry, pest-free space with a location index so any record can be retrieved quickly even years after discharge.","During assessor review, demonstrate the retention schedule, pull a record from five or more years ago to show it is intact and retrievable, and confirm that no record within its retention period has been disposed of without authorization."]'::jsonb where oe_code = 'IMS.5.b';
update public.shco_full_oes set achieve_tips = '["Develop an SOP for record retention that includes physical security measures: locked storage rooms, climate and humidity controls where feasible, restricted access lists, and periodic inspection records for the storage area.","Ensure that all archived patient records are stored in sealed, labelled boxes with no patient identifiers visible on the outside, and that the storage area is accessible only to authorized MRD personnel with a key register maintained.","For digital archives, ensure that backups are encrypted, stored on secure servers, and access-protected so that retained data cannot be read, altered, or deleted by unauthorized users, with access logs reviewed quarterly.","Train MRD staff and the IT team on the confidentiality obligations that extend to retained records — the fact that a record is archived does not reduce the obligation to protect it — and document this training in staff records."]'::jsonb where oe_code = 'IMS.5.c';
update public.shco_full_oes set achieve_tips = '["Write a Medical Record Destruction Policy that defines who may authorize destruction, which records are eligible (past their retention period), the approved destruction method (shredding for paper, certified wiping for digital), and how destruction is documented.","Maintain a Destruction Register that records the UHID range or document batch, retention period end date, date of destruction, method used, quantity, and the signature of the authorizing officer and the person who carried out the destruction.","Use a third-party certified shredding service for bulk destruction of paper records and obtain a destruction certificate from the vendor to file alongside the Destruction Register as dual evidence of compliant disposal.","Conduct a pre-destruction review with the Medical Superintendent or Quality Head to confirm no record in the batch is subject to pending litigation, insurance query, or regulatory hold before authorizing destruction, and document this clearance check."]'::jsonb where oe_code = 'IMS.5.d';
update public.shco_full_oes set achieve_tips = '["Establish a Medical Records Committee or designate the Quality Team to conduct formal medical record audits at a defined frequency — at minimum monthly — using a standardized checklist covering completeness, legibility, timeliness, and correct filing.","Maintain a Medical Record Review Register that logs each review cycle: date conducted, number of records reviewed, audit scores, deficiencies identified, and the corrective actions raised with responsible departments.","During assessor visits, present the last three months of review registers and demonstrate the trend of completeness scores improving over time; assessors specifically look for evidence that reviews happen regularly and are not just conducted before accreditation.","Use the findings from periodic reviews to update staff training content — if a recurring deficiency is found in a specific documentation element, add a focused module on that element in the next departmental CME or in-service training session."]'::jsonb where oe_code = 'IMS.6.a';
update public.shco_full_oes set achieve_tips = '["Apply a statistically valid sampling method for record reviews — for example, using a random number table or HIS-generated random UHID list — to select records from both currently admitted patients and those discharged in the review period.","Document the sample selection methodology in the Medical Records Committee minutes, specifying the total patient population, sample size formula used, and how active and discharged records are proportionally represented in each review cycle.","Ensure the sample includes records from different departments, age groups, and lengths of stay to get a representative cross-section of documentation quality across the hospital, not just from the best-performing wards.","Train the Quality or MRD team on basic statistical sampling concepts so they can explain the selection rationale to assessors; keep a sampling log showing how many active versus discharged records were reviewed in each monthly cycle."]'::jsonb where oe_code = 'IMS.6.b';
update public.shco_full_oes set achieve_tips = '["Formally designate the members of the Medical Records Review Committee by name and designation in a written order signed by the Medical Superintendent, including at least one clinician, one nursing representative, and the MRD in-charge.","Maintain attendance records for every review session to demonstrate that the designated individuals are consistently conducting the reviews and that the process is not delegated informally to junior staff without committee oversight.","Rotate the clinical reviewer role across departments periodically — for example, have the Surgery department lead one month and Medicine the next — so that different specialties gain ownership of documentation quality across the hospital.","Assessors will ask who conducts the medical record review; ensure the designated committee members can describe their role, the review frequency, and the most recent findings without needing to consult documents during the interview."]'::jsonb where oe_code = 'IMS.6.c';
update public.shco_full_oes set achieve_tips = '["Define a set of measurable review parameters in the Medical Records Committee charter — such as completeness of discharge summary, timeliness of operation notes, presence of consent forms, legibility of entries, and use of only approved abbreviations.","Create a scoring checklist with one row per parameter, a yes/no or percentage score column, and a comments column; use the same checklist every month so trend data is comparable across review cycles.","Share the parameter-wise scores with department heads after each review, highlighting the top three deficiencies, and require each head to submit a written corrective action plan within one week of receiving the report.","Display a monthly dashboard in the MRD and quality board showing the trend of each review parameter over the last six months; this visual evidence demonstrates ongoing monitoring and is highly effective during assessor walkthroughs."]'::jsonb where oe_code = 'IMS.6.d';
update public.shco_full_oes set achieve_tips = '["Log every deficiency identified during medical record reviews in a Corrective Action Tracker with columns for deficiency description, responsible department, action to be taken, target date, and closure status reviewed at the next committee meeting.","For recurring deficiencies, escalate from individual feedback to systemic correction — for example, if missing consent forms are found repeatedly, revise the admission checklist so consent is obtained before the patient enters the ward.","Follow up on each corrective action within 30 days by re-auditing the same parameter in the concerned department to verify whether the action was implemented and effective, and document the follow-up findings in the tracker.","Present the Corrective Action Tracker to assessors as primary evidence of a closed-loop improvement process; assessors specifically look for proof that identified gaps are not just noted but actually resolved with measurable impact on documentation quality."]'::jsonb where oe_code = 'IMS.6.e';

